            "Purchase Analytics":

                "تحليلات المشتريات",



            "Purchase Invoice Trends":

                "اتجاهات فواتير المشتريات"



        };





        var reports = {



            "Purchase Order Analysis":

                true,



            "Purchase Analytics":

                true,



            "Purchase Invoice Trends":

                true



        };





        var trees = {



            "Supplier Group":

                true



        };





        function translate(name) {



            if (!isArabic) {

                return name;

            }



            return (

                translations[name] ||

                name

            );



        }





        function navigate(name) {



            if (

                reports[name]

            ) {



                openReport(

                    name

                );



                return;



            }





            if (

                trees[name]

            ) {



                openTree(

                    name

                );



                return;



            }





            openList(

                name

            );



        }





        var cardsHtml = "";





        for (

            var c = 0;

            c < cards.length;

            c++

        ) {



            var card =

                cards[c];





            var linksHtml = "";





            for (

                var j = 0;

                j < card.links.length;

                j++

            ) {



                var name =

                    card.links[j];





                var details = "";





                /*

                 * بدون شرح للتقارير والإعدادات

                 */



                if (

                    !reports[name] &&

                    name !== "Buying Settings" &&

                    descriptions[name]

                ) {



                    details =



                        '<button ' +

                        'type="button" ' +

                        'class="erp-info-link" ' +

                        'data-buy-info="' +

                        escapeHtml(name) +

                        '">' +



                            text(

                                "تفاصيل",

                                "Details"

                            ) +



                        '</button>';



                }





                linksHtml +=



                    '<div class="erp-link-row">' +



                        '<button ' +

                        'type="button" ' +

                        'class="erp-link" ' +

                        'data-buy-card="' +

                        c +

                        '" ' +

                        'data-buy-link="' +

                        j +

                        '">' +



                            '<span class="erp-link-text">' +



                                escapeHtml(

                                    translate(name)

                                ) +



                            '</span>' +



                            '<span class="erp-link-arrow">' +



                                (

                                    isArabic

                                        ? "←"

                                        : "→"

                                ) +



                            '</span>' +



                        '</button>' +



                        details +



                    '</div>';



            }





            cardsHtml +=



                '<article class="erp-card tone-' +

                (c % 5) +

                '" data-buy-card-container>' +



                    '<button class="erp-card-heading" data-buy-card-toggle>' +



                        '<span class="erp-icon">' +

                            card.icon +

                        '</span>' +



                        '<span class="erp-card-title">' +



                            escapeHtml(

