                        "Masters & Reports"

                    ) +



                '</h2>' +



                '<div class="erp-dashboard-grid">' +

                    cardsHtml +

                '</div>' +



            '</section>';





        content.addEventListener(

            "click",

            function (event) {





                var info =

                    event.target.closest(

                        "[data-buy-info]"

                    );





                if (info) {



                    event.preventDefault();

                    event.stopPropagation();





                    showDetails(

                        info.getAttribute(

                            "data-buy-info"

                        )

                    );



                    return;

                }





                var link =

                    event.target.closest(

                        "[data-buy-link]"

                    );





                if (link) {



                    var cardIndex =

                        parseInt(

                            link.getAttribute(

                                "data-buy-card"

                            ),

                            10

                        );





                    var linkIndex =

                        parseInt(

                            link.getAttribute(

                                "data-buy-link"

                            ),

                            10

                        );





                    var name =

                        cards[

                            cardIndex

                        ].links[

                            linkIndex

                        ];





                    navigate(

                        name

                    );



                    return;

                }





                var toggle =

                    event.target.closest(

                        "[data-buy-card-toggle]"

                    );





                if (!toggle) {

                    return;

                }





                var selected =

                    toggle.closest(

                        "[data-buy-card-container]"

                    );





                if (!selected) {

                    return;

                }





                var shouldOpen =

                    !selected.classList.contains(

                        "is-open"

                    );





                var all =

                    content.querySelectorAll(

                        "[data-buy-card-container]"

                    );





                for (

                    var x = 0;

                    x < all.length;

                    x++

                ) {



                    if (

                        all[x] !== selected

                    ) {



                        all[x]

                            .classList

                            .remove(

                                "is-open"

                            );



                    }



                }





                selected.classList.toggle(

                    "is-open",

                    shouldOpen

                );



            }

        );





        /* =================================================

           6. FOOTER

        ================================================= */



        if (footerEl) {



            footerEl.innerHTML =



                '<div class="erp-footer-inner">' +



                    '<div class="erp-footer-item">' +



                        '<span class="erp-footer-icon">☎</span>' +



