  padding: 0;



  border: 0;

  border-bottom:

    1px solid transparent;



  outline: none;



  background:

    transparent;



  color:

    var(--brand-text) !important;



  font-family: inherit;



  text-align: inherit;



  cursor: pointer;



  transition:

    border-color 0.22s ease,

    margin-bottom 0.22s ease;

}





.erp-card.is-open

.erp-card-heading {



  margin-bottom: 10px;



  border-bottom-color:

    var(--brand-border);

}











/* =========================================================

   29. CARD ICON

========================================================= */



.erp-icon {



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 34px;

  height: 34px;



  flex:

    0 0 34px;



  border-radius:

    9px;



  background:

    var(--erp-soft);



  font-size:

    17px;

}





/* =========================================================

   30. CARD TITLE

========================================================= */



.erp-card-title,

.erp-card .erp-card-title {



  flex: 1;



  min-width: 0;



  color:

    var(--brand-text) !important;



  font-size:

    16px;



  font-weight:

    800;



  line-height:

    1.5;

}





/* =========================================================

   31. CARD CHEVRON

========================================================= */



.erp-card-chevron {



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 28px;

  height: 28px;



  flex:

    0 0 28px;



  border-radius:

    8px;



  background:

    var(--erp-soft);



  color:

    var(--erp-accent) !important;



  font-size:

    17px;



  transition:

    transform 0.22s ease;

}





.erp-card.is-open

.erp-card-chevron {



  transform:

    rotate(180deg);

}











/* =========================================================

   32. CARD LINKS

========================================================= */



.erp-card-links {



  position: relative;



  z-index: 2;



  display: grid;



  gap: 5px;



  max-height: 0;



  margin: 0;

  padding: 0;



  overflow: hidden;



  opacity: 0;

  visibility: hidden;



  pointer-events: none;



  transform:

    translateY(-8px);



  transition:

    max-height 0.38s ease,

    opacity 0.2s ease,

    visibility 0.2s ease,

    transform 0.28s ease;

}





.erp-card.is-open

.erp-card-links {



  max-height: 480px;



  overflow-y: auto;



  opacity: 1;

  visibility: visible;



  pointer-events: auto;



  transform:

    translateY(0);

}











/* =========================================================

   33. LINK ROW

========================================================= */



.erp-link-row {



  display: flex;



  align-items: center;



  gap: 6px;



  width: 100%;

}





/* =========================================================

   34. CARD LINK

========================================================= */



.erp-link {



  display: flex;



  align-items: center;



  gap: 7px;



  flex: 1;



  min-width: 0;

  min-height: 36px;



  padding:

    7px 10px;



  border:

    1px solid transparent;



  border-radius:

    8px;



  outline: none;



  background:

    transparent;



  color:

    var(--brand-text) !important;



  font-family: inherit;



  font-size:

    13px;



  font-weight:

    500;



  line-height:

    1.45;



  text-align:

    inherit;



  cursor: pointer;



  transition:

    background 0.16s ease,

    color 0.16s ease,

    border-color 0.16s ease,

    transform 0.16s ease;

}





.erp-link-text {



  flex: 1;



  min-width: 0;



  color:

