  transition:

    max-height 0.38s ease,

    opacity 0.2s ease,

    visibility 0.2s ease,

    transform 0.28s ease;

}





.erp-card.is-open

.erp-card-links {



  max-height: 480px;



  overflow-y: auto;



  opacity: 1;

  visibility: visible;



  pointer-events: auto;



  transform:

    translateY(0);

}











/* =========================================================

   33. LINK ROW

========================================================= */



.erp-link-row {



  display: flex;



  align-items: center;



  gap: 6px;



  width: 100%;

}





/* =========================================================

   34. CARD LINK

========================================================= */



.erp-link {



  display: flex;



  align-items: center;



  gap: 7px;



  flex: 1;



  min-width: 0;

  min-height: 36px;



  padding:

    7px 10px;



  border:

    1px solid transparent;



  border-radius:

    8px;



  outline: none;



