    inherit;



  font-size:

    12.5px;



  font-weight:

    700;



  cursor:

    pointer;

}





.erp-modal-toggle-steps:hover {



  background:

    rgba(56, 103, 174, 0.13);

}





/* =========================================================

   44. MODAL STEPS

========================================================= */



.erp-modal-steps {



  max-height: 0;



  overflow: hidden;



  opacity: 0;



  margin-top: 0;



  transition:

    max-height 0.38s ease,

    opacity 0.25s ease,

    margin-top 0.25s ease;

}





.erp-modal-steps.is-shown {



  max-height: 500px;



  opacity: 1;



  margin-top:

    15px;

}





.erp-modal-steps-list {



  margin: 0;



  padding:

    0 20px;



  list-style: none;



  counter-reset:

    step-counter;

}





.erp-modal-steps-list li {



  position: relative;



  counter-increment:

    step-counter;



  padding:

    9px 0;



  border-bottom:

    1px solid rgba(56, 103, 174, 0.10);



  color:

    var(--brand-text) !important;



  font-size:

    12.5px;



  line-height:

    1.65;

}





.erp-modal-steps-list li:last-child {



  border-bottom: 0;

}





.erp-modal-steps-list li::before {



  content:

    counter(step-counter);



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 22px;

  height: 22px;



  margin-inline-end:

    9px;



  border-radius:

    50%;



  background:

    var(--brand-primary);



  color:

    #ffffff;



  font-size:

    10px;



  font-weight:

    800;

}





/* =========================================================

   45. DARK MODE

========================================================= */



[data-theme="dark"]

.erp-dashboard-wrapper,



html[data-theme="dark"]

.erp-dashboard-wrapper {



  --brand-text:

    #E9EEF7;



  --brand-muted:

    #A7B2C5;



  --brand-border:

    rgba(15, 132, 181, 0.22);



  --brand-border-strong:

    rgba(15, 132, 181, 0.40);

}





/*

   في الوضع الداكن نقلل وضوح Pattern

*/



[data-theme="dark"]

.erp-dashboard-wrapper::before,



html[data-theme="dark"]

.erp-dashboard-wrapper::before {



  opacity: 0.025;

}





[data-theme="dark"]

.erp-cycle-container,



html[data-theme="dark"]

.erp-cycle-container,



[data-theme="dark"]

.erp-overview-container,



html[data-theme="dark"]

.erp-overview-container,



[data-theme="dark"]

.erp-cycle-card,



html[data-theme="dark"]

.erp-cycle-card,



[data-theme="dark"]

.erp-card,



html[data-theme="dark"]

.erp-card,



[data-theme="dark"]

.erp-stat-card,



html[data-theme="dark"]

.erp-stat-card {



  background:

    rgba(32, 36, 44, 0.95);



  box-shadow:

    0 7px 22px rgba(0, 0, 0, 0.18);

}





[data-theme="dark"]

.erp-modal-box,



html[data-theme="dark"]

.erp-modal-box {



  background:

    var(--fg-color, #20242c) !important;

}





/* =========================================================

   46. LARGE TABLET

========================================================= */



@media (max-width: 1250px) {



  .erp-cycle-grid {



    grid-template-columns:

      repeat(4, minmax(0, 1fr));

  }





  .erp-cycle-arrow {



    display: none;

  }





  /*

     نصغر الـ Pattern قليلاً

  */



  .erp-dashboard-wrapper::before {



    -webkit-mask-size:

      155px auto;



    mask-size:

      155px auto;

  }

}





/* =========================================================

   47. TABLET

========================================================= */



@media (max-width: 1050px) {



  .erp-dashboard-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;

  }

}





/* =========================================================

   48. SMALL TABLET

========================================================= */



@media (max-width: 850px) {



  .erp-cycle-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr));

  }





  .erp-overview-container

  .erp-stats-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;

  }





  .erp-quick-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;

  }

}





/* =========================================================

   49. MOBILE

========================================================= */



@media (max-width: 650px) {



  .erp-dashboard-wrapper {



    padding:

      8px 8px 26px;

  }





  /*

     نحافظ على Pattern في الجوال

     لكن نصغره ونخففه

  */



  .erp-dashboard-wrapper::before {



    -webkit-mask-size:

      115px auto;



    mask-size:

      115px auto;



    opacity:

      0.025;

  }





  /* دورة المشتريات */



  .erp-cycle-container {



    padding:

      12px;

  }





  .erp-cycle-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr));



    gap:

      8px;

  }





  .erp-cycle-card {



    min-height:

      155px;



    padding:

      13px 8px;

  }





  .erp-cycle-number {



    width:

      36px;



    height:

      36px;



    flex-basis:

      36px;



    margin-bottom:

      10px;



    font-size:

      15px;

  }





  .erp-cycle-card-title {



    font-size:

      12px;

  }





  .erp-cycle-description {



    font-size:

      9.5px;



    line-height:

      1.55;

  }





  /* نظرة عامة */



  .erp-overview-container {



    padding:

      12px;

  }





  .erp-overview-container

  .erp-stats-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;



    gap:

      9px;

  }





  .erp-stat-card {



    min-height:

      76px;



    padding:

      11px;



    gap:

      8px;

  }





  .erp-stat-icon {



    width:

      36px;



    height:

      36px;



    flex-basis:

      36px;



    font-size:

      9px !important;

  }





  .erp-stat-value,

  .erp-stat-card .erp-stat-value {



    font-size:

      15px !important;

  }





  .erp-stat-label,

  .erp-stat-card .erp-stat-label {



    font-size:

      10px !important;

  }





  /* الاختصارات */



  .erp-quick-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;



    gap:

      8px;

  }





  .erp-quick-btn {



    min-height:

      43px;



    padding:

      9px 7px;



    font-size:

      11.5px;

  }





  /* التقارير */



  .erp-dashboard-grid {



    grid-template-columns:

      1fr !important;



    gap:

      11px;

  }





  .erp-card.is-open {



    transform:

      translateY(-2px);

  }





  /* الفوتر */



  .erp-footer {



    --footer-font-size:

      13px;



    margin-top:

      26px;



    padding-top:

      16px;

  }





  .erp-footer-inner {



    flex-direction:

      column;



    gap:

      8px;

