  /* =========================================================

     11. HELPERS

  ========================================================= */



  function translate(name) {



    if (!isArabic)

      return name;



    return (

      arabicFallback[name] ||

      (

        typeof window.__ === "function"

          ? window.__(name)

          : name

      )

    );



  }





  function escapeHtml(value) {



    return String(value ?? "")



      .replaceAll("&", "&amp;")

      .replaceAll("<", "&lt;")

      .replaceAll(">", "&gt;")

      .replaceAll('"', "&quot;")

      .replaceAll("'", "&#039;");



  }





  function formatNumber(number) {



    return (

      parseFloat(number) || 0

    ).toLocaleString("en-US");



  }





  function formatCurrency(number) {



    return (

      parseFloat(number) || 0

    ).toLocaleString(

       "en-US",

      {

        minimumFractionDigits: 2,

        maximumFractionDigits: 2

      }

    );



  }





  /* =========================================================

     12. MODAL

  ========================================================= */



  function showInfoModal(data) {



    const title =

      isArabic

        ? data.labelAr

        : data.labelEn;



    const summary =

      isArabic

        ? data.summaryAr

        : data.summaryEn;



    const steps =

      isArabic

        ? data.stepsAr

        : data.stepsEn;



    const hasSteps =

      Array.isArray(steps) &&

      steps.length > 0;



    const showText =

      isArabic

        ? "📖 عرض الخطوات"

        : "📖 Show Steps";



    const hideText =

      isArabic

        ? "📖 إخفاء الخطوات"

        : "📖 Hide Steps";





    const overlay =

      document.createElement("div");



    overlay.className =

      "erp-modal-overlay";



    overlay.setAttribute(

      "dir",

      isArabic ? "rtl" : "ltr"

    );





    overlay.innerHTML = `



      <div class="erp-modal-box">



        <button

          type="button"

          class="erp-modal-close"

          data-modal-close

        >

          ✕

        </button>





        <div class="erp-modal-header">



          <span class="erp-modal-icon">

            ${data.icon || "📄"}

          </span>



          <h3 class="erp-modal-title">

            ${escapeHtml(title)}

          </h3>



        </div>





        <p class="erp-modal-summary">

          ${escapeHtml(summary)}

        </p>





        ${

          hasSteps

            ? `

              <button

                type="button"

                class="erp-modal-toggle-steps"

                data-toggle-steps

              >

                ${showText}

              </button>



              <div

                class="erp-modal-steps"

                data-modal-steps

              >



                <ol class="erp-modal-steps-list">



                  ${steps

                    .map(

                      step =>

                        `<li>${escapeHtml(step)}</li>`

                    )

                    .join("")}



                </ol>



              </div>

            `

            : ""

        }



      </div>



    `;





    root.appendChild(overlay);





    requestAnimationFrame(() => {



      overlay.classList.add(

        "is-visible"

      );



    });





    function closeModal() {



      overlay.remove();



    }





    overlay

      .querySelector("[data-modal-close]")

      ?.addEventListener(

        "click",

        closeModal

      );





    overlay.addEventListener(



      "click",



      event => {



        if (event.target === overlay)

          closeModal();



      }



    );





    const toggleButton =

      overlay.querySelector(

        "[data-toggle-steps]"

      );



    const stepsContainer =

      overlay.querySelector(

        "[data-modal-steps]"

      );





    if (

      toggleButton &&

      stepsContainer

    ) {



      toggleButton.addEventListener(



        "click",



        () => {



          stepsContainer.classList.toggle(

            "is-shown"

          );



          toggleButton.textContent =

            stepsContainer.classList.contains(

              "is-shown"

            )

              ? hideText

              : showText;



        }



      );



    }



  }





  /* =========================================================

     13. ROUTING

  ========================================================= */



  function openRoute(name) {



    if (

      !window.frappe ||

      typeof frappe.set_route !== "function"

    )

      return;





    if (reportNames.has(name)) {



      frappe.set_route(

        "query-report",

        name

      );



      return;



    }





    if (singleDocs.has(name)) {



      frappe.set_route(

        "Form",

        name

      );



      return;



    }





    if (treeDocs.has(name)) {



      frappe.set_route(

        "Tree",

        name

      );



      return;



    }





    frappe.set_route(

      "List",

      name

    );



  }





  /* =========================================================

     14. RENDER STOCK CYCLE

  ========================================================= */



  function renderStockCycle() {



    if (!stockCycle)

      return;





    const sectionTitle =

      isArabic

        ? "دورة المخزون"

        : "Stock Cycle";





    stockCycle.innerHTML = `



      <section class="erp-cycle-container">



        <h2 class="erp-section-title erp-cycle-title">

          ${escapeHtml(sectionTitle)}

        </h2>





        <div

          class="erp-cycle-grid"

          style="

            grid-template-columns:

            repeat(

              ${stockCycleCards.length},

              minmax(0, 1fr)

            );

          "

        >



          ${stockCycleCards



            .map(

              (card, index) => {



                const title =

                  isArabic

                    ? card.labelAr

                    : card.labelEn;



                const description =

                  isArabic

                    ? card.descriptionAr

                    : card.descriptionEn;





                const arrow =

                  index <

                  stockCycleCards.length - 1



                    ? `

                      <span

                        class="erp-cycle-arrow"

                        aria-hidden="true"

                      >

                        ${isArabic ? "←" : "→"}

                      </span>

                    `

                    : "";





                return `



                  <div class="erp-cycle-item">



                    <button

                      type="button"

                      class="

                        erp-cycle-card

                        cycle-tone-${(index % 4) + 1}

                      "

                      data-cycle-index="${index}"

                    >



                      <span class="erp-cycle-number">

                        ${card.step}

                      </span>



                      <span class="erp-cycle-card-title">

                        ${escapeHtml(title)}

                      </span>



                      <span class="erp-cycle-description">

                        ${escapeHtml(description)}

                      </span>



                    </button>



                    ${arrow}



                  </div>



                `;



              }

            )



            .join("")}



        </div>



      </section>



    `;





    stockCycle.addEventListener(



      "click",



      event => {



        const element =

          event.target.closest(

            "[data-cycle-index]"

          );



        if (!element)

          return;





        const card =

          stockCycleCards[

            Number(

              element.dataset.cycleIndex

            )

          ];



        if (!card)

          return;





        if (

          card.doctype === "Stock Entry" &&

          card.stockEntryType

        ) {



          frappe.new_doc(

            "Stock Entry",

            {

              stock_entry_type:

                card.stockEntryType

            }

          );



          return;



        }





        openRoute(

          card.doctype

        );



      }



    );



  }





