                        </button>





                        <div class="erp-card-links">

                          ${links}

                        </div>



                      </article>



                    `;



                  }

                )



                .join("");





            return `



              <section class="erp-module-section">



                <h2 class="erp-section-title">

                  ${escapeHtml(translate(section[0]))}

                </h2>



                <div class="erp-dashboard-grid">

                  ${cards}

                </div>



              </section>



            `;



          }

        )



        .join("");



  }





  /* =========================================================

     18. FOOTER

  ========================================================= */



  function renderFooter() {



    if (!footerEl)

      return;





    footerEl.innerHTML = `



      <div class="erp-footer-inner">



        <div class="erp-footer-item">



          <span class="erp-footer-icon">☎</span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? footerInfo.labels.phoneAr

                : footerInfo.labels.phoneEn

            }:



          </span>



          <a

            href="tel:${footerInfo.phone}"

            class="erp-footer-link"

            dir="ltr"

          >

            ${footerInfo.phone}

          </a>



        </div>





        <span class="erp-footer-sep">|</span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">✉</span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? footerInfo.labels.emailAr

                : footerInfo.labels.emailEn

            }:



          </span>



          <a

            href="mailto:${footerInfo.email}"

            class="erp-footer-link"

          >

            ${footerInfo.email}

          </a>



        </div>





        <span class="erp-footer-sep">|</span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">◎</span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? footerInfo.labels.websiteAr

                : footerInfo.labels.websiteEn

            }:



          </span>



          <a

            href="https://${footerInfo.website}"

            class="erp-footer-link"

            target="_blank"

          >

            ${footerInfo.website}

          </a>



        </div>



      </div>



    `;



  }





  /* =========================================================

     19. EVENTS

  ========================================================= */



  content.addEventListener(



    "click",



    event => {





      const infoButton =

        event.target.closest(

          "[data-info-item]"

        );





      if (infoButton) {



        const itemName =

          infoButton.dataset.infoItem;



        const data =

          itemDescriptions[itemName];



        if (data) {



          showInfoModal({



            ...data,



            labelAr:

              translate(itemName),



            labelEn:

              itemName



          });



        }



        return;



      }





      const routeButton =

        event.target.closest(

          "[data-route-name]"

        );





      if (routeButton) {



        openRoute(

          routeButton.dataset.routeName

        );



        return;



      }





      const cardButton =

        event.target.closest(

          "[data-card-toggle]"

        );





      if (!cardButton)

        return;





      const selectedCard =

        cardButton.closest(

          "[data-erp-card]"

        );





      if (!selectedCard)

        return;





      const shouldOpen =

        !selectedCard.classList.contains(

          "is-open"

        );





      content

        .querySelectorAll(

          "[data-erp-card]"

        )

        .forEach(card => {



          if (card !== selectedCard) {



            card.classList.remove(

              "is-open"

            );



          }



        });





      selectedCard.classList.toggle(

        "is-open",

        shouldOpen

      );



  });





  /* =========================================================

     20. INIT

  ========================================================= */



  renderStockCycle();



  renderStats();



  renderQuickActions();



  renderSections();



  renderFooter();



})();

