/* =========================================================

   29. CARD ICON

========================================================= */



.erp-icon {



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 34px;

  height: 34px;



  flex:

    0 0 34px;



  border-radius:

    9px;



  background:

    var(--erp-soft);



  font-size:

    17px;

}





/* =========================================================

   30. CARD TITLE

========================================================= */



.erp-card-title,

.erp-card .erp-card-title {



  flex: 1;



  min-width: 0;



  color:

    var(--brand-text) !important;



  font-size:

    16px;



  font-weight:

    800;



  line-height:

    1.5;

}





/* =========================================================

   31. CARD CHEVRON

========================================================= */



.erp-card-chevron {



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 28px;

  height: 28px;



  flex:

    0 0 28px;



  border-radius:

    8px;



  background:

    var(--erp-soft);



  color:

    var(--erp-accent) !important;



  font-size:

    17px;



  transition:

    transform 0.22s ease;

}





.erp-card.is-open

.erp-card-chevron {



  transform:

    rotate(180deg);

}











/* =========================================================

   32. CARD LINKS

========================================================= */



.erp-card-links {



  position: relative;



  z-index: 2;



  display: grid;



  gap: 5px;



  max-height: 0;



  margin: 0;

  padding: 0;



  overflow: hidden;



  opacity: 0;

  visibility: hidden;



  pointer-events: none;



  transform:

    translateY(-8px);



  transition:

    max-height 0.38s ease,

    opacity 0.2s ease,

    visibility 0.2s ease,

    transform 0.28s ease;

}





.erp-card.is-open

.erp-card-links {



  max-height: 480px;



  overflow-y: auto;



  opacity: 1;

  visibility: visible;



  pointer-events: auto;



  transform:

    translateY(0);

}











/* =========================================================

   33. LINK ROW

========================================================= */



.erp-link-row {



  display: flex;



  align-items: center;



  gap: 6px;



  width: 100%;

}





/* =========================================================

   34. CARD LINK

========================================================= */



.erp-link {



  display: flex;



  align-items: center;



  gap: 7px;



  flex: 1;



  min-width: 0;

  min-height: 36px;



  padding:

    7px 10px;



  border:

    1px solid transparent;



  border-radius:

    8px;



  outline: none;



  background:

    transparent;



  color:

    var(--brand-text) !important;



  font-family: inherit;



  font-size:

    13px;



  font-weight:

    500;



  line-height:

    1.45;



  text-align:

    inherit;



  cursor: pointer;



  transition:

    background 0.16s ease,

    color 0.16s ease,

    border-color 0.16s ease,

    transform 0.16s ease;

}





.erp-link-text {



  flex: 1;



  min-width: 0;



  color:

    inherit !important;

}





.erp-link:hover,

.erp-link:focus {



  border-color:

    var(--brand-border);



  background:

    var(--erp-soft);



  color:

    var(--erp-accent) !important;

}





.erp-dashboard-rtl

.erp-link:hover,



.erp-dashboard-rtl

.erp-link:focus {



  transform:

    translateX(-3px);

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-link:hover,



.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-link:focus {



  transform:

    translateX(3px);

}





/* =========================================================

   35. LINK ARROW

========================================================= */



.erp-link-arrow {



  flex:

    0 0 auto;



  color:

    var(--erp-accent) !important;



  font-size:

    13px;



  font-weight:

    800;



  opacity: 0;



  transition:

    opacity 0.16s ease;

}





.erp-link:hover

.erp-link-arrow,



.erp-link:focus

.erp-link-arrow {



  opacity: 1;

}





/* =========================================================

   36. DETAILS BUTTON

========================================================= */



.erp-info-link {



  flex:

    0 0 auto;



  padding:

    5px 10px;



  border:

    1px solid var(--brand-border);



  border-radius:

    7px;



  outline: none;



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;



  font-family:

    inherit;



  font-size:

    12px;



  font-weight:

    600;



  cursor: pointer;



  transition:

    border-color 0.16s ease,

    background 0.16s ease,

    color 0.16s ease;

}





.erp-info-link:hover {



  border-color:

    var(--brand-primary);



  background:

    rgba(56, 103, 174, 0.13);



  color:

    var(--brand-primary) !important;

}





/* =========================================================

   37. SCROLLBAR

========================================================= */



.erp-card-links::-webkit-scrollbar {



  width: 5px;

}





.erp-card-links::-webkit-scrollbar-track {



  background:

    transparent;

}





.erp-card-links::-webkit-scrollbar-thumb {



  border-radius:

    10px;



  background:

    var(--brand-primary);

}





/* =========================================================

   38. FOOTER

========================================================= */



.erp-footer {



  --footer-font-size:

    15px;



  margin-top:

    34px;



  padding:

    20px 12px 4px;



  border-top:

    1px solid var(--brand-border);



  color:

    var(--brand-text);

}





.erp-footer-inner {



  display: flex;



  align-items: center;

  justify-content: center;



  flex-wrap: wrap;



  gap:

    10px 22px;



  width: 100%;

}





.erp-footer-item {



  display: flex;



  align-items: center;



  gap: 7px;



  color:

    var(--brand-text) !important;



  font-size:

    var(--footer-font-size) !important;



  font-weight:

    600;



  line-height:

    1.6;

}





.erp-footer-icon {



  display: inline-flex;



  align-items: center;

  justify-content: center;



  color:

    var(--brand-primary) !important;



  font-size:

    17px !important;



  line-height:

    1;

}





.erp-footer-label {



  color:

    var(--brand-text) !important;



  font-size:

    var(--footer-font-size) !important;



  font-weight:

    700 !important;

}





.erp-footer-link {



  color:

    var(--brand-primary) !important;



  font-size:

    var(--footer-font-size) !important;



  font-weight:

    600 !important;



  text-decoration: none;



  transition:

    color 0.18s ease;

}





.erp-footer-link:hover {



  color:

    var(--brand-secondary) !important;



  text-decoration:

    underline;

}





.erp-footer-sep {



  color:

    var(--brand-border-strong) !important;



  font-size:

    20px;



  font-weight:

    300;



  line-height:

    1;

}





/* =========================================================

   39. MODAL OVERLAY

========================================================= */



.erp-modal-overlay {



  position: fixed;



  inset: 0;



  z-index:

    99999 !important;



  display: flex;



  align-items: center;

  justify-content: center;



  padding: 20px;



  background:

    rgba(12, 27, 54, 0) !important;



  transition:

    background 0.28s ease;

}





.erp-modal-overlay.is-visible {



  background:

    rgba(12, 27, 54, 0.52) !important;

}





/* =========================================================

   40. MODAL BOX

========================================================= */



.erp-modal-box {



  position: relative;



  width: 100%;



  max-width: 480px;

  max-height: 85vh;



  padding:

    28px 24px;



  overflow-y: auto;



  border:

    1px solid var(--brand-border);



  border-radius:

    16px;



  background:

    #ffffff !important;



  box-shadow:

    0 24px 64px rgba(12, 27, 54, 0.28) !important;



  opacity: 0;



  transform:

    translateY(24px)

    scale(0.97);



  transition:

    opacity 0.28s ease,

    transform 0.28s ease;

}





.erp-modal-overlay.is-visible

.erp-modal-box {



  opacity: 1;



  transform:

    translateY(0)

    scale(1);

}





/* =========================================================

   41. MODAL CLOSE

========================================================= */



.erp-modal-close {



  position: absolute;



  top: 12px;



  display: flex;



  align-items: center;

  justify-content: center;



  width: 32px;

  height: 32px;



  border: 0;



  border-radius:

    8px;



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;



  font-size:

    15px;



  cursor:

    pointer;

}





[dir="rtl"]

.erp-modal-close {



  left: 12px;

}





[dir="ltr"]

.erp-modal-close {



  right: 12px;

}





/* =========================================================

   42. MODAL CONTENT

========================================================= */



.erp-modal-header {



  display: flex;



  align-items: center;



  gap: 11px;



  margin-bottom:

    15px;

}





.erp-modal-icon {



  font-size:

    28px;



  line-height:

    1;

}





.erp-modal-title {



  margin: 0;



  color:

    var(--brand-text) !important;



  font-size:

    18px;



  font-weight:

    800;

}





.erp-modal-summary {



  margin:

    0 0 16px;



  color:

    var(--brand-text) !important;



  font-size:

    13.5px;



  line-height:

    1.75;

}





/* =========================================================

   43. MODAL STEPS BUTTON

========================================================= */



.erp-modal-toggle-steps {



  display: inline-flex;



  align-items: center;



  gap: 6px;



  padding:

    8px 16px;



  border:

    1px solid var(--brand-primary);



  border-radius:

    9px;



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;



  font-family:

    inherit;



  font-size:

    12.5px;



  font-weight:

    700;



  cursor:

    pointer;

}





.erp-modal-toggle-steps:hover {



  background:

    rgba(56, 103, 174, 0.13);

}





/* =========================================================

   44. MODAL STEPS

========================================================= */



.erp-modal-steps {



  max-height: 0;



  overflow: hidden;



  opacity: 0;



  margin-top: 0;



  transition:

    max-height 0.38s ease,

    opacity 0.25s ease,

    margin-top 0.25s ease;

}





.erp-modal-steps.is-shown {



  max-height: 500px;



  opacity: 1;



  margin-top:

    15px;

}





.erp-modal-steps-list {



  margin: 0;



  padding:

    0 20px;



  list-style: none;



  counter-reset:

    step-counter;

}





.erp-modal-steps-list li {



  position: relative;



  counter-increment:

    step-counter;



  padding:

    9px 0;



  border-bottom:

    1px solid rgba(56, 103, 174, 0.10);



  color:

    var(--brand-text) !important;



  font-size:

    12.5px;



  line-height:

    1.65;

}





.erp-modal-steps-list li:last-child {



  border-bottom: 0;

}





.erp-modal-steps-list li::before {



  content:

    counter(step-counter);



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 22px;

  height: 22px;



  margin-inline-end:

    9px;



  border-radius:

    50%;



  background:

    var(--brand-primary);



  color:

    #ffffff;



  font-size:

    10px;



  font-weight:

    800;

}





/* =========================================================

   45. DARK MODE

========================================================= */



[data-theme="dark"]

.erp-dashboard-wrapper,



html[data-theme="dark"]

.erp-dashboard-wrapper {



  --brand-text:

    #E9EEF7;



  --brand-muted:

    #A7B2C5;



  --brand-border:

    rgba(15, 132, 181, 0.22);



  --brand-border-strong:

    rgba(15, 132, 181, 0.40);

}





/*

   في الوضع الداكن نقلل وضوح Pattern

*/



[data-theme="dark"]

.erp-dashboard-wrapper::before,



html[data-theme="dark"]

.erp-dashboard-wrapper::before {



  opacity: 0.025;

}





[data-theme="dark"]

.erp-cycle-container,



html[data-theme="dark"]

.erp-cycle-container,



[data-theme="dark"]

.erp-overview-container,



html[data-theme="dark"]

.erp-overview-container,



[data-theme="dark"]

.erp-cycle-card,



html[data-theme="dark"]

.erp-cycle-card,



[data-theme="dark"]

.erp-card,



html[data-theme="dark"]

.erp-card,



[data-theme="dark"]

.erp-stat-card,



html[data-theme="dark"]

.erp-stat-card {



  background:

    rgba(32, 36, 44, 0.95);



  box-shadow:

    0 7px 22px rgba(0, 0, 0, 0.18);

}





[data-theme="dark"]

.erp-modal-box,



html[data-theme="dark"]

.erp-modal-box {



  background:

    var(--fg-color, #20242c) !important;

}





/* =========================================================

   46. LARGE TABLET

========================================================= */



@media (max-width: 1250px) {



  .erp-cycle-grid {



    grid-template-columns:

      repeat(4, minmax(0, 1fr));

  }





  .erp-cycle-arrow {



    display: none;

  }





  /*

     نصغر الـ Pattern قليلاً

  */



  .erp-dashboard-wrapper::before {



    -webkit-mask-size:

      155px auto;



    mask-size:

      155px auto;

  }

}





/* =========================================================

   47. TABLET

========================================================= */



@media (max-width: 1050px) {



  .erp-dashboard-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;

  }

}





/* =========================================================

   48. SMALL TABLET

========================================================= */



@media (max-width: 850px) {



  .erp-cycle-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr));

  }





  .erp-overview-container

  .erp-stats-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;

  }





  .erp-quick-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;

  }

}





/* =========================================================

   49. MOBILE

========================================================= */



@media (max-width: 650px) {



  .erp-dashboard-wrapper {



    padding:

      8px 8px 26px;

  }





  /*

     نحافظ على Pattern في الجوال

     لكن نصغره ونخففه

  */



  .erp-dashboard-wrapper::before {



    -webkit-mask-size:

      115px auto;



    mask-size:

      115px auto;



    opacity:

      0.025;

  }





  /* دورة المشتريات */



  .erp-cycle-container {



    padding:

      12px;

  }





  .erp-cycle-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr));



    gap:

      8px;

  }





  .erp-cycle-card {



    min-height:

      155px;



    padding:

      13px 8px;

  }





  .erp-cycle-number {



    width:

      36px;



    height:

      36px;



    flex-basis:

      36px;



    margin-bottom:

      10px;



    font-size:

      15px;

  }





  .erp-cycle-card-title {



    font-size:

      12px;

  }





  .erp-cycle-description {



    font-size:

      9.5px;



    line-height:

      1.55;

  }





  /* نظرة عامة */



  .erp-overview-container {



    padding:

      12px;

  }





  .erp-overview-container

  .erp-stats-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;



    gap:

      9px;

  }





  .erp-stat-card {



    min-height:

      76px;



    padding:

      11px;



    gap:

      8px;

  }





  .erp-stat-icon {



    width:

      36px;



    height:

      36px;



    flex-basis:

      36px;



    font-size:

      9px !important;

  }





  .erp-stat-value,

  .erp-stat-card .erp-stat-value {



    font-size:

      15px !important;

  }





  .erp-stat-label,

  .erp-stat-card .erp-stat-label {



    font-size:

      10px !important;

  }





  /* الاختصارات */



  .erp-quick-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;



    gap:

      8px;

  }





  .erp-quick-btn {



    min-height:

      43px;



    padding:

      9px 7px;



    font-size:

      11.5px;

  }





  /* التقارير */



  .erp-dashboard-grid {



    grid-template-columns:

      1fr !important;



    gap:

      11px;

  }





  .erp-card.is-open {



    transform:

      translateY(-2px);

  }





  /* الفوتر */



  .erp-footer {



    --footer-font-size:

      13px;



    margin-top:

      26px;



    padding-top:

      16px;

  }





  .erp-footer-inner {



    flex-direction:

      column;



    gap:

      8px;

  }





  .erp-footer-item {



    justify-content:

      center;

  }





  .erp-footer-icon {



    font-size:

      15px !important;

  }





  .erp-footer-sep {



    display:

      none;

  }





  /* المودال */



  .erp-modal-overlay {



    align-items:

      flex-end;



    padding:

      10px;

  }





  .erp-modal-box {



    max-height:

      82vh;



    padding:

      22px 17px;



    border-radius:

      16px 16px 0 0;

  }

}

/* =========================================================
   CARDS REMAIN OPEN BY DEFAULT & HOVER-OPEN DISABLED
   إبقاء المربعات مفتوحة بشكل تلقائي وإلغاء الفتح بمرور الماوس
========================================================= */

.erp-card {
  max-height: none !important;
  overflow: visible !important;
  padding-bottom: 15px !important;
}

.erp-card .erp-card-heading {
  margin-bottom: 10px !important;
  border-bottom: 1px solid var(--brand-border) !important;
}

.erp-card .erp-card-chevron {
  transform: rotate(180deg) !important;
}

.erp-card .erp-card-links {
  max-height: none !important;
  overflow: visible !important;
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: auto !important;
  transform: none !important;
}

script:
(() => {
  /*
   * ══════════════════════════════════════════
   *  لوحة تحكم الأصول الثابتة — ERPNext Assets
   * ══════════════════════════════════════════
   */

  const root = root_element.querySelector("[data-erp-dashboard]");
  const content = root_element.querySelector("[data-dashboard-content]");
  const statsSection = root_element.querySelector("[data-stats-section]");
  const quickActions = root_element.querySelector("[data-quick-actions]");
  const footerEl = root_element.querySelector("[data-dashboard-footer]");

  if (!root || !content) return;

  const langValue =
    window.frappe?.boot?.lang ||
    window.frappe?.boot?.user?.language ||
    document.documentElement.lang || "en";

  const isArabic = String(langValue).toLowerCase().startsWith("ar");

  /* ─────────────────────────────────────────
     ١. إحصائيات الأصول الثابتة
  ───────────────────────────────────────── */

  const statsCards = [
    {
      id: "total-assets",
      short: "AST",
      labelEn: "Total Assets",
      labelAr: "إجمالي الأصول",
      fetch: () =>
        new Promise(resolve => {
          frappe.call({
            method: "frappe.client.get_count",
            args: {
              doctype: "Asset",
              filters: { docstatus: 1 }
            },
            callback: data => resolve(data?.message || 0),
            error: () => resolve(0)
          });
        })
    },
    {
      id: "book-value",
      short: "VAL",
      labelEn: "Total Asset Value",
      labelAr: "القيمة الإجمالية",
      isCurrency: true,
      fetch: () =>
        new Promise(resolve => {
          frappe.call({
            method: "frappe.client.get_list",
            args: {
              doctype: "Asset",
              filters: { docstatus: 1 },
              fields: ["sum(gross_purchase_amount) as total"],
              limit_page_length: 0
            },
            callback: data => {
              const value = data?.message?.[0]?.total || 0;
              resolve(Number(value).toFixed(2));
            },
            error: () => resolve("0.00")
          });
        })
    },
    {
      id: "due-depreciation",
      short: "DEP",
      labelEn: "Pending Depreciation",
      labelAr: "إهلاكات مستحقة",
      fetch: () =>
        new Promise(resolve => {
          frappe.call({
            method: "frappe.client.get_count",
            args: {
              doctype: "Asset",
              filters: {
                docstatus: 1,
                status: ["in", ["Submitted", "Partially Depreciated"]]
              }
            },
            callback: data => resolve(data?.message || 0),
            error: () => resolve(0)
          });
        })
    },
    {
      id: "disposed-assets",
      short: "DSP",
      labelEn: "Disposed Assets",
      labelAr: "أصول مستبعدة",
      fetch: () =>
        new Promise(resolve => {
          frappe.call({
            method: "frappe.client.get_count",
            args: {
              doctype: "Asset",
              filters: {
                docstatus: 1,
                status: ["in", ["Scrapped", "Sold"]]
              }
            },
            callback: data => resolve(data?.message || 0),
            error: () => resolve(0)
          });
        })
    }
  ];

  /* ─────────────────────────────────────────
     ٢. أزرار الاختصارات السريعة (تبقى كما هي)
  ───────────────────────────────────────── */

  const quickActionButtons = [
    {
      doctype: "Asset",
      labelEn: "New Asset",
      labelAr: "أصل جديد"
    },
    {
      doctype: "Purchase Invoice",
      labelEn: "Asset Purchase Invoice",
      labelAr: "فاتورة شراء أصل"
    },
    {
      doctype: "Asset Movement",
      labelEn: "New Asset Movement",
      labelAr: "حركة أصل جديدة"
    },
    {
      doctype: "Asset Value Adjustment",
      labelEn: "Asset Value Adjustment",
      labelAr: "تعديل قيمة أصل"
    }
  ];

  /* ─────────────────────────────────────────
     ٣. إعدادات الفوتر
  ───────────────────────────────────────── */

  const footerInfo = {
    phone: "0115110455",
    email: "sales@mubtkir.com",
    website: "www.mubtkir.com",
    labels: {
      phoneEn: "Phone", phoneAr: "الهاتف الموحد",
      emailEn: "Email", emailAr: "البريد الإلكتروني",
      websiteEn: "Website", websiteAr: "الموقع"
    }
  };

