  /* =========================================================

     10. HELPERS

  ========================================================= */



  function translate(name) {



    if (!isArabic)

      return name;



    return (

      arabicFallback[name] ||

      (

        typeof window.__ === "function"

          ? window.__(name)

          : name

      )

    );



  }





  function escapeHtml(value) {



    return String(value ?? "")



      .replaceAll("&", "&amp;")

      .replaceAll("<", "&lt;")

      .replaceAll(">", "&gt;")

      .replaceAll('"', "&quot;")

      .replaceAll("'", "&#039;");



  }





  function formatNumber(number) {



    return (

      parseFloat(number) || 0

    ).toLocaleString("en-US");



  }





  /* =========================================================

     11. INFO MODAL

  ========================================================= */



  function showInfoModal(data) {



    const title =

      isArabic

        ? data.labelAr

        : data.labelEn;



    const summary =

      isArabic

        ? data.summaryAr

        : data.summaryEn;



    const steps =

      isArabic

        ? data.stepsAr

        : data.stepsEn;



    const hasSteps =

      Array.isArray(steps) &&

      steps.length > 0;



    const showText =

      isArabic

        ? "📖 عرض الخطوات"

        : "📖 Show Steps";



    const hideText =

      isArabic

        ? "📖 إخفاء الخطوات"

        : "📖 Hide Steps";





    const overlay =

      document.createElement("div");



    overlay.className =

      "erp-modal-overlay";



    overlay.setAttribute(

      "dir",

      isArabic ? "rtl" : "ltr"

    );





    overlay.innerHTML = `



      <div class="erp-modal-box">



        <button

          type="button"

          class="erp-modal-close"

          data-modal-close

        >

          ✕

        </button>





        <div class="erp-modal-header">



          <span class="erp-modal-icon">

            ${data.icon || "📄"}

          </span>



          <h3 class="erp-modal-title">

            ${escapeHtml(title)}

          </h3>



        </div>





        <p class="erp-modal-summary">

          ${escapeHtml(summary)}

        </p>





        ${

          hasSteps

            ? `



              <button

                type="button"

                class="erp-modal-toggle-steps"

                data-toggle-steps

              >

                ${showText}

              </button>





              <div

                class="erp-modal-steps"

                data-modal-steps

              >



                <ol class="erp-modal-steps-list">



                  ${steps

                    .map(

                      step =>

                        `<li>${escapeHtml(step)}</li>`

                    )

                    .join("")}



                </ol>



              </div>



            `

            : ""

        }



      </div>



    `;





    root.appendChild(overlay);





    requestAnimationFrame(() => {



      overlay.classList.add(

        "is-visible"

      );



    });





    function closeModal() {



      overlay.remove();



    }





    overlay

      .querySelector("[data-modal-close]")

      ?.addEventListener(

        "click",

        closeModal

      );





    overlay.addEventListener(



      "click",



      event => {



        if (event.target === overlay)

          closeModal();



      }



    );





    const toggleButton =

      overlay.querySelector(

        "[data-toggle-steps]"

      );



    const stepsContainer =

      overlay.querySelector(

        "[data-modal-steps]"

      );





    if (

      toggleButton &&

      stepsContainer

    ) {



      toggleButton.addEventListener(



        "click",



        () => {



          stepsContainer

            .classList

            .toggle(

              "is-shown"

            );





          toggleButton.textContent =

            stepsContainer

              .classList

              .contains(

                "is-shown"

              )

              ? hideText

              : showText;



        }



      );



    }



  }





  /* =========================================================

     12. ROUTING

  ========================================================= */



  function openRoute(name) {



    if (

      !window.frappe ||

      typeof frappe.set_route !== "function"

    )

      return;





    /* Role Permission Manager */



    if (specialPages[name]) {



      frappe.set_route(

        specialPages[name]

      );



      return;



    }





    /* Single Doc */



    if (singleDocs.has(name)) {



      frappe.set_route(

        "Form",

        name

      );



      return;



    }





    /* Normal List */



    frappe.set_route(

      "List",

      name

    );



  }





