  function renderUserFlow() {



    if (!userFlow)

      return;





    const sectionTitle =

      isArabic

        ? "إدارة المستخدمين"

        : "User Management Flow";





    userFlow.innerHTML = `



      <section class="erp-cycle-container">



        <h2

          class="

            erp-section-title

            erp-cycle-title

          "

        >

          ${escapeHtml(sectionTitle)}

        </h2>





        <div

          class="erp-cycle-grid"

          style="

            grid-template-columns:

            repeat(

              ${userFlowCards.length},

              minmax(0, 1fr)

            );

          "

        >



          ${userFlowCards



            .map(

              (card, index) => {



                const title =

                  isArabic

                    ? card.labelAr

                    : card.labelEn;





                const description =

                  isArabic

                    ? card.descriptionAr

                    : card.descriptionEn;





                const arrow =

                  index <

                  userFlowCards.length - 1



                    ? `

                      <span

                        class="erp-cycle-arrow"

                        aria-hidden="true"

                      >

                        ${isArabic ? "←" : "→"}

                      </span>

                    `



                    : "";





                return `



                  <div class="erp-cycle-item">



                    <button

                      type="button"

                      class="

                        erp-cycle-card

                        cycle-tone-${(index % 4) + 1}

                      "

                      data-user-flow-index="${index}"

                    >



                      <span class="erp-cycle-number">

                        ${card.step}

                      </span>





                      <span class="erp-cycle-card-title">

                        ${escapeHtml(title)}

                      </span>





                      <span class="erp-cycle-description">

                        ${escapeHtml(description)}

                      </span>



                    </button>





                    ${arrow}



                  </div>



                `;



              }

            )



            .join("")}



        </div>



      </section>



    `;





    userFlow.addEventListener(



      "click",



      event => {



        const element =

          event.target.closest(

            "[data-user-flow-index]"

          );





        if (!element)

          return;





        const card =

          userFlowCards[

            Number(

              element.dataset.userFlowIndex

            )

          ];





        if (!card)

          return;





        if (

          card.action === "new"

        ) {



          frappe.new_doc(

            card.doctype

          );



          return;



        }





        if (

          card.action === "page"

        ) {



          frappe.set_route(

            card.route

          );



          return;



        }





        openRoute(

          card.doctype

        );



      }



    );



  }





