  let lastToggleTime = 0;





  content.addEventListener(



    "click",



    event => {





      /* DETAILS */



      const infoButton =

        event.target.closest(

          "[data-info-item]"

        );





      if (infoButton) {



        event.preventDefault();

        event.stopPropagation();





        const itemName =

          infoButton.dataset.infoItem;





        const data =

          itemDescriptions[itemName];





        if (data) {



          showInfoModal({



            ...data,



            labelAr:

              translate(itemName),



            labelEn:

              itemName



          });



        }





        return;



      }





      /* ROUTE */



      const routeButton =

        event.target.closest(

          "[data-route-name]"

        );





      if (routeButton) {



        event.preventDefault();

        event.stopPropagation();





        openRoute(

          routeButton.dataset.routeName

        );





        return;



      }





      /* CARD TOGGLE */



      const cardButton =

        event.target.closest(

          "[data-card-toggle]"

        );





      if (!cardButton)

        return;





      const now =

        Date.now();





      if (

        now - lastToggleTime <

        400

      )

        return;





      lastToggleTime =

        now;





      const selectedCard =

        cardButton.closest(

          "[data-erp-card]"

        );





      if (!selectedCard)

        return;





      const shouldOpen =

        !selectedCard

          .classList

          .contains(

            "is-open"

          );





      content

        .querySelectorAll(

          "[data-erp-card]"

        )

        .forEach(card => {



          if (

            card !== selectedCard

          ) {



            card

              .classList

              .remove(

                "is-open"

              );



          }



        });





      selectedCard

        .classList

        .toggle(

          "is-open",

          shouldOpen

        );



    }



  );





  /* =========================================================

     19. INIT

  ========================================================= */



  renderUserFlow();



  renderStats();



  renderQuickActions();



  renderSections();



  renderFooter();



})();

