                        '<ol class="erp-modal-steps-list">' +

                            list +

                        '</ol>' +



                    '</div>' +



                '</div>';





            root.appendChild(

                overlay

            );





            setTimeout(

                function () {



                    overlay.classList.add(

                        "is-visible"

                    );



                },

                10

            );





            var close =

                overlay.querySelector(

                    "[data-mfg-modal-close]"

                );





            if (close) {



                close.addEventListener(

                    "click",

                    function () {



                        overlay.remove();



                    }

                );



            }





            var toggle =

                overlay.querySelector(

                    "[data-mfg-show-steps]"

                );





