}





/* =========================================================

   44. MODAL STEPS

========================================================= */



.erp-modal-steps {



  max-height: 0;



  overflow: hidden;



  opacity: 0;



  margin-top: 0;



  transition:

    max-height 0.38s ease,

    opacity 0.25s ease,

    margin-top 0.25s ease;

}





.erp-modal-steps.is-shown {



  max-height: 500px;



  opacity: 1;



  margin-top:

