/* =========================================================

   MUBTKIR ERP — BUYING WORKSPACE

   Unified Professional Brand Theme

   لوحة تحكم قسم المشتريات

========================================================= */





/* =========================================================

   1. ROOT + BRAND COLORS

   ألوان الهوية الرسمية

========================================================= */



.erp-dashboard-wrapper {



  --brand-primary: #3867AE;

  --brand-secondary: #0F84B5;

  --brand-accent: #0BA1B8;

  --brand-purple: #644DA6;



  --brand-text: #243B63;

  --brand-muted: #66758A;



  --brand-border: rgba(56, 103, 174, 0.22);

  --brand-border-strong: rgba(56, 103, 174, 0.38);



  --brand-soft: rgba(56, 103, 174, 0.07);

  --brand-soft-secondary: rgba(15, 132, 181, 0.07);

  --brand-soft-accent: rgba(11, 161, 184, 0.07);

  --brand-soft-purple: rgba(100, 77, 166, 0.07);



  position: relative;

  isolation: isolate;



  width: 100%;



  padding: 14px 16px 36px;



  overflow: visible;



  color: var(--brand-text);

}





/* =========================================================

   2. FONT

========================================================= */



.erp-dashboard-wrapper,

.erp-dashboard-wrapper * {



  box-sizing: border-box;



  font-family:

    "Tajawal",

    "Inter",

    Arial,

    sans-serif !important;

}





/* =========================================================

   3. RTL

========================================================= */



.erp-dashboard-wrapper.erp-dashboard-rtl {



  direction: rtl;

  text-align: right;

}





/* =========================================================

   BACKGROUND

   صورة واحدة في الخلفية بدون تكرار

========================================================= */



.erp-dashboard-bg {

    position: absolute !important;



    top: 50px;

    left: 50%;



    /* حجم الصورة */

    width: 78%;

    max-width: 1200px;



    height: auto;



    transform: translateX(-50%);



    /* الشفافية */

    opacity: 0.03;



    object-fit: contain;



    pointer-events: none;

    user-select: none;



    z-index: 0;

}





/* الحاوية الرئيسية */

.erp-dashboard-wrapper {

    position: relative !important;

    isolation: isolate;

}





/* المحتوى فوق الخلفية */

.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

    position: relative !important;

    z-index: 2;

}



/* =========================================================

   المحتوى فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



    position: relative;



    z-index: 2;

}

/* =========================================================

   إبقاء جميع عناصر الداشبورد فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

    position: relative;

    z-index: 2;

}



/* =========================================================

   5. CONTENT LAYER

   جميع المحتويات تظهر فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



  position: relative;



  z-index: 2;

}





.erp-dashboard-content,

.erp-module-section,

.erp-dashboard-grid {



  background: transparent !important;

}





/* =========================================================

   6. SECTION TITLE

========================================================= */



.erp-section-title {



  position: relative;



  display: flex;

  align-items: center;



  min-height: 36px;



  margin: 0 0 16px;



  padding: 0 0 10px;



  border-bottom:

    1px solid var(--brand-border);



  color:

    var(--brand-text) !important;



  font-size: 18px;

  font-weight: 700;



  line-height: 1.4;

}





.erp-section-title::after {



  content: "";



  position: absolute;



  bottom: -1px;



  width: 52px;

  height: 2px;



  border-radius: 20px;



  background: var(--brand-primary);

}





.erp-dashboard-rtl

.erp-section-title::after {



  right: 0;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-section-title::after {



  left: 0;

}





/* =========================================================

   7. PURCHASE CYCLE SECTION

========================================================= */



.erp-purchase-cycle-section {



  margin: 18px 0 24px;

}





.erp-cycle-container {



  position: relative;



  padding: 18px 18px 20px;



  border:

    1px solid var(--brand-border);



  border-radius: 16px;



  /*

     شبه معتم حتى يبقى الـ Pattern ظاهراً بخفة

  */



  background:

    rgba(255, 255, 255, 0.94);



  box-shadow:

    0 5px 18px rgba(36, 59, 99, 0.06);

}





.erp-cycle-title {



  margin-bottom: 20px;

}





/* =========================================================

   SALES / PURCHASE CYCLE GRID

   توزيع البطاقات على كامل عرض الصفحة

========================================================= */



.erp-cycle-grid {

  display: grid;



  grid-template-columns:

    repeat(5, minmax(0, 1fr));



  gap: 18px;



  width: 100%;



  align-items: stretch;

}





.erp-cycle-item {

  position: relative;



  display: flex;



  width: 100%;



  min-width: 0;

}





/* البطاقة تتمدد حسب عرض العمود */

.erp-cycle-card {

  width: 100%;



  min-width: 0;



  min-height: 180px;

}



/* =========================================================

   9. PURCHASE CYCLE CARD

========================================================= */



.erp-cycle-card {



  --cycle-color:

    var(--brand-primary);



  --cycle-soft:

    var(--brand-soft);



  position: relative;



  display: flex;



  flex-direction: column;



  align-items: center;

  justify-content: flex-start;



  width: 100%;



  min-width: 0;

  min-height: 180px;



  padding: 17px 11px 15px;



  overflow: hidden;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  outline: none;



  background:

    rgba(255, 255, 255, 0.96);



  color:

    var(--brand-text) !important;



  font-family: inherit;



  text-align: center;



  cursor: pointer;



  transition:

    transform 0.20s ease,

    border-color 0.20s ease,

    box-shadow 0.20s ease;

}





.erp-cycle-card::before {



  content: "";



  position: absolute;



  inset: 0;



  border-radius: inherit;



  background:

    var(--cycle-soft);



  opacity: 0.42;



  pointer-events: none;

}





.erp-cycle-card::after {



  content: "";



  position: absolute;



  right: 0;

  bottom: 0;



  width: 0;

  height: 3px;



  background:

    var(--cycle-color);



  transition:

    width 0.25s ease;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-cycle-card::after {



  right: auto;

  left: 0;

}





.erp-cycle-card > * {



