script:
(() => {



  /* =========================================================

     MUBTKIR ERP — PROJECTS WORKSPACE

     لوحة تحكم المشاريع

  ========================================================= */



  const root =

    root_element.querySelector("[data-erp-dashboard]");



  const projectCycle =

    root_element.querySelector("[data-purchase-cycle]");



  const statsSection =

    root_element.querySelector("[data-stats-section]");



  const quickActions =

    root_element.querySelector("[data-quick-actions]");



  const content =

    root_element.querySelector("[data-dashboard-content]");



  const footerEl =

    root_element.querySelector("[data-dashboard-footer]");



  if (!root) return;





  /* =========================================================

     1. LANGUAGE

  ========================================================= */



  const langValue =

    window.frappe?.boot?.lang ||

    document.documentElement.lang ||

    "en";



  const isArabic =

    String(langValue)

      .toLowerCase()

      .startsWith("ar");



  root.setAttribute(

    "dir",

    isArabic ? "rtl" : "ltr"

  );





  /* =========================================================

     2. HELPERS

  ========================================================= */



  function escapeHtml(value) {



    return String(value ?? "")

      .replace(/&/g, "&amp;")

      .replace(/</g, "&lt;")

      .replace(/>/g, "&gt;")

      .replace(/"/g, "&quot;")

      .replace(/'/g, "&#039;");

  }





  function formatNumber(value) {



    return (

      parseFloat(value) || 0

    ).toLocaleString("en-US");

  }





  function getToday() {



    try {



      if (

        frappe.datetime &&

        frappe.datetime.get_today

      ) {



        return frappe.datetime.get_today();



      }



    } catch (e) {}



    return new Date()

      .toISOString()

      .slice(0, 10);

  }





  function safeCount(

    doctype,

    filters = {}

  ) {



    return new Promise(resolve => {



      try {



        frappe.call({



          method:

            "frappe.client.get_count",



          args: {

            doctype,

            filters

          },



          callback: r => {



            resolve(

              r?.message || 0

            );



          },



          error: () =>

            resolve(0)



        });



      } catch (e) {



        console.error(

          "Project Count Error:",

          doctype,

          e

        );



        resolve(0);



      }



    });



  }





  function openRoute(name) {



    try {



      if (

        reportNames.has(name)

      ) {



        frappe.set_route(

          "query-report",

          name

        );



        return;



      }





      frappe.set_route(

        "List",

        name

      );



    } catch (e) {



      console.error(

        "Project Route Error:",

        name,

        e

      );



    }



  }





  function newDoc(doctype) {



    try {



