                      ${escapeHtml(

                        isArabic

                          ? card.descriptionAr

                          : card.descriptionEn

                      )}



                    </span>



                  </button>





                  ${

                    index <

                    projectCycleCards.length - 1



                      ? `

                        <span

                          class="erp-cycle-arrow"

                        >

                          ${

                            isArabic

                              ? "←"

                              : "→"

                          }

                        </span>

                      `



                      : ""

                  }



                </div>



              `

            )

            .join("")}



        </div>



      </section>



    `;





    projectCycle.addEventListener(

      "click",

      event => {



        const element =

          event.target.closest(

            "[data-project-cycle]"

          );





        if (!element)

          return;





        const card =

          projectCycleCards[

            Number(

              element.dataset.projectCycle

            )

          ];





        if (!card)

          return;





        if (

          card.action === "new"

        ) {



          newDoc(

            card.doctype

          );



          return;



        }





        if (

          card.action === "team"

        ) {



          showSelector(



            "الفريق والموارد",

            "Team & Resources",



            [

              {

                doctype:

                  "Employee",



                labelAr:

                  "الموظفون",



                labelEn:

                  "Employees"

              },



              {

                doctype:

                  "Activity Type",



                labelAr:

                  "أنواع الأنشطة",



                labelEn:

                  "Activity Types"

              },



              {

                doctype:

                  "Activity Cost",



                labelAr:

                  "تكلفة الأنشطة",



                labelEn:

                  "Activity Costs"

              }

            ]



          );



          return;



        }





        if (

          card.action === "costs"

        ) {



          showSelector(



            "تكاليف المشروع",

            "Project Costs",



            [

              {

                doctype:

                  "Expense Claim",



                labelAr:

                  "المصروفات",



                labelEn:

                  "Expenses"

              },



              {

                doctype:

                  "Employee Advance",



                labelAr:

                  "سلف الموظفين",



                labelEn:

                  "Employee Advances"

              },



              {

                doctype:

                  "Journal Entry",



                labelAr:

                  "قيود اليومية",



                labelEn:

                  "Journal Entries"

              }

            ]



          );



          return;



        }





        openRoute(

          card.doctype

        );



      }

    );



  }





  /* =========================================================

     10. RENDER STATS

  ========================================================= */



  function renderStats() {



    if (!statsSection)

      return;





    statsSection.innerHTML = `



      <section class="erp-overview-container">



        <h2 class="erp-section-title">



          ${

            isArabic

              ? "نظرة عامة"

              : "Overview"

          }



        </h2>





        <div class="erp-stats-grid">



          ${statsCards

            .map(

              (card, index) => `



                <div

                  class="

                    erp-stat-card

                    overview-tone-${index + 1}

                  "

                >



                  <div class="erp-stat-icon">

                    ${escapeHtml(card.short)}

                  </div>





                  <div class="erp-stat-info">



                    <span

                      class="erp-stat-value"

                      data-project-stat="${card.id}"

                    >

                      0

                    </span>





                    <span

                      class="erp-stat-label"

                    >



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>



                  </div>



                </div>



              `

            )

            .join("")}



        </div>



      </section>



    `;





    statsCards.forEach(

      card => {



        Promise

          .resolve()

          .then(

            () => card.fetch()

          )

          .then(

            value => {



              const element =

                statsSection.querySelector(

                  `[data-project-stat="${card.id}"]`

                );





              if (element) {



                element.textContent =

                  formatNumber(value);



              }



            }

          )

          .catch(

            error => {



              console.error(

                "Project Stat Error:",

                card.id,

                error

              );



            }

          );



      }

    );



  }





  /* =========================================================

     11. QUICK ACTIONS

  ========================================================= */



  function renderQuickActions() {



    if (!quickActions)

      return;





    quickActions.innerHTML = `



      <h2 class="erp-section-title">



        ${

          isArabic

            ? "اختصارات سريعة"

            : "Quick Actions"

        }



      </h2>





      <div class="erp-quick-grid">



        ${quickActionButtons

          .map(

            (button, index) => `



              <button

                type="button"

                class="erp-quick-btn"

                data-project-quick="${index}"

              >



                <span

                  class="erp-quick-label"

                >



                  ${escapeHtml(

                    isArabic

                      ? button.labelAr

                      : button.labelEn

                  )}



                </span>



              </button>



            `

          )

          .join("")}



      </div>



    `;





    quickActions.addEventListener(

      "click",

      event => {



        const element =

          event.target.closest(

            "[data-project-quick]"

          );





        if (!element)

          return;





        const button =

          quickActionButtons[

            Number(

              element.dataset.projectQuick

            )

          ];





        if (!button)

          return;





        newDoc(

          button.doctype

        );



      }

    );



  }





  /* =========================================================

     12. RENDER LOWER SECTIONS

  ========================================================= */



  function renderSections() {



    if (!content)

      return;





    content.innerHTML =

      sections

        .map(

          (section, sectionIndex) => {



            const cards =

              section[1]

                .map(

                  (card, cardIndex) => {



                    const links =

                      card[2]

                        .map(

                          item => `



                            <div

                              class="erp-link-row"

                            >



                              <button

                                type="button"

                                class="erp-link"

                                data-project-route="${escapeHtml(item)}"

                              >



                                <span

                                  class="erp-link-text"

                                >

                                  ${escapeHtml(translate(item))}

                                </span>





                                <span

                                  class="erp-link-arrow"

                                >

                                  ${

                                    isArabic

                                      ? "←"

                                      : "→"

                                  }

                                </span>



                              </button>



                            </div>



                          `

                        )

                        .join("");





                    return `



                      <article

                        class="

                          erp-card

                          tone-${(sectionIndex + cardIndex) % 5}

                        "

                        data-project-card

                      >



                        <button

                          type="button"

                          class="erp-card-heading"

                          data-project-toggle

                          aria-expanded="false"

                        >



                          <span class="erp-icon">

                            ${card[1]}

                          </span>





                          <span

                            class="erp-card-title"

                          >

                            ${escapeHtml(translate(card[0]))}

                          </span>





                          <span

                            class="erp-card-chevron"

                          >

                            ⌄

                          </span>



                        </button>





                        <div

                          class="erp-card-links"

                        >

                          ${links}

                        </div>



                      </article>



                    `;



                  }

                )

                .join("");





            return `



              <section

                class="erp-module-section"

              >



                <h2

                  class="erp-section-title"

                >

                  ${escapeHtml(translate(section[0]))}

                </h2>





                <div

                  class="erp-dashboard-grid"

                >

                  ${cards}

                </div>



              </section>



            `;



          }

        )

        .join("");





    content.addEventListener(

      "click",

      event => {



        const routeButton =

          event.target.closest(

            "[data-project-route]"

          );





        if (routeButton) {



          event.preventDefault();



          openRoute(

            routeButton.dataset.projectRoute

          );



          return;



        }





        const toggleButton =

          event.target.closest(

            "[data-project-toggle]"

          );





        if (!toggleButton)

          return;





        const selectedCard =

          toggleButton.closest(

            "[data-project-card]"

          );





        if (!selectedCard)

          return;





        const shouldOpen =

          !selectedCard.classList.contains(

            "is-open"

          );





        content

          .querySelectorAll(

            "[data-project-card]"

          )

          .forEach(

            card => {



              if (

                card !== selectedCard

              ) {



                card.classList.remove(

                  "is-open"

                );



              }



            }

          );





        selectedCard

          .classList

          .toggle(

            "is-open",

            shouldOpen

          );



      }

    );



  }





  /* =========================================================

     13. FOOTER

  ========================================================= */



  function renderFooter() {



    if (!footerEl)

      return;





    footerEl.innerHTML = `



      <div class="erp-footer-inner">



        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ☎

          </span>



          <span class="erp-footer-label">

            ${

              isArabic

                ? "الهاتف الموحد:"

                : "Phone:"

            }

          </span>



          <a

            href="tel:0115110455"

            class="erp-footer-link"

            dir="ltr"

          >

            0115110455

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ✉

          </span>



          <span class="erp-footer-label">

            ${

              isArabic

                ? "البريد الإلكتروني:"

                : "Email:"

            }

          </span>



          <a

            href="mailto:sales@mubtkir.com"

            class="erp-footer-link"

          >

            sales@mubtkir.com

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ◎

          </span>



          <span class="erp-footer-label">

            ${

              isArabic

                ? "الموقع:"

                : "Website:"

            }

          </span>



          <a

            href="https://www.mubtkir.com"

            class="erp-footer-link"

            target="_blank"

            rel="noopener"

          >

            www.mubtkir.com

          </a>



        </div>



      </div>



    `;



  }





  /* =========================================================

     14. INIT

  ========================================================= */



  try {



    renderProjectCycle();



  } catch (e) {



    console.error(

      "Project Cycle Error:",

      e

    );



  }





  try {



    renderStats();



  } catch (e) {



    console.error(

      "Project Stats Error:",

      e

    );



  }





  try {



    renderQuickActions();



  } catch (e) {



    console.error(

      "Project Quick Actions Error:",

      e

    );



  }





  try {



    renderSections();



  } catch (e) {



    console.error(

      "Project Sections Error:",

      e

    );



  }





  try {



    renderFooter();



  } catch (e) {



    console.error(

      "Project Footer Error:",

      e

    );



  }



})();

