        "أدخل وصف الحملة",



        "اضغط «حفظ»",



        "اربط العملاء المحتملين والفرص بالحملة"



      ],



      stepsEn: [



        "Click «New Campaign»",



        "Enter campaign name",



        "Set start and end dates",



        "Enter campaign description",



        "Click «Save»",



        "Link Leads and Opportunities to the campaign"



      ]



    },





    "Email Campaign": {



      icon: "✉️",



      summaryAr:

        "إرسال سلسلة رسائل بريد إلكتروني للعملاء المحتملين أو جهات الاتصال وفق جدول زمني.",



      summaryEn:

        "Send scheduled email campaigns to Leads or Contacts.",



      stepsAr: [



        "اضغط «حملة بريد جديدة»",



        "حدد المستلم",



        "حدد الحملة",



        "حدد تاريخ البداية",



        "راجع قوالب البريد",



        "اضغط «حفظ»"



      ],



      stepsEn: [



        "Click «New Email Campaign»",



        "Select recipient",



        "Select Campaign",



        "Set start date",



        "Review email templates",



        "Click «Save»"



      ]



    },





    "CRM Settings": {



      icon: "⚙️",



      summaryAr:

        "إعداد طريقة إدارة العملاء المحتملين والفرص وبعض خيارات التكرار والمتابعة في CRM.",



      summaryEn:

        "Configure Lead, Opportunity and CRM workflow behavior.",



      stepsAr: [



        "افتح «إعدادات إدارة العملاء»",



        "راجع إعدادات العملاء المحتملين",



        "راجع إعدادات التكرار",



        "راجع إعدادات الفرص",



        "راجع خيارات نقل التواصل",



        "احفظ التغييرات"



      ],



      stepsEn: [



        "Open CRM Settings",



        "Review Lead settings",



        "Review duplication settings",



        "Review Opportunity settings",



        "Review communication settings",



        "Save changes"



      ]



    }



  };





  /* =========================================================

     12. INFO MODAL

  ========================================================= */



  function showInfoModal(data) {



    const title =

      isArabic

        ? data.labelAr

        : data.labelEn;



    const summary =

      isArabic

        ? data.summaryAr

        : data.summaryEn;



    const steps =

      isArabic

        ? data.stepsAr

        : data.stepsEn;



    const hasSteps =

      Array.isArray(steps) &&

      steps.length > 0;





    const overlay =

      document.createElement("div");



    overlay.className =

      "erp-modal-overlay";



    overlay.setAttribute(

      "dir",

      isArabic ? "rtl" : "ltr"

    );





    overlay.innerHTML = `



      <div class="erp-modal-box">



        <button

          type="button"

          class="erp-modal-close"

          data-modal-close

        >

          ✕

        </button>





        <div class="erp-modal-header">



          <span class="erp-modal-icon">

            ${data.icon || "📄"}

          </span>



          <h3 class="erp-modal-title">

            ${escapeHtml(title)}

          </h3>



        </div>





        <p class="erp-modal-summary">

          ${escapeHtml(summary)}

        </p>





        ${

          hasSteps

            ? `



              <button

                type="button"

                class="erp-modal-toggle-steps"

                data-toggle-steps

              >

                ${

                  isArabic

                    ? "📖 عرض الخطوات"

                    : "📖 Show Steps"

                }

              </button>





              <div

                class="erp-modal-steps"

                data-modal-steps

              >



                <ol class="erp-modal-steps-list">



                  ${steps

                    .map(

                      step =>

                        `<li>${escapeHtml(step)}</li>`

                    )

                    .join("")}



                </ol>



              </div>



            `

            : ""

        }



      </div>



    `;





    root.appendChild(overlay);





    requestAnimationFrame(() => {



      overlay.classList.add(

        "is-visible"

      );



    });





    overlay

      .querySelector(

        "[data-modal-close]"

      )

      ?.addEventListener(

        "click",

        () => overlay.remove()

      );





    overlay.addEventListener(



      "click",



      event => {



        if (event.target === overlay)

          overlay.remove();



      }



    );





    const toggleButton =

      overlay.querySelector(

        "[data-toggle-steps]"

      );



    const stepsContainer =

      overlay.querySelector(

        "[data-modal-steps]"

      );





    if (

      toggleButton &&

      stepsContainer

    ) {



      toggleButton.addEventListener(



        "click",



        () => {



          stepsContainer

            .classList

            .toggle(

              "is-shown"

            );





          toggleButton.textContent =

            stepsContainer

              .classList

              .contains(

                "is-shown"

              )



              ? (

                  isArabic

                    ? "📖 إخفاء الخطوات"

                    : "📖 Hide Steps"

                )



              : (

                  isArabic

                    ? "📖 عرض الخطوات"

                    : "📖 Show Steps"

                );



        }



      );



    }



  }





  /* =========================================================

     13. ROUTING

  ========================================================= */



  function openRoute(name) {



    if (

      !window.frappe ||

      typeof frappe.set_route !==

        "function"

    )

      return;





    if (

      reportNames.has(name)

    ) {



      frappe.set_route(

        "query-report",

        name

      );



      return;



    }





    if (

      singleDocs.has(name)

    ) {



      frappe.set_route(

        "Form",

        name

      );



      return;



    }





    if (

      treeDocs.has(name)

    ) {



      frappe.set_route(

        "Tree",

        name

      );



      return;



    }





    frappe.set_route(

      "List",

      name

    );



  }





  /* =========================================================

     14. RENDER CRM CYCLE

  ========================================================= */



  function renderCrmCycle() {



    if (!crmCycle)

      return;





    crmCycle.innerHTML = `



      <section class="erp-cycle-container">



        <h2

          class="

            erp-section-title

            erp-cycle-title

          "

        >

          ${

            isArabic

              ? "دورة إدارة علاقات العملاء"

              : "CRM Cycle"

          }

        </h2>





        <div

          class="erp-cycle-grid"

          style="

            grid-template-columns:

            repeat(

              ${crmCycleCards.length},

              minmax(0,1fr)

            );

          "

        >



          ${crmCycleCards



            .map(

              (card, index) => `



                <div class="erp-cycle-item">



                  <button

                    type="button"

                    class="

                      erp-cycle-card

                      cycle-tone-${(index % 4) + 1}

                    "

                    data-cycle-index="${index}"

                  >



                    <span class="erp-cycle-number">

                      ${card.step}

                    </span>





                    <span class="erp-cycle-card-title">



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>





                    <span class="erp-cycle-description">



                      ${escapeHtml(

                        isArabic

                          ? card.descriptionAr

                          : card.descriptionEn

                      )}



                    </span>



                  </button>





                  ${

                    index <

                    crmCycleCards.length - 1



                      ? `

                        <span

                          class="erp-cycle-arrow"

                          aria-hidden="true"

                        >

                          ${

                            isArabic

                              ? "←"

                              : "→"

                          }

                        </span>

                      `



                      : ""

                  }



                </div>



              `

            )



            .join("")}



        </div>



      </section>



    `;





    crmCycle.addEventListener(



      "click",



      event => {



        const element =

          event.target.closest(

            "[data-cycle-index]"

          );





        if (!element)

          return;





        const card =

          crmCycleCards[

            Number(

              element.dataset.cycleIndex

            )

          ];





        if (!card)

          return;





        openRoute(

          card.doctype

        );



      }



    );



  }





  /* =========================================================

     15. RENDER STATS

  ========================================================= */



  function renderStats() {



    if (!statsSection)

      return;





    statsSection.innerHTML = `



      <section class="erp-overview-container">



        <h2 class="erp-section-title">

          ${

            isArabic

              ? "نظرة عامة"

              : "Overview"

          }

        </h2>





        <div class="erp-stats-grid">



          ${statsCards



            .map(

              (card, index) => `



                <div

                  class="

                    erp-stat-card

                    overview-tone-${index + 1}

                  "

                >



                  <div class="erp-stat-icon">

                    ${escapeHtml(card.short)}

                  </div>





                  <div class="erp-stat-info">



                    <span

                      class="erp-stat-value"

                      data-stat-id="${card.id}"

                    >

                      ...

                    </span>





                    <span class="erp-stat-label">



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>



                  </div>



                </div>



              `

            )



            .join("")}



        </div>



      </section>



    `;





    statsCards.forEach(card => {



      card.fetch().then(value => {



        const element =

          statsSection.querySelector(

            `[data-stat-id="${card.id}"]`

          );





        if (!element)

          return;





        element.textContent =

          card.isCurrency



            ? `${formatCurrency(value)} ${

                isArabic

                  ? "ر.س"

                  : "SAR"

              }`



            : formatNumber(value);



      });



    });



  }





  /* =========================================================

     16. QUICK ACTIONS

  ========================================================= */



  function renderQuickActions() {



    if (!quickActions)

      return;





    quickActions.innerHTML = `



      <h2 class="erp-section-title">



        ${

          isArabic

            ? "اختصارات سريعة"

            : "Quick Actions"

        }



      </h2>





      <div class="erp-quick-grid">



        ${quickActionButtons



          .map(

            (button, index) => `



              <button

                type="button"

                class="erp-quick-btn"

                data-quick-index="${index}"

              >



                <span class="erp-quick-label">



                  ${escapeHtml(

                    isArabic

                      ? button.labelAr

                      : button.labelEn

                  )}



                </span>



              </button>



            `

          )



          .join("")}



      </div>



    `;





    quickActions.addEventListener(



      "click",



      event => {



        const element =

          event.target.closest(

            "[data-quick-index]"

          );





        if (!element)

          return;





        const button =

          quickActionButtons[

            Number(

              element.dataset.quickIndex

            )

          ];





        if (!button)

          return;





        frappe.new_doc(

          button.doctype

        );



      }



    );



  }





  /* =========================================================

     17. RENDER SECTIONS

  ========================================================= */



  function renderSections() {



    content.innerHTML =

      sections



        .map(

          (section, sectionIndex) => {





            const cards =

              section[1]



                .map(

                  (card, cardIndex) => {





                    const links =

                      card[2]



                        .map(

                          item => {





                            const description =

                              itemDescriptions[item];





                            return `



                              <div class="erp-link-row">



                                <button

                                  type="button"

                                  class="erp-link"

                                  data-route-name="${escapeHtml(item)}"

                                >



                                  <span class="erp-link-text">

                                    ${escapeHtml(translate(item))}

                                  </span>





                                  <span class="erp-link-arrow">

                                    ${

                                      isArabic

                                        ? "←"

                                        : "→"

                                    }

                                  </span>



                                </button>





                                ${

                                  description



                                    ? `



                                      <button

                                        type="button"

                                        class="erp-info-link"

                                        data-info-item="${escapeHtml(item)}"

                                      >

                                        ${

                                          isArabic

                                            ? "تفاصيل"

                                            : "Details"

                                        }

                                      </button>



                                    `



                                    : ""

                                }



                              </div>



                            `;



                          }

                        )



                        .join("");





                    return `



                      <article

                        class="

                          erp-card

                          tone-${(sectionIndex + cardIndex) % 5}

                        "

                        data-erp-card

                      >



                        <button

                          type="button"

                          class="erp-card-heading"

                          data-card-toggle

                          aria-expanded="false"

                        >



                          <span class="erp-icon">

                            ${card[1]}

                          </span>





                          <span class="erp-card-title">

                            ${escapeHtml(translate(card[0]))}

                          </span>





                          <span class="erp-card-chevron">

                            ⌄

                          </span>



                        </button>





                        <div class="erp-card-links">

                          ${links}

                        </div>



                      </article>



                    `;



                  }

                )



                .join("");





            return `



              <section class="erp-module-section">



                <h2 class="erp-section-title">

                  ${escapeHtml(translate(section[0]))}

                </h2>





                <div class="erp-dashboard-grid">

                  ${cards}

                </div>



              </section>



            `;



          }

        )



        .join("");



  }





  /* =========================================================

     18. FOOTER

  ========================================================= */



  function renderFooter() {



    if (!footerEl)

      return;





    footerEl.innerHTML = `



      <div class="erp-footer-inner">



        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ☎

          </span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? footerInfo.labels.phoneAr

                : footerInfo.labels.phoneEn

            }:



          </span>



          <a

            href="tel:${footerInfo.phone}"

            class="erp-footer-link"

            dir="ltr"

          >

            ${footerInfo.phone}

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ✉

          </span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? footerInfo.labels.emailAr

                : footerInfo.labels.emailEn

            }:



          </span>



          <a

            href="mailto:${footerInfo.email}"

            class="erp-footer-link"

          >

            ${footerInfo.email}

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ◎

          </span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? footerInfo.labels.websiteAr

                : footerInfo.labels.websiteEn

            }:



          </span>



          <a

            href="https://${footerInfo.website}"

            class="erp-footer-link"

            target="_blank"

            rel="noopener"

          >

            ${footerInfo.website}

          </a>



        </div>



      </div>



    `;



  }





  /* =========================================================

     19. EVENTS

  ========================================================= */



  let lastToggleTime = 0;





  content.addEventListener(



    "click",



    event => {





      /* DETAILS */



      const infoButton =

        event.target.closest(

          "[data-info-item]"

        );





      if (infoButton) {



        event.preventDefault();

        event.stopPropagation();





        const itemName =

          infoButton.dataset.infoItem;





        const data =

          itemDescriptions[itemName];





        if (data) {



          showInfoModal({



            ...data,



            labelAr:

              translate(itemName),



            labelEn:

              itemName



          });



        }





        return;



      }





      /* ROUTE */



      const routeButton =

        event.target.closest(

          "[data-route-name]"

        );





      if (routeButton) {



        event.preventDefault();

        event.stopPropagation();





        openRoute(

          routeButton.dataset.routeName

        );





        return;



      }





      /* CARD */



      const cardButton =

        event.target.closest(

          "[data-card-toggle]"

        );





      if (!cardButton)

        return;





      const now =

        Date.now();





      if (

        now - lastToggleTime <

        400

      )

        return;





      lastToggleTime =

        now;





      const selectedCard =

        cardButton.closest(

          "[data-erp-card]"

        );





      if (!selectedCard)

        return;





      const shouldOpen =

        !selectedCard

          .classList

          .contains(

            "is-open"

          );





      content

        .querySelectorAll(

          "[data-erp-card]"

        )

        .forEach(card => {



          if (

            card !== selectedCard

          ) {



            card

              .classList

              .remove(

                "is-open"

              );



          }



        });





      selectedCard

        .classList

        .toggle(

          "is-open",

          shouldOpen

        );



    }



  );





  /* =========================================================

     20. INIT

  ========================================================= */



  renderCrmCycle();



  renderStats();



  renderQuickActions();



  renderSections();



  renderFooter();



})();

style:
/* =========================================================

   MUBTKIR ERP — BUYING WORKSPACE

   Unified Professional Brand Theme

   لوحة تحكم قسم المشتريات

========================================================= */





/* =========================================================

   1. ROOT + BRAND COLORS

   ألوان الهوية الرسمية

========================================================= */



.erp-dashboard-wrapper {



  --brand-primary: #3867AE;

  --brand-secondary: #0F84B5;

  --brand-accent: #0BA1B8;

  --brand-purple: #644DA6;



  --brand-text: #243B63;

  --brand-muted: #66758A;



  --brand-border: rgba(56, 103, 174, 0.22);

  --brand-border-strong: rgba(56, 103, 174, 0.38);



  --brand-soft: rgba(56, 103, 174, 0.07);

  --brand-soft-secondary: rgba(15, 132, 181, 0.07);

  --brand-soft-accent: rgba(11, 161, 184, 0.07);

  --brand-soft-purple: rgba(100, 77, 166, 0.07);



  position: relative;

  isolation: isolate;



  width: 100%;



  padding: 14px 16px 36px;



  overflow: visible;



  color: var(--brand-text);

}





/* =========================================================

   2. FONT

========================================================= */



.erp-dashboard-wrapper,

.erp-dashboard-wrapper * {



  box-sizing: border-box;



  font-family:

    "Tajawal",

    "Inter",

    Arial,

    sans-serif !important;

}





/* =========================================================

   3. RTL

========================================================= */



.erp-dashboard-wrapper.erp-dashboard-rtl {



  direction: rtl;

  text-align: right;

}





/* =========================================================

   BACKGROUND

   صورة واحدة في الخلفية بدون تكرار

========================================================= */



.erp-dashboard-bg {

    position: absolute !important;



    top: 50px;

    left: 50%;



    /* حجم الصورة */

    width: 78%;

    max-width: 1200px;



    height: auto;



    transform: translateX(-50%);



    /* الشفافية */

    opacity: 0.03;



    object-fit: contain;



    pointer-events: none;

    user-select: none;



    z-index: 0;

}





/* الحاوية الرئيسية */

.erp-dashboard-wrapper {

    position: relative !important;

    isolation: isolate;

}





/* المحتوى فوق الخلفية */

.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

    position: relative !important;

    z-index: 2;

}



/* =========================================================

   المحتوى فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



    position: relative;



    z-index: 2;

}

/* =========================================================

   إبقاء جميع عناصر الداشبورد فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

    position: relative;

    z-index: 2;

}



/* =========================================================

   5. CONTENT LAYER

   جميع المحتويات تظهر فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



  position: relative;



  z-index: 2;

}





.erp-dashboard-content,

.erp-module-section,

.erp-dashboard-grid {



  background: transparent !important;

}





/* =========================================================

   6. SECTION TITLE

========================================================= */



.erp-section-title {



  position: relative;



  display: flex;

  align-items: center;



  min-height: 36px;



  margin: 0 0 16px;



  padding: 0 0 10px;



  border-bottom:

    1px solid var(--brand-border);



  color:

    var(--brand-text) !important;



  font-size: 18px;

  font-weight: 700;



  line-height: 1.4;

}





.erp-section-title::after {



  content: "";



  position: absolute;



  bottom: -1px;



  width: 52px;

  height: 2px;



  border-radius: 20px;



  background: var(--brand-primary);

}





.erp-dashboard-rtl

.erp-section-title::after {



  right: 0;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-section-title::after {



  left: 0;

}





/* =========================================================

   7. PURCHASE CYCLE SECTION

========================================================= */



.erp-purchase-cycle-section {



  margin: 18px 0 24px;

}





.erp-cycle-container {



  position: relative;



  padding: 18px 18px 20px;



  border:

    1px solid var(--brand-border);



  border-radius: 16px;



  /*

     شبه معتم حتى يبقى الـ Pattern ظاهراً بخفة

  */



  background:

    rgba(255, 255, 255, 0.94);



  box-shadow:

    0 5px 18px rgba(36, 59, 99, 0.06);

}





.erp-cycle-title {



  margin-bottom: 20px;

}





/* =========================================================

   SALES / PURCHASE CYCLE GRID

   توزيع البطاقات على كامل عرض الصفحة

========================================================= */



.erp-cycle-grid {

  display: grid;



  grid-template-columns:

    repeat(5, minmax(0, 1fr));



  gap: 18px;



  width: 100%;



  align-items: stretch;

}





.erp-cycle-item {

  position: relative;



  display: flex;



  width: 100%;



  min-width: 0;

}





/* البطاقة تتمدد حسب عرض العمود */

.erp-cycle-card {

  width: 100%;



  min-width: 0;



  min-height: 180px;

}



/* =========================================================

   9. PURCHASE CYCLE CARD

========================================================= */



.erp-cycle-card {



  --cycle-color:

    var(--brand-primary);



  --cycle-soft:

    var(--brand-soft);



  position: relative;



  display: flex;



  flex-direction: column;



  align-items: center;

  justify-content: flex-start;



  width: 100%;



  min-width: 0;

  min-height: 180px;



  padding: 17px 11px 15px;



  overflow: hidden;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  outline: none;



  background:

    rgba(255, 255, 255, 0.96);



  color:

    var(--brand-text) !important;



  font-family: inherit;



  text-align: center;



  cursor: pointer;



  transition:

