          ✕

        </button>





        <div class="erp-modal-header">



          <span class="erp-modal-icon">

            ${data.icon || "📄"}

          </span>



          <h3 class="erp-modal-title">

            ${escapeHtml(title)}

          </h3>



        </div>





        <p class="erp-modal-summary">

          ${escapeHtml(summary)}

        </p>





        ${

          hasSteps

            ? `



              <button

                type="button"

                class="erp-modal-toggle-steps"

                data-toggle-steps

              >

                ${

                  isArabic

                    ? "📖 عرض الخطوات"

                    : "📖 Show Steps"

                }

              </button>





              <div

                class="erp-modal-steps"

                data-modal-steps

              >



                <ol class="erp-modal-steps-list">



                  ${steps

                    .map(

                      step =>

                        `<li>${escapeHtml(step)}</li>`

                    )

                    .join("")}



                </ol>



              </div>



            `

            : ""

        }



      </div>



    `;





    root.appendChild(overlay);





    requestAnimationFrame(() => {



      overlay.classList.add(

        "is-visible"

      );



    });





    overlay

      .querySelector("[data-modal-close]")

      ?.addEventListener(

        "click",

        () => overlay.remove()

      );





    overlay.addEventListener(



      "click",



      event => {



        if (event.target === overlay)

          overlay.remove();



      }



    );





    const toggleButton =

      overlay.querySelector(

        "[data-toggle-steps]"

      );



    const stepsContainer =

      overlay.querySelector(

        "[data-modal-steps]"

      );





    if (

      toggleButton &&

      stepsContainer

    ) {



      toggleButton.addEventListener(



        "click",



        () => {



          stepsContainer.classList.toggle(

            "is-shown"

          );





          toggleButton.textContent =

            stepsContainer.classList.contains(

              "is-shown"

            )

              ? (

                  isArabic

                    ? "📖 إخفاء الخطوات"

                    : "📖 Hide Steps"

                )

              : (

                  isArabic

                    ? "📖 عرض الخطوات"

                    : "📖 Show Steps"

                );



        }



      );



    }



  }





  /* =========================================================

     12. RENDER SUPPORT CYCLE

  ========================================================= */



  function renderSupportCycle() {



    if (!supportCycle)

      return;





    supportCycle.innerHTML = `



      <section class="erp-cycle-container">



        <h2

          class="

            erp-section-title

            erp-cycle-title

          "

        >

          ${

            isArabic

              ? "دورة الدعم"

              : "Support Cycle"

          }

        </h2>





        <div

          class="erp-cycle-grid"

          style="

            grid-template-columns:

            repeat(

              ${supportCycleCards.length},

              minmax(0,1fr)

            );

          "

        >



          ${supportCycleCards



            .map(

              (card, index) => `



                <div class="erp-cycle-item">



                  <button

                    type="button"

                    class="

                      erp-cycle-card

                      cycle-tone-${(index % 4) + 1}

                    "

                    data-cycle-index="${index}"

                  >



                    <span class="erp-cycle-number">

                      ${card.step}

                    </span>





                    <span class="erp-cycle-card-title">



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>





                    <span class="erp-cycle-description">



                      ${escapeHtml(

                        isArabic

                          ? card.descriptionAr

                          : card.descriptionEn

                      )}



                    </span>



                  </button>





                  ${

                    index <

                    supportCycleCards.length - 1



                      ? `

                        <span

                          class="erp-cycle-arrow"

                          aria-hidden="true"

                        >

                          ${isArabic ? "←" : "→"}

                        </span>

                      `



                      : ""

                  }



                </div>



              `

            )



            .join("")}



        </div>



      </section>



    `;





    supportCycle.addEventListener(



      "click",



      event => {



        const element =

          event.target.closest(

            "[data-cycle-index]"

          );





        if (!element)

          return;





        const card =

          supportCycleCards[

            Number(

              element.dataset.cycleIndex

            )

          ];





        if (!card)

          return;





        if (card.action === "new") {



          frappe.new_doc(

            card.doctype

          );



          return;



        }





        openRoute(

          card.doctype

        );



      }



    );



  }





  /* =========================================================

     13. RENDER STATS

  ========================================================= */



  function renderStats() {



    if (!statsSection)

      return;





    statsSection.innerHTML = `



      <section class="erp-overview-container">



        <h2 class="erp-section-title">



          ${

            isArabic

              ? "نظرة عامة"

              : "Overview"

          }



        </h2>





        <div class="erp-stats-grid">



          ${statsCards



            .map(

              (card, index) => `



                <div

                  class="

                    erp-stat-card

                    overview-tone-${index + 1}

                  "

                >



                  <div class="erp-stat-icon">

                    ${escapeHtml(card.short)}

                  </div>





                  <div class="erp-stat-info">



                    <span

                      class="erp-stat-value"

                      data-stat-id="${card.id}"

                    >

                      ...

                    </span>





                    <span class="erp-stat-label">



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>



                  </div>



                </div>



              `

            )



            .join("")}



        </div>



      </section>



    `;





    statsCards.forEach(card => {



      try {



        card

          .fetch()

          .then(value => {



            const element =

              statsSection.querySelector(

                `[data-stat-id="${card.id}"]`

              );





            if (element) {



              element.textContent =

                formatNumber(value);



            }



          })

          .catch(() => {



            const element =

              statsSection.querySelector(

                `[data-stat-id="${card.id}"]`

              );



            if (element)

              element.textContent = "0";



          });



      }



      catch (e) {



        const element =

          statsSection.querySelector(

            `[data-stat-id="${card.id}"]`

          );



        if (element)

          element.textContent = "0";



      }



    });



  }





  /* =========================================================

     14. QUICK ACTIONS

  ========================================================= */



  function renderQuickActions() {



    if (!quickActions)

      return;





    quickActions.innerHTML = `



      <h2 class="erp-section-title">



        ${

          isArabic

            ? "اختصارات سريعة"

            : "Quick Actions"

        }



      </h2>





      <div class="erp-quick-grid">



        ${quickActionButtons



          .map(

            (button, index) => `



              <button

                type="button"

                class="erp-quick-btn"

                data-quick-index="${index}"

              >



                <span class="erp-quick-label">



                  ${escapeHtml(

                    isArabic

                      ? button.labelAr

                      : button.labelEn

                  )}



                </span>



              </button>



            `

          )



          .join("")}



      </div>



    `;





    quickActions.addEventListener(



      "click",



      event => {



        const element =

          event.target.closest(

            "[data-quick-index]"

          );





        if (!element)

          return;





        const button =

          quickActionButtons[

            Number(

              element.dataset.quickIndex

            )

          ];





        if (!button)

          return;





        if (button.action === "new") {



          frappe.new_doc(

            button.doctype

          );



          return;



        }





        openRoute(

          button.doctype

        );



      }



    );



  }





  /* =========================================================

     15. RENDER SECTIONS

  ========================================================= */



  function renderSections() {



    content.innerHTML =

      sections



        .map(

          (section, sectionIndex) => {





            const cards =

              section[1]



                .map(

                  (card, cardIndex) => {





                    const links =

                      card[2]



                        .map(

                          item => {





                            const description =

                              itemDescriptions[item];





                            return `



                              <div class="erp-link-row">



                                <button

                                  type="button"

                                  class="erp-link"

                                  data-route-name="${escapeHtml(item)}"

                                >



                                  <span class="erp-link-text">

                                    ${escapeHtml(translate(item))}

                                  </span>





                                  <span class="erp-link-arrow">

                                    ${isArabic ? "←" : "→"}

                                  </span>



                                </button>





                                ${

                                  description



                                    ? `

                                      <button

                                        type="button"

                                        class="erp-info-link"

                                        data-info-item="${escapeHtml(item)}"

                                      >

                                        ${

                                          isArabic

                                            ? "تفاصيل"

                                            : "Details"

                                        }

                                      </button>

                                    `



                                    : ""

                                }



                              </div>



                            `;



                          }

                        )



                        .join("");





                    return `



                      <article

                        class="

                          erp-card

                          tone-${(sectionIndex + cardIndex) % 5}

                        "

                        data-erp-card

                      >



                        <button

                          type="button"

                          class="erp-card-heading"

                          data-card-toggle

                          aria-expanded="false"

                        >



                          <span class="erp-icon">

                            ${card[1]}

                          </span>





                          <span class="erp-card-title">

                            ${escapeHtml(translate(card[0]))}

                          </span>





                          <span class="erp-card-chevron">

                            ⌄

                          </span>



                        </button>





                        <div class="erp-card-links">

                          ${links}

                        </div>



                      </article>



                    `;



                  }

                )



                .join("");





            return `



              <section class="erp-module-section">



                <h2 class="erp-section-title">

                  ${escapeHtml(translate(section[0]))}

                </h2>





                <div class="erp-dashboard-grid">

                  ${cards}

                </div>



              </section>



            `;



          }

        )



        .join("");



  }





  /* =========================================================

     16. FOOTER

  ========================================================= */



  function renderFooter() {



    if (!footerEl)

      return;





    footerEl.innerHTML = `



      <div class="erp-footer-inner">



        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ☎

          </span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? footerInfo.labels.phoneAr

                : footerInfo.labels.phoneEn

            }:



          </span>



          <a

            href="tel:${footerInfo.phone}"

            class="erp-footer-link"

            dir="ltr"

          >

            ${footerInfo.phone}

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ✉

          </span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? footerInfo.labels.emailAr

                : footerInfo.labels.emailEn

            }:



          </span>



          <a

            href="mailto:${footerInfo.email}"

            class="erp-footer-link"

          >

            ${footerInfo.email}

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ◎

          </span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? footerInfo.labels.websiteAr

                : footerInfo.labels.websiteEn

            }:



          </span>



          <a

            href="https://${footerInfo.website}"

            class="erp-footer-link"

            target="_blank"

            rel="noopener"

          >

            ${footerInfo.website}

          </a>



        </div>



      </div>



    `;



  }





  /* =========================================================

     17. EVENTS

  ========================================================= */



  let lastToggleTime = 0;





  content.addEventListener(



    "click",



    event => {





      const infoButton =

        event.target.closest(

          "[data-info-item]"

        );





      if (infoButton) {



        event.preventDefault();

        event.stopPropagation();





        const itemName =

          infoButton.dataset.infoItem;



        const data =

          itemDescriptions[itemName];





        if (data) {



          showInfoModal({



            ...data,



            labelAr:

              translate(itemName),



            labelEn:

              itemName



          });



        }





        return;



      }





      const routeButton =

        event.target.closest(

          "[data-route-name]"

        );





      if (routeButton) {



        event.preventDefault();

        event.stopPropagation();





        openRoute(

          routeButton.dataset.routeName

        );





        return;



      }





      const cardButton =

        event.target.closest(

          "[data-card-toggle]"

        );





      if (!cardButton)

        return;





      const now =

        Date.now();





      if (

        now - lastToggleTime <

        400

      )

        return;





      lastToggleTime =

        now;





      const selectedCard =

        cardButton.closest(

          "[data-erp-card]"

        );





      if (!selectedCard)

        return;





      const shouldOpen =

        !selectedCard.classList.contains(

          "is-open"

        );





      content

        .querySelectorAll(

          "[data-erp-card]"

        )

        .forEach(card => {



          if (card !== selectedCard) {



            card.classList.remove(

              "is-open"

            );



          }



        });





      selectedCard.classList.toggle(

        "is-open",

        shouldOpen

      );



    }



  );





  /* =========================================================

     18. INIT

  ========================================================= */



  try {

    renderSupportCycle();

  } catch (e) {

    console.error("Support Cycle Error:", e);

  }



  try {

    renderStats();

  } catch (e) {

    console.error("Support Stats Error:", e);

  }



  try {

    renderQuickActions();

  } catch (e) {

    console.error("Support Quick Actions Error:", e);

  }



  try {

    renderSections();

  } catch (e) {

    console.error("Support Sections Error:", e);

  }



  try {

    renderFooter();

  } catch (e) {

    console.error("Support Footer Error:", e);

  }



})();

style:
/* =========================================================

   MUBTKIR ERP — BUYING WORKSPACE

   Unified Professional Brand Theme

   لوحة تحكم قسم المشتريات

========================================================= */





/* =========================================================

   1. ROOT + BRAND COLORS

   ألوان الهوية الرسمية

========================================================= */



.erp-dashboard-wrapper {



  --brand-primary: #3867AE;

  --brand-secondary: #0F84B5;

  --brand-accent: #0BA1B8;

  --brand-purple: #644DA6;



  --brand-text: #243B63;

  --brand-muted: #66758A;



  --brand-border: rgba(56, 103, 174, 0.22);

  --brand-border-strong: rgba(56, 103, 174, 0.38);



  --brand-soft: rgba(56, 103, 174, 0.07);

  --brand-soft-secondary: rgba(15, 132, 181, 0.07);

  --brand-soft-accent: rgba(11, 161, 184, 0.07);

  --brand-soft-purple: rgba(100, 77, 166, 0.07);



  position: relative;

  isolation: isolate;



  width: 100%;



  padding: 14px 16px 36px;



  overflow: visible;



  color: var(--brand-text);

}





/* =========================================================

   2. FONT

========================================================= */



.erp-dashboard-wrapper,

.erp-dashboard-wrapper * {



  box-sizing: border-box;



  font-family:

    "Tajawal",

    "Inter",

    Arial,

    sans-serif !important;

}





/* =========================================================

   3. RTL

========================================================= */



.erp-dashboard-wrapper.erp-dashboard-rtl {



  direction: rtl;

  text-align: right;

}





/* =========================================================

   BACKGROUND

   صورة واحدة في الخلفية بدون تكرار

========================================================= */



.erp-dashboard-bg {

    position: absolute !important;



    top: 50px;

    left: 50%;



    /* حجم الصورة */

    width: 78%;

    max-width: 1200px;



    height: auto;



    transform: translateX(-50%);



    /* الشفافية */

    opacity: 0.03;



    object-fit: contain;



    pointer-events: none;

    user-select: none;



    z-index: 0;

}





/* الحاوية الرئيسية */

.erp-dashboard-wrapper {

    position: relative !important;

    isolation: isolate;

}





/* المحتوى فوق الخلفية */

.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

    position: relative !important;

    z-index: 2;

}



/* =========================================================

   المحتوى فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



    position: relative;



    z-index: 2;

}

/* =========================================================

   إبقاء جميع عناصر الداشبورد فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

    position: relative;

    z-index: 2;

}



/* =========================================================

   5. CONTENT LAYER

   جميع المحتويات تظهر فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



  position: relative;



  z-index: 2;

}





.erp-dashboard-content,

.erp-module-section,

.erp-dashboard-grid {



  background: transparent !important;

}





/* =========================================================

   6. SECTION TITLE

========================================================= */



.erp-section-title {



  position: relative;



  display: flex;

  align-items: center;



  min-height: 36px;



  margin: 0 0 16px;



  padding: 0 0 10px;



  border-bottom:

    1px solid var(--brand-border);



  color:

    var(--brand-text) !important;



  font-size: 18px;

  font-weight: 700;



  line-height: 1.4;

}





.erp-section-title::after {



  content: "";



  position: absolute;



  bottom: -1px;



  width: 52px;

  height: 2px;



  border-radius: 20px;



  background: var(--brand-primary);

}





.erp-dashboard-rtl

.erp-section-title::after {



  right: 0;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-section-title::after {



  left: 0;

}





/* =========================================================

   7. PURCHASE CYCLE SECTION

========================================================= */



.erp-purchase-cycle-section {



  margin: 18px 0 24px;

}





.erp-cycle-container {



  position: relative;



  padding: 18px 18px 20px;



  border:

    1px solid var(--brand-border);



  border-radius: 16px;



  /*

     شبه معتم حتى يبقى الـ Pattern ظاهراً بخفة

  */



  background:

    rgba(255, 255, 255, 0.94);



  box-shadow:

    0 5px 18px rgba(36, 59, 99, 0.06);

}





.erp-cycle-title {



  margin-bottom: 20px;

}





/* =========================================================

   SALES / PURCHASE CYCLE GRID

   توزيع البطاقات على كامل عرض الصفحة

========================================================= */



.erp-cycle-grid {

  display: grid;



  grid-template-columns:

    repeat(5, minmax(0, 1fr));



  gap: 18px;



  width: 100%;



  align-items: stretch;

}





.erp-cycle-item {

  position: relative;



  display: flex;



  width: 100%;



  min-width: 0;

}





/* البطاقة تتمدد حسب عرض العمود */

.erp-cycle-card {

  width: 100%;



  min-width: 0;



  min-height: 180px;

}



/* =========================================================

   9. PURCHASE CYCLE CARD

========================================================= */



.erp-cycle-card {



  --cycle-color:

    var(--brand-primary);



  --cycle-soft:

    var(--brand-soft);



  position: relative;



  display: flex;



  flex-direction: column;



  align-items: center;

  justify-content: flex-start;



  width: 100%;



  min-width: 0;

  min-height: 180px;



  padding: 17px 11px 15px;



  overflow: hidden;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  outline: none;



  background:

    rgba(255, 255, 255, 0.96);



  color:

    var(--brand-text) !important;



  font-family: inherit;



  text-align: center;



  cursor: pointer;



  transition:

    transform 0.20s ease,

    border-color 0.20s ease,

    box-shadow 0.20s ease;

}





.erp-cycle-card::before {



  content: "";



  position: absolute;



  inset: 0;



  border-radius: inherit;



  background:

    var(--cycle-soft);



  opacity: 0.42;



  pointer-events: none;

}





.erp-cycle-card::after {



  content: "";



  position: absolute;



  right: 0;

  bottom: 0;



  width: 0;

  height: 3px;



  background:

    var(--cycle-color);



  transition:

    width 0.25s ease;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-cycle-card::after {



  right: auto;

  left: 0;

}





.erp-cycle-card > * {



  position: relative;



  z-index: 2;

}





@media (hover: hover) {



  .erp-cycle-card:hover {



    transform:

      translateY(-4px);



    border-color:

      var(--cycle-color);



    box-shadow:

      0 12px 28px rgba(36, 59, 99, 0.12);

  }





  .erp-cycle-card:hover::after {



    width: 100%;

  }

}





/* =========================================================

   10. CYCLE NUMBER

========================================================= */



.erp-cycle-number {



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 42px;

  height: 42px;



  flex: 0 0 42px;



  margin-bottom: 14px;



  border-radius: 50%;



  background:

    var(--cycle-color);



  color:

    #ffffff !important;



  font-size: 18px;

  font-weight: 800;



  line-height: 1;



  box-shadow:

    0 5px 14px rgba(36, 59, 99, 0.12);

}





/* =========================================================

   11. CYCLE TITLE

========================================================= */



.erp-cycle-card-title {



  display: block;



  width: 100%;



  margin-bottom: 7px;



  color:

    var(--brand-text) !important;



  font-size: 13.5px;

  font-weight: 800;



  line-height: 1.45;

}





/* =========================================================

   12. CYCLE DESCRIPTION

========================================================= */



.erp-cycle-description {



  display: block;



  width: 100%;



  color:

    var(--brand-muted) !important;



  font-size: 10.5px;

  font-weight: 500;



  line-height: 1.65;

}





/* =========================================================

   13. CYCLE BRAND COLORS

========================================================= */



.erp-cycle-card.cycle-tone-1 {



  --cycle-color:

    var(--brand-primary);



  --cycle-soft:

    var(--brand-soft);

}





.erp-cycle-card.cycle-tone-2 {



  --cycle-color:

    var(--brand-secondary);



  --cycle-soft:

    var(--brand-soft-secondary);

}





.erp-cycle-card.cycle-tone-3 {



  --cycle-color:

    var(--brand-accent);



  --cycle-soft:

    var(--brand-soft-accent);

}





.erp-cycle-card.cycle-tone-4 {



  --cycle-color:

    var(--brand-purple);



  --cycle-soft:

    var(--brand-soft-purple);

}





/* =========================================================

   14. CYCLE ARROW

========================================================= */



.erp-cycle-arrow {



  position: absolute;



  top: 50%;



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 20px;

  height: 20px;



