}











/* =========================================================

   29. CARD ICON

========================================================= */



.erp-icon {



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 34px;

  height: 34px;



  flex:

    0 0 34px;



  border-radius:

    9px;



  background:

    var(--erp-soft);



  font-size:

    17px;

}





/* =========================================================

   30. CARD TITLE

========================================================= */



.erp-card-title,

.erp-card .erp-card-title {



  flex: 1;



  min-width: 0;



  color:

    var(--brand-text) !important;



  font-size:

    16px;



  font-weight:

    800;



  line-height:

    1.5;

}





/* =========================================================

   31. CARD CHEVRON

========================================================= */



.erp-card-chevron {



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 28px;

  height: 28px;



