.erp-footer-link:hover {



  color:

    var(--brand-secondary) !important;



  text-decoration:

    underline;

}





.erp-footer-sep {



  color:

    var(--brand-border-strong) !important;



  font-size:

    20px;



  font-weight:

    300;



  line-height:

    1;

