/* =========================================================

   40. MODAL BOX

========================================================= */



.erp-modal-box {



  position: relative;



  width: 100%;



  max-width: 480px;

  max-height: 85vh;



  padding:

    28px 24px;



  overflow-y: auto;



  border:

    1px solid var(--brand-border);



  border-radius:

    16px;



  background:

    #ffffff !important;



  box-shadow:

    0 24px 64px rgba(12, 27, 54, 0.28) !important;



  opacity: 0;



  transform:

    translateY(24px)

