                  >



                    <span class="erp-cycle-number">

                      ${card.step}

                    </span>



                    <span class="erp-cycle-card-title">

                      ${escapeHtml(title)}

                    </span>



                    <span class="erp-cycle-description">

                      ${escapeHtml(description)}

                    </span>



                  </button>



                  ${arrow}



                </div>

              `;



            }

          ).join("")}



        </div>



      </section>

    `;





    zatcaCycle.addEventListener(

      "click",

      event => {



        const element =

          event.target.closest(

            "[data-cycle-index]"

          );



        if (!element)

          return;





        const card =

          zatcaCycleCards[

            Number(element.dataset.cycleIndex)

          ];



        if (!card)

          return;





        if (card.action === "new") {



          frappe.new_doc(

            card.doctype

          );



          return;

        }





        if (card.action === "form") {



          frappe.set_route(

            "Form",

            card.doctype

          );



          return;

        }





        if (card.action === "list") {



          frappe.set_route(

            "List",

            card.doctype

          );

        }



      }

    );



  }





  /* ══════════════════════════════════════════

     ١٠. إنشاء بطاقات الإحصائيات

  ══════════════════════════════════════════ */



  function renderStats() {



    if (!statsSection)

      return;





    statsSection.innerHTML = `



      <div class="erp-stats-grid">



        ${statsCards.map((card) => {



          const label =

            isArabic

              ? card.labelAr

              : card.labelEn;



          return `



            <div

              class="erp-stat-card"

              style="--stat-color:${card.color}"

            >



              <div class="erp-stat-icon">

                ${card.icon}

              </div>



              <div class="erp-stat-info">



                <span

                  class="erp-stat-value"

                  data-stat-id="${card.id}"

                >

                  ...

                </span>



                <span class="erp-stat-label">

                  ${escapeHtml(label)}

                </span>



              </div>



            </div>

          `;



        }).join("")}



      </div>

    `;





    if (window.frappe) {



      statsCards.forEach(card => {



        card.fetch().then(value => {



          const el =

            statsSection.querySelector(

              `[data-stat-id="${card.id}"]`

            );



          if (!el)

            return;



          el.textContent =

            formatNumber(value);



        });



      });



    }



  }





  /* ══════════════════════════════════════════

     ١١. مربع التفاصيل

  ══════════════════════════════════════════ */



  function showInfoModal(data) {



    const title =

      isArabic

        ? data.labelAr

        : data.labelEn;



    const summary =

      isArabic

        ? data.summaryAr

        : data.summaryEn;





    const overlay =

      document.createElement("div");



    overlay.className =

      "erp-modal-overlay";



    overlay.setAttribute(

      "dir",

      isArabic ? "rtl" : "ltr"

    );





    overlay.innerHTML = `



      <div class="erp-modal-box">



        <button

          type="button"

          class="erp-modal-close"

          data-modal-close

        >

          ✕

        </button>



        <div class="erp-modal-header">



          <span class="erp-modal-icon">

            ${data.icon}

          </span>



          <h3 class="erp-modal-title">

            ${escapeHtml(title)}

          </h3>



        </div>



        <p class="erp-modal-summary">

          ${escapeHtml(summary)}

        </p>



      </div>

    `;





    root.appendChild(overlay);



    requestAnimationFrame(() =>

      overlay.classList.add("is-visible")

    );





    function closeModal() {



      overlay.classList.remove(

        "is-visible"

      );



      overlay.addEventListener(

        "transitionend",

        () => overlay.remove(),

        { once: true }

      );



    }





    overlay

      .querySelector("[data-modal-close]")

      .addEventListener(

        "click",

        closeModal

      );





    overlay.addEventListener(

      "click",

      e => {



        if (e.target === overlay)

          closeModal();



      }

    );



  }





  /* ══════════════════════════════════════════

     ١٢. إنشاء البطاقات

  ══════════════════════════════════════════ */



  function renderSections() {



    content.innerHTML =

      sections.map(

        (section, sectionIndex) => {



          const sectionName =

            section[0];



          const sectionCards =

            section[1];





          const cardsHtml =

            sectionCards.map(

              (card, cardIndex) => {



                const cardName =

                  card[0];



                const icon =

                  card[1];



                const items =

                  card[2];





                const linksHtml =

                  items.map(

                    itemName => {



                      const desc =

                        itemDescriptions[itemName];



                      const detailsLabel =

                        isArabic

                          ? "تفاصيل"

                          : "Details";





                      const infoBtn =

                        desc

                          ? `

                            <button

                              type="button"

                              class="erp-info-link"

                              data-info-item="${escapeHtml(itemName)}"

                            >

                              ${detailsLabel}

                            </button>

                          `

                          : "";





                      return `



                        <div class="erp-link-row">



                          <button

                            type="button"

                            class="erp-link"

                            data-route-name="${escapeHtml(itemName)}"

                          >



                            <span class="erp-link-text">

                              ${escapeHtml(translate(itemName))}

                            </span>



                            <span class="erp-link-arrow">

                              ${isArabic ? "←" : "→"}

                            </span>



                          </button>



                          ${infoBtn}



                        </div>

                      `;



                    }

                  ).join("");





                return `



                  <article

                    class="

                      erp-card

                      tone-${(sectionIndex + cardIndex) % 5}

                    "

                    data-erp-card

                  >



                    <button

                      type="button"

                      class="erp-card-heading"

                      data-card-toggle

                      aria-expanded="false"

                    >



                      <span class="erp-icon">

                        ${icon}

                      </span>



                      <span class="erp-card-title">

                        ${escapeHtml(translate(cardName))}

                      </span>



                      <span class="erp-card-chevron">

                        ⌄

                      </span>



                    </button>





                    <div class="erp-card-links">

                      ${linksHtml}

                    </div>



                  </article>

                `;



              }

            ).join("");





          return `



            <section class="erp-module-section">



              <h2 class="erp-section-title">

                ${escapeHtml(translate(sectionName))}

              </h2>



              <div class="erp-dashboard-grid">

                ${cardsHtml}

              </div>



            </section>

          `;



        }

      ).join("");



  }





  /* ══════════════════════════════════════════

     ١٣. الفوتر

  ══════════════════════════════════════════ */



  function renderFooter() {



    if (!footerEl)

      return;





    const labels =

      footerInfo.labels;





    const phoneLabel =

      isArabic

        ? labels.phoneAr

        : labels.phoneEn;





    const emailLabel =

      isArabic

        ? labels.emailAr

        : labels.emailEn;





    const websiteLabel =

      isArabic

        ? labels.websiteAr

        : labels.websiteEn;





    footerEl.innerHTML = `



      <div class="erp-footer-inner">



        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            📞

          </span>



          <span class="erp-footer-label">

            ${escapeHtml(phoneLabel)}:

          </span>



          <a

            href="tel:${footerInfo.phone}"

            class="erp-footer-link"

            dir="ltr"

          >

            ${escapeHtml(footerInfo.phone)}

          </a>



        </div>



        <span class="erp-footer-sep">

          |

        </span>



        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ✉️

          </span>



          <span class="erp-footer-label">

            ${escapeHtml(emailLabel)}:

          </span>



          <a

            href="mailto:${footerInfo.email}"

            class="erp-footer-link"

          >

            ${escapeHtml(footerInfo.email)}

          </a>



        </div>



        <span class="erp-footer-sep">

          |

        </span>



        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            🌐

          </span>



          <span class="erp-footer-label">

            ${escapeHtml(websiteLabel)}:

          </span>



          <a

            href="https://${footerInfo.website}"

            class="erp-footer-link"

            target="_blank"

            rel="noopener"

          >

            ${escapeHtml(footerInfo.website)}

          </a>



        </div>



      </div>

    `;



  }





  /* ══════════════════════════════════════════

     ١٤. فتح الخيارات

  ══════════════════════════════════════════ */



  function openRoute(name) {



    if (

      !window.frappe ||

      typeof frappe.set_route !== "function"

    )

      return;





    if (reportNames.has(name)) {



      frappe.set_route(

        "query-report",

        name

      );



      return;

    }





    if (singleDocs.has(name)) {



      frappe.set_route(

        "Form",

        name

      );



      return;

    }





    frappe.set_route(

      "List",

      name

    );



  }





  /* ══════════════════════════════════════════

     ١٥. أحداث الضغط

  ══════════════════════════════════════════ */



  let lastToggleTime = 0;





  content.addEventListener(

    "click",

    event => {





      const infoBtn =

        event.target.closest(

          "[data-info-item]"

        );





      if (infoBtn) {



        event.preventDefault();

        event.stopPropagation();





        const itemName =

          infoBtn.dataset.infoItem;





        const desc =

          itemDescriptions[itemName];





        if (desc) {



          showInfoModal({



            icon:

              desc.icon || "📄",



            labelAr:

              translate(itemName),



            labelEn:

              itemName,



            summaryAr:

              desc.summaryAr,



            summaryEn:

              desc.summaryEn



          });



        }



        return;

      }





      const routeButton =

        event.target.closest(

          "[data-route-name]"

        );





      if (routeButton) {



        event.preventDefault();

        event.stopPropagation();





        openRoute(

          routeButton.dataset.routeName

        );



        return;

      }





      const cardButton =

        event.target.closest(

          "[data-card-toggle]"

        );





      if (!cardButton)

        return;





      const now =

        Date.now();





      if (

        now - lastToggleTime <

        400

      )

        return;





      lastToggleTime =

        now;





      const selectedCard =

        cardButton.closest(

          "[data-erp-card]"

        );





      if (!selectedCard)

        return;





      const shouldOpen =

        !selectedCard.classList.contains(

          "is-open"

        );





      content

        .querySelectorAll(

          "[data-erp-card]"

        )

        .forEach(card => {



          if (card !== selectedCard) {



            card.classList.remove(

              "is-open"

            );



            card

              .querySelector(

                "[data-card-toggle]"

              )

              ?.setAttribute(

                "aria-expanded",

                "false"

              );



          }



        });





      if (shouldOpen) {



        selectedCard.classList.add(

          "is-open"

        );



        cardButton.setAttribute(

          "aria-expanded",

          "true"

        );



      } else {



        selectedCard.classList.remove(

          "is-open"

        );



        cardButton.setAttribute(

          "aria-expanded",

          "false"

        );



      }



    }

  );





  /* ══════════════════════════════════════════

     ١٦. تشغيل

  ══════════════════════════════════════════ */



  renderZatcaCycle();

  renderStats();

  renderSections();

  renderFooter();



})();

style:
/* =========================================================

   MUBTKIR ERP — BUYING WORKSPACE

   Unified Professional Brand Theme

   لوحة تحكم قسم المشتريات

========================================================= */





/* =========================================================

   1. ROOT + BRAND COLORS

   ألوان الهوية الرسمية

========================================================= */



.erp-dashboard-wrapper {



  --brand-primary: #3867AE;

  --brand-secondary: #0F84B5;

  --brand-accent: #0BA1B8;

  --brand-purple: #644DA6;



  --brand-text: #243B63;

  --brand-muted: #66758A;



  --brand-border: rgba(56, 103, 174, 0.22);

  --brand-border-strong: rgba(56, 103, 174, 0.38);



  --brand-soft: rgba(56, 103, 174, 0.07);

  --brand-soft-secondary: rgba(15, 132, 181, 0.07);

  --brand-soft-accent: rgba(11, 161, 184, 0.07);

  --brand-soft-purple: rgba(100, 77, 166, 0.07);



  position: relative;

  isolation: isolate;



  width: 100%;



  padding: 14px 16px 36px;



  overflow: visible;



  color: var(--brand-text);

}





/* =========================================================

   2. FONT

========================================================= */



.erp-dashboard-wrapper,

.erp-dashboard-wrapper * {



  box-sizing: border-box;



  font-family:

    "Tajawal",

    "Inter",

    Arial,

    sans-serif !important;

}





/* =========================================================

   3. RTL

========================================================= */



.erp-dashboard-wrapper.erp-dashboard-rtl {



  direction: rtl;

  text-align: right;

}





/* =========================================================

   BACKGROUND

   صورة واحدة في الخلفية بدون تكرار

========================================================= */



.erp-dashboard-bg {

    position: absolute !important;



    top: 50px;

    left: 50%;



    /* حجم الصورة */

    width: 78%;

    max-width: 1200px;



    height: auto;



    transform: translateX(-50%);



    /* الشفافية */

    opacity: 0.03;



    object-fit: contain;



    pointer-events: none;

    user-select: none;



    z-index: 0;

}





/* الحاوية الرئيسية */

.erp-dashboard-wrapper {

    position: relative !important;

    isolation: isolate;

}





/* المحتوى فوق الخلفية */

.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

    position: relative !important;

    z-index: 2;

}



/* =========================================================

   المحتوى فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



    position: relative;



    z-index: 2;

}

/* =========================================================

   إبقاء جميع عناصر الداشبورد فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

    position: relative;

    z-index: 2;

}



/* =========================================================

   5. CONTENT LAYER

   جميع المحتويات تظهر فوق الخلفية

========================================================= */



.erp-purchase-cycle-section,

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {



  position: relative;



  z-index: 2;

}





.erp-dashboard-content,

.erp-module-section,

.erp-dashboard-grid {



  background: transparent !important;

}





/* =========================================================

   6. SECTION TITLE

========================================================= */



.erp-section-title {



  position: relative;



  display: flex;

  align-items: center;



  min-height: 36px;



  margin: 0 0 16px;



  padding: 0 0 10px;



  border-bottom:

    1px solid var(--brand-border);



  color:

    var(--brand-text) !important;



  font-size: 18px;

  font-weight: 700;



  line-height: 1.4;

}





.erp-section-title::after {



  content: "";



  position: absolute;



  bottom: -1px;



  width: 52px;

  height: 2px;



  border-radius: 20px;



  background: var(--brand-primary);

}





.erp-dashboard-rtl

.erp-section-title::after {



  right: 0;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-section-title::after {



  left: 0;

}





/* =========================================================

   7. PURCHASE CYCLE SECTION

========================================================= */



.erp-purchase-cycle-section {



  margin: 18px 0 24px;

}





.erp-cycle-container {



  position: relative;



  padding: 18px 18px 20px;



  border:

    1px solid var(--brand-border);



  border-radius: 16px;



  /*

     شبه معتم حتى يبقى الـ Pattern ظاهراً بخفة

  */



  background:

    rgba(255, 255, 255, 0.94);



  box-shadow:

    0 5px 18px rgba(36, 59, 99, 0.06);

}





.erp-cycle-title {



  margin-bottom: 20px;

}





/* =========================================================

   SALES / PURCHASE CYCLE GRID

   توزيع البطاقات على كامل عرض الصفحة

========================================================= */



.erp-cycle-grid {

  display: grid;



  grid-template-columns:

    repeat(5, minmax(0, 1fr));



  gap: 18px;



  width: 100%;



  align-items: stretch;

}





.erp-cycle-item {

  position: relative;



  display: flex;



  width: 100%;



  min-width: 0;

}





/* البطاقة تتمدد حسب عرض العمود */

.erp-cycle-card {

  width: 100%;



  min-width: 0;



  min-height: 180px;

}



/* =========================================================

   9. PURCHASE CYCLE CARD

========================================================= */



.erp-cycle-card {



  --cycle-color:

    var(--brand-primary);



  --cycle-soft:

    var(--brand-soft);



  position: relative;



  display: flex;



  flex-direction: column;



  align-items: center;

  justify-content: flex-start;



  width: 100%;



  min-width: 0;

  min-height: 180px;



  padding: 17px 11px 15px;



  overflow: hidden;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  outline: none;



  background:

    rgba(255, 255, 255, 0.96);



  color:

    var(--brand-text) !important;



  font-family: inherit;



  text-align: center;



  cursor: pointer;



  transition:

    transform 0.20s ease,

    border-color 0.20s ease,

    box-shadow 0.20s ease;

}





.erp-cycle-card::before {



  content: "";



  position: absolute;



  inset: 0;



  border-radius: inherit;



  background:

    var(--cycle-soft);



  opacity: 0.42;



  pointer-events: none;

}





.erp-cycle-card::after {



  content: "";



  position: absolute;



  right: 0;

  bottom: 0;



  width: 0;

  height: 3px;



  background:

    var(--cycle-color);



  transition:

    width 0.25s ease;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-cycle-card::after {



  right: auto;

  left: 0;

}





.erp-cycle-card > * {



  position: relative;



  z-index: 2;

}





@media (hover: hover) {



  .erp-cycle-card:hover {



    transform:

      translateY(-4px);



    border-color:

      var(--cycle-color);



    box-shadow:

      0 12px 28px rgba(36, 59, 99, 0.12);

  }





  .erp-cycle-card:hover::after {



    width: 100%;

  }

}





/* =========================================================

   10. CYCLE NUMBER

========================================================= */



.erp-cycle-number {



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 42px;

  height: 42px;



  flex: 0 0 42px;



  margin-bottom: 14px;



  border-radius: 50%;



  background:

    var(--cycle-color);



  color:

    #ffffff !important;



  font-size: 18px;

  font-weight: 800;



  line-height: 1;



  box-shadow:

    0 5px 14px rgba(36, 59, 99, 0.12);

}





/* =========================================================

   11. CYCLE TITLE

========================================================= */



.erp-cycle-card-title {



  display: block;



  width: 100%;



  margin-bottom: 7px;



  color:

    var(--brand-text) !important;



  font-size: 13.5px;

  font-weight: 800;



  line-height: 1.45;

}





/* =========================================================

   12. CYCLE DESCRIPTION

========================================================= */



.erp-cycle-description {



  display: block;



  width: 100%;



  color:

    var(--brand-muted) !important;



  font-size: 10.5px;

  font-weight: 500;



  line-height: 1.65;

}





/* =========================================================

   13. CYCLE BRAND COLORS

========================================================= */



.erp-cycle-card.cycle-tone-1 {



  --cycle-color:

    var(--brand-primary);



  --cycle-soft:

    var(--brand-soft);

}





.erp-cycle-card.cycle-tone-2 {



  --cycle-color:

    var(--brand-secondary);



  --cycle-soft:

    var(--brand-soft-secondary);

}





.erp-cycle-card.cycle-tone-3 {



  --cycle-color:

    var(--brand-accent);



  --cycle-soft:

    var(--brand-soft-accent);

}





.erp-cycle-card.cycle-tone-4 {



  --cycle-color:

    var(--brand-purple);



  --cycle-soft:

    var(--brand-soft-purple);

}





/* =========================================================

   14. CYCLE ARROW

========================================================= */



.erp-cycle-arrow {



  position: absolute;



  top: 50%;



  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 20px;

  height: 20px;



  color:

    var(--brand-primary) !important;



  font-size: 20px;

  font-weight: 800;



  line-height: 1;



  opacity: 0.55;



  transform:

    translateY(-50%);



  pointer-events: none;



  z-index: 10;

}





.erp-dashboard-rtl

.erp-cycle-arrow {



  left: -17px;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-cycle-arrow {



  right: -17px;

}





/* =========================================================

   15. OVERVIEW SECTION

========================================================= */



.erp-stats-section {



  margin: 0 0 24px;

}





.erp-overview-container {



  padding: 18px;



  border:

    1px solid var(--brand-border);



  border-radius: 16px;



  background:

    rgba(255, 255, 255, 0.94);



  box-shadow:

    0 5px 18px rgba(36, 59, 99, 0.06);

}





/* =========================================================

   16. STATS GRID

========================================================= */



.erp-stats-grid {



  display: grid !important;



  grid-template-columns:

    repeat(4, minmax(0, 1fr)) !important;



  gap: 14px;



  margin: 0;

}





/* =========================================================

   17. STAT CARD

========================================================= */



.erp-stat-card {



  display: flex;



  align-items: center;



  gap: 13px;



  min-width: 0;



  min-height: 88px;



  padding: 16px 18px;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  background:

    rgba(255, 255, 255, 0.96);



  box-shadow:

    0 4px 14px rgba(36, 59, 99, 0.05);



  transition:

    transform 0.22s ease,

    border-color 0.22s ease,

    box-shadow 0.22s ease;

