/* =========================================================

   MUBTKIR ERP — SALES WORKSPACE

   Unified Professional Brand Theme

========================================================= */





/* =========================================================

   1. ROOT + BRAND COLORS

========================================================= */



.erp-dashboard-wrapper {

  --brand-primary: #3867AE;

  --brand-secondary: #0F84B5;

  --brand-accent: #0BA1B8;

  --brand-purple: #644DA6;



  --brand-text: #243B63;

  --brand-muted: #66758A;



  --brand-border: rgba(56, 103, 174, 0.22);

  --brand-border-strong: rgba(56, 103, 174, 0.38);



  --brand-soft: rgba(56, 103, 174, 0.07);

  --brand-soft-secondary: rgba(15, 132, 181, 0.07);

  --brand-soft-accent: rgba(11, 161, 184, 0.07);

  --brand-soft-purple: rgba(100, 77, 166, 0.07);



  position: relative;

  width: 100%;

  padding: 14px 16px 36px;

  overflow: visible;



  color: var(--brand-text);

}



.erp-dashboard-wrapper,

.erp-dashboard-wrapper * {

  box-sizing: border-box;



  font-family:

    "Tajawal",

    "Inter",

    Arial,

    sans-serif !important;

}





/* RTL */



.erp-dashboard-wrapper.erp-dashboard-rtl {

  direction: rtl;

  text-align: right;

}





/* =========================================================

   2. BACKGROUND LOGO

   الشعار المائي في خلفية لوحة التحكم

========================================================= */



.erp-dashboard-wrapper {

  position: relative;

  isolation: isolate;

}





/* الشعار المائي */

.erp-dashboard-bg {

  position: absolute;



  /* يبدأ أسفل بطاقات الإحصائيات تقريباً */

  top: 60px;

  left: 50%;



  width: 58%;

  max-width: 720px;

  height: auto;



  object-fit: contain;



  transform: translateX(-50%);



  /* قوة ظهور الشعار */

  opacity: 0.055;



  pointer-events: none;

  user-select: none;



  z-index: 0;

}





/* جميع محتويات الصفحة فوق الشعار */

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

  position: relative;

  z-index: 2;

}





/* ضمان شفافية منطقة المحتوى */

.erp-dashboard-content,

.erp-module-section,

.erp-dashboard-grid {

  background: transparent !important;

}





/* =========================================================

   3. CONTENT LAYER

========================================================= */



.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

  position: relative;

  z-index: 2;

}





/* =========================================================

   4. STATISTICS GRID

========================================================= */



.erp-stats-grid {

  display: grid !important;



  grid-template-columns:

    repeat(4, minmax(0, 1fr)) !important;



  gap: 14px;



  margin: 18px 0 24px;

}





/* =========================================================

   5. STAT CARD

========================================================= */



.erp-stat-card {

  display: flex;



  align-items: center;



  gap: 12px;



  min-width: 0;



  padding: 16px 18px;



  border: 1px solid var(--brand-border);

  border-radius: 14px;



  background: var(--fg-color, #ffffff);



  box-shadow:

    0 4px 14px rgba(36, 59, 99, 0.06);



  transition:

    transform 0.22s ease,

    border-color 0.22s ease,

    box-shadow 0.22s ease;

}





@media (hover: hover) {



  .erp-stat-card:hover {

    transform: translateY(-3px);



    border-color: var(--brand-border-strong);



    box-shadow:

      0 10px 26px rgba(36, 59, 99, 0.11);

  }



}





/* =========================================================

   6. STAT ICON

========================================================= */



.erp-stat-icon {

  display: flex;



  align-items: center;

  justify-content: center;



  width: 44px;

  height: 44px;



  flex: 0 0 44px;



  border-radius: 12px;



  background: var(--brand-soft);



  font-size: 21px;

}





/* =========================================================

   7. STAT INFO

   لون النص موحد لجميع بطاقات الإحصائيات

========================================================= */



.erp-stat-info {

  display: flex;



  flex-direction: column;



  gap: 3px;



  min-width: 0;



  color: var(--brand-text) !important;

}





/* الرقم / القيمة */



.erp-stat-value,

.erp-stat-card .erp-stat-value {

  color: var(--brand-text) !important;



  font-size: 18px !important;

  font-weight: 800 !important;



  line-height: 1.3;



  direction: ltr;

}





/* اسم الإحصائية */



.erp-stat-label,

.erp-stat-card .erp-stat-label {

  color: var(--brand-text) !important;



  font-size: 11.5px !important;

  font-weight: 600 !important;



  line-height: 1.45;

}





/* فرض اللون على أي عناصر داخل بطاقة الإحصائية */



.erp-stat-card .erp-stat-info,

.erp-stat-card .erp-stat-info span {

  color: var(--brand-text) !important;

}





/* =========================================================

   8. STAT CARD SOFT COLORS

   اللون يطبق على خلفية الأيقونة فقط

   وليس على النص

========================================================= */



.erp-stat-card:nth-child(1) .erp-stat-icon {

  background: var(--brand-soft);

}



.erp-stat-card:nth-child(2) .erp-stat-icon {

  background: var(--brand-soft-secondary);

}



.erp-stat-card:nth-child(3) .erp-stat-icon {

  background: var(--brand-soft-accent);

}



.erp-stat-card:nth-child(4) .erp-stat-icon {

  background: var(--brand-soft-purple);

}





/* =========================================================

   9. SECTION

========================================================= */



.erp-quick-actions {

  margin-bottom: 24px;

}



.erp-module-section {

  margin-top: 24px;

}





/* =========================================================

   10. SECTION TITLE

========================================================= */



.erp-section-title {

  position: relative;



  display: flex;



  align-items: center;



  min-height: 36px;



  margin: 0 0 14px;



  padding: 0 0 9px;



  border-bottom:

    1px solid var(--brand-border);



  color: var(--brand-text) !important;



  font-size: 18px;

  font-weight: 600;



  line-height: 1.4;

}





.erp-section-title::after {

  content: "";



  position: absolute;



  bottom: -1px;



  width: 52px;

  height: 2px;



  border-radius: 20px;



  background: var(--brand-primary);

}





.erp-dashboard-rtl

.erp-section-title::after {

  right: 0;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-section-title::after {

  left: 0;

}





/* =========================================================

   11. QUICK ACTIONS GRID

========================================================= */



.erp-quick-grid {

  display: grid !important;



  grid-template-columns:

    repeat(4, minmax(0, 1fr)) !important;



  gap: 12px;

}





/* =========================================================

   12. QUICK BUTTONS

   بدون أيقونات

   لون الخط موحد

========================================================= */



.erp-quick-btn {

  display: flex;



  align-items: center;

  justify-content: center;



  min-height: 48px;



  padding: 11px 14px;



  border:

    1px solid var(--brand-border);



  border-radius: 10px;



  outline: none;



  background: var(--brand-soft);



  color: var(--brand-primary) !important;



  font-family: inherit;



  font-size: 15px;

  font-weight: 700;



  line-height: 1.4;



  text-align: center;



  cursor: pointer;



  transition:

    transform 0.18s ease,

    background-color 0.18s ease,

    border-color 0.18s ease,

    color 0.18s ease,

    box-shadow 0.18s ease;

}





.erp-quick-btn:nth-child(2) {

  background: var(--brand-soft-secondary);

}



.erp-quick-btn:nth-child(3) {

  background: var(--brand-soft-accent);

}



.erp-quick-btn:nth-child(4) {

  background: var(--brand-soft-purple);

}





.erp-quick-btn,

.erp-quick-btn .erp-quick-label {

  color: var(--brand-primary) !important;

}





@media (hover: hover) {



  .erp-quick-btn:hover {

    transform: translateY(-2px);



    color: var(--brand-secondary) !important;



    border-color: var(--brand-secondary);



    background:

      rgba(15, 132, 181, 0.10);



    box-shadow:

      0 6px 16px rgba(56, 103, 174, 0.12);

  }



}





.erp-quick-btn:active {

  transform: scale(0.98);

}





.erp-quick-label {

  width: 100%;



  white-space: normal;



  text-align: center;

}





/* =========================================================

   13. REPORT CARDS GRID

========================================================= */



.erp-dashboard-grid {

  display: grid !important;



  grid-template-columns:

    repeat(3, minmax(0, 1fr)) !important;



  align-items: start;



  gap: 16px;



  width: 100%;



  overflow: visible;

}





/* =========================================================

   14. REPORT CARD CLOSED

========================================================= */



.erp-card {

  --erp-accent: var(--brand-primary);

  --erp-soft: var(--brand-soft);



  position: relative;



  z-index: 1;



  min-width: 0;



  min-height: 74px;

  max-height: 74px;



  padding: 0 16px;



  overflow: hidden;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  background: var(--fg-color, #ffffff);



  color: var(--brand-text) !important;



  box-shadow:

    0 5px 16px rgba(36, 59, 99, 0.06);



  transition:

    max-height 0.4s ease,

    transform 0.28s ease,

    box-shadow 0.28s ease,

    border-color 0.28s ease,

    padding-bottom 0.28s ease;

}





/* soft background */



.erp-card::before {

  content: "";



  position: absolute;



  inset: 0;



  z-index: 0;



  background: var(--erp-soft);



  opacity: 0;



  pointer-events: none;



  transition:

    opacity 0.25s ease;

}





/* bottom accent */



.erp-card::after {

  content: "";



  position: absolute;



  right: 0;

  bottom: 0;



  z-index: 4;



  width: 0;

  height: 3px;



  background: var(--erp-accent);



  transition:

    width 0.3s ease;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-card::after {

  right: auto;

  left: 0;

}





/* =========================================================

   15. CARD BRAND TONES

========================================================= */



.erp-card.tone-0 {

  --erp-accent: var(--brand-primary);

  --erp-soft: var(--brand-soft);

}



.erp-card.tone-1 {

  --erp-accent: var(--brand-secondary);

  --erp-soft: var(--brand-soft-secondary);

}



.erp-card.tone-2 {

  --erp-accent: var(--brand-accent);

  --erp-soft: var(--brand-soft-accent);

}



.erp-card.tone-3 {

  --erp-accent: var(--brand-purple);

  --erp-soft: var(--brand-soft-purple);

}



.erp-card.tone-4 {

  --erp-accent: var(--brand-primary);

  --erp-soft: var(--brand-soft);

}





/* =========================================================

   16. CARD OPEN

========================================================= */



.erp-card.is-open {

