  }





  .erp-stat-label,

  .erp-stat-card .erp-stat-label {

    font-size:

      10px !important;

  }





  .erp-quick-grid {

    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;



    gap: 8px;

  }





  .erp-quick-btn {

    min-height: 43px;



    padding:

      9px 7px;



    font-size:

      11.5px;

  }





  .erp-dashboard-grid {

    grid-template-columns:

      1fr !important;



    gap: 11px;

  }





  .erp-card.is-open {

    transform:

      translateY(-2px);

  }





  /* ================================

     FOOTER MOBILE

  ================================ */



  .erp-footer {



    /* حجم خط الفوتر على الجوال */

