    gap: 8px;

  }





  .erp-footer-item {

    justify-content: center;

  }





  .erp-footer-icon {

    font-size:

      15px !important;

  }





  .erp-footer-sep {

    display: none;

  }





  .erp-modal-overlay {

    align-items:

      flex-end;



    padding: 10px;

  }





  .erp-modal-box {

    max-height: 82vh;



    padding:

      22px 17px;



    border-radius:

      16px 16px 0 0;

  }



}

/* =========================================================
   CARDS REMAIN OPEN BY DEFAULT & HOVER-OPEN DISABLED
   إبقاء المربعات مفتوحة بشكل تلقائي وإلغاء الفتح بمرور الماوس
========================================================= */

