  /* ─────────────────────────────────────────
     ٨. دوال مساعدة
  ───────────────────────────────────────── */

  function translate(name) {
    if (!isArabic) return name;
    if (arabicFallback[name]) return arabicFallback[name];
    if (typeof window.__ === "function") return window.__(name);
    return name;
  }

  function escapeHtml(value) {
    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }


  /* ─────────────────────────────────────────
     ٩. مربع التفاصيل (Modal)
     توضيح فقط بدون خطوات.
  ───────────────────────────────────────── */

  function showInfoModal(data) {
    const title = isArabic
      ? data.labelAr
      : data.labelEn;

    const summary = isArabic
      ? data.summaryAr
      : data.summaryEn;

    const steps = isArabic
      ? data.stepsAr
      : data.stepsEn;

    const hasSteps =
      Array.isArray(steps) && steps.length > 0;

    const showStepsText = isArabic
      ? "📖 عرض الخطوات"
      : "📖 Show Steps";

    const hideStepsText = isArabic
      ? "📖 إخفاء الخطوات"
      : "📖 Hide Steps";

    let stepsHtml = "";
    if (hasSteps) {
      stepsHtml = `
        <div class="erp-modal-steps" data-modal-steps>
          <ol class="erp-modal-steps-list">
            ${steps
              .map(
                (step) =>
                  `<li>${escapeHtml(step)}</li>`
              )
              .join("")}
          </ol>
        </div>
      `;
    }

    const overlay = document.createElement("div");
    overlay.className = "erp-modal-overlay";
    overlay.setAttribute(
      "dir",
      isArabic ? "rtl" : "ltr"
    );

    overlay.innerHTML = `
      <div class="erp-modal-box">
        <button
          type="button"
          class="erp-modal-close"
          data-modal-close
          aria-label="Close"
        >✕</button>

        <div class="erp-modal-header">
          <span class="erp-modal-icon">${data.icon}</span>
          <h3 class="erp-modal-title">
            ${escapeHtml(title)}
          </h3>
        </div>

        <p class="erp-modal-summary">
          ${escapeHtml(summary)}
        </p>

        ${
          hasSteps
            ? `<button
                type="button"
                class="erp-modal-toggle-steps"
                data-toggle-steps
              >${showStepsText}</button>`
            : ""
        }

        ${stepsHtml}
      </div>
    `;

    root.appendChild(overlay);

    requestAnimationFrame(() => {
      overlay.classList.add("is-visible");
    });

    function closeModal() {
      overlay.classList.remove("is-visible");
      overlay.addEventListener(
        "transitionend",
        () => overlay.remove(),
        { once: true }
      );
    }

    overlay
      .querySelector("[data-modal-close]")
      .addEventListener("click", closeModal);

    overlay.addEventListener("click", (e) => {
      if (e.target === overlay) closeModal();
    });

    const toggleBtn = overlay.querySelector(
      "[data-toggle-steps]"
    );
    const stepsContainer = overlay.querySelector(
      "[data-modal-steps]"
    );

    if (toggleBtn && stepsContainer) {
      toggleBtn.addEventListener("click", () => {
        const isShowing =
          stepsContainer.classList.contains("is-shown");
        if (isShowing) {
          stepsContainer.classList.remove("is-shown");
          toggleBtn.textContent = showStepsText;
        } else {
          stepsContainer.classList.add("is-shown");
          toggleBtn.textContent = hideStepsText;
        }
      });
    }
  }


  /* ─────────────────────────────────────────
     ١٠. إنشاء بطاقات التكاملات
  ───────────────────────────────────────── */

  function renderSections() {
    root.setAttribute(
      "dir",
      isArabic ? "rtl" : "ltr"
    );

    root.classList.toggle(
      "erp-dashboard-rtl",
      isArabic
    );

    content.innerHTML = sections
      .map((section, sectionIndex) => {
        const sectionName = section[0];
        const sectionCards = section[1];

        const cardsHtml = sectionCards
          .map((card, cardIndex) => {
            const cardName = card[0];
            const icon = card[1];
            const items = card[2];

            const linksHtml = items
              .map((itemName) => {
                const desc =
                  itemDescriptions[itemName];

                const detailsLabel = isArabic
                  ? "تفاصيل"
                  : "Details";

                const infoBtn = desc
                  ? `<button
                      type="button"
                      class="erp-info-link"
                      data-info-item="${escapeHtml(itemName)}"
                    >${detailsLabel}</button>`
                  : "";

                return `
                  <div class="erp-link-row">
                    <button
                      type="button"
                      class="erp-link"
                      data-route-name="${escapeHtml(itemName)}"
                    >
                      <span class="erp-link-text">
                        ${escapeHtml(translate(itemName))}
                      </span>
                      <span
                        class="erp-link-arrow"
                        aria-hidden="true"
                      >${isArabic ? "←" : "→"}</span>
                    </button>
                    ${infoBtn}
                  </div>
                `;
              })
              .join("");

            return `
              <article
                class="erp-card tone-${(sectionIndex + cardIndex) % 5}"
                data-erp-card
              >
                <button
                  type="button"
                  class="erp-card-heading"
                  data-card-toggle
                  aria-expanded="false"
                >
                  <span class="erp-icon" aria-hidden="true">
                    ${icon}
                  </span>
                  <span class="erp-card-title">
                    ${escapeHtml(translate(cardName))}
                  </span>
                  <span class="erp-card-chevron" aria-hidden="true">
                    ⌄
                  </span>
                </button>
                <div class="erp-card-links">
                  ${linksHtml}
                </div>
              </article>
            `;
          })
          .join("");

        return `
          <section class="erp-module-section">
            <h2 class="erp-section-title">
              ${escapeHtml(translate(sectionName))}
            </h2>
            <div class="erp-dashboard-grid">
              ${cardsHtml}
            </div>
          </section>
        `;
      })
      .join("");
  }


  /* ─────────────────────────────────────────
     ١١. إنشاء الفوتر
  ───────────────────────────────────────── */

  function renderFooter() {
    if (!footerEl) return;

    const labels = footerInfo.labels;
    const phoneLabel = isArabic
      ? labels.phoneAr
      : labels.phoneEn;
    const emailLabel = isArabic
      ? labels.emailAr
      : labels.emailEn;
    const websiteLabel = isArabic
      ? labels.websiteAr
      : labels.websiteEn;

    footerEl.innerHTML = `
      <div class="erp-footer-inner">
        <div class="erp-footer-item">
          <span class="erp-footer-icon">📞</span>
          <span class="erp-footer-label">
            ${escapeHtml(phoneLabel)}:
          </span>
          <a href="tel:${footerInfo.phone}"
            class="erp-footer-link" dir="ltr"
          >${escapeHtml(footerInfo.phone)}</a>
        </div>

        <span class="erp-footer-sep">|</span>

        <div class="erp-footer-item">
          <span class="erp-footer-icon">✉️</span>
          <span class="erp-footer-label">
            ${escapeHtml(emailLabel)}:
          </span>
          <a href="mailto:${footerInfo.email}"
            class="erp-footer-link"
          >${escapeHtml(footerInfo.email)}</a>
        </div>

        <span class="erp-footer-sep">|</span>

        <div class="erp-footer-item">
          <span class="erp-footer-icon">🌐</span>
          <span class="erp-footer-label">
            ${escapeHtml(websiteLabel)}:
          </span>
          <a href="https://${footerInfo.website}"
            class="erp-footer-link"
            target="_blank" rel="noopener"
          >${escapeHtml(footerInfo.website)}</a>
        </div>
      </div>
    `;
  }


  /* ─────────────────────────────────────────
     ١٢. فتح الخيار داخل ERPNext
  ───────────────────────────────────────── */

  function openRoute(name) {
    if (
      !window.frappe ||
      typeof frappe.set_route !== "function"
    ) {
      return;
    }

    if (reportNames.has(name)) {
      frappe.set_route("query-report", name);
      return;
    }

    if (singleDocs.has(name)) {
      frappe.set_route("Form", name);
      return;
    }

    frappe.set_route("List", name);
  }


  /* ─────────────────────────────────────────
     ١٣. أحداث الضغط على البطاقات والروابط
  ───────────────────────────────────────── */

  let lastToggleTime = 0;

  content.addEventListener("click", (event) => {
    /* ① الضغط على زر "تفاصيل" */
    const infoBtn = event.target.closest(
      "[data-info-item]"
    );
    if (infoBtn) {
      event.preventDefault();
      event.stopPropagation();
      const itemName = infoBtn.dataset.infoItem;
      const desc = itemDescriptions[itemName];
      if (desc) {
        showInfoModal({
          icon: desc.icon || "📄",
          labelAr: translate(itemName),
          labelEn: itemName,
          summaryAr: desc.summaryAr,
          summaryEn: desc.summaryEn,
          stepsAr: desc.stepsAr,
          stepsEn: desc.stepsEn
        });
      }
      return;
    }

    /* ② الضغط على رابط خيار */
    const routeButton = event.target.closest(
      "[data-route-name]"
    );
    if (routeButton) {
      event.preventDefault();
      event.stopPropagation();
      openRoute(routeButton.dataset.routeName);
      return;
    }

    /* ③ الضغط على عنوان البطاقة */
    const cardButton = event.target.closest(
      "[data-card-toggle]"
    );
    if (!cardButton) return;

    const now = Date.now();
    if (now - lastToggleTime < 400) return;
    lastToggleTime = now;

    const selectedCard = cardButton.closest(
      "[data-erp-card]"
    );
    if (!selectedCard) return;

    const shouldOpen =
      !selectedCard.classList.contains("is-open");

    content
      .querySelectorAll("[data-erp-card]")
      .forEach((card) => {
        if (card !== selectedCard) {
          card.classList.remove("is-open");
          card
            .querySelector("[data-card-toggle]")
            ?.setAttribute("aria-expanded", "false");
        }
      });

    if (shouldOpen) {
      selectedCard.classList.add("is-open");
      cardButton.setAttribute("aria-expanded", "true");
    } else {
      selectedCard.classList.remove("is-open");
      cardButton.setAttribute(
        "aria-expanded",
        "false"
      );
    }
  });


  /* ─────────────────────────────────────────
     ١٤. تشغيل إنشاء الأقسام
     (بدون إحصائيات وبدون أزرار اختصار)
  ───────────────────────────────────────── */

  renderSections();
  renderFooter();
})();

style:
/* =========================================================

   MUBTKIR ERP — SALES WORKSPACE

   Unified Professional Brand Theme

========================================================= */





/* =========================================================

   1. ROOT + BRAND COLORS

========================================================= */



.erp-dashboard-wrapper {

  --brand-primary: #3867AE;

  --brand-secondary: #0F84B5;

  --brand-accent: #0BA1B8;

  --brand-purple: #644DA6;



  --brand-text: #243B63;

  --brand-muted: #66758A;



  --brand-border: rgba(56, 103, 174, 0.22);

  --brand-border-strong: rgba(56, 103, 174, 0.38);



  --brand-soft: rgba(56, 103, 174, 0.07);

  --brand-soft-secondary: rgba(15, 132, 181, 0.07);

  --brand-soft-accent: rgba(11, 161, 184, 0.07);

  --brand-soft-purple: rgba(100, 77, 166, 0.07);



  position: relative;

  width: 100%;

  padding: 14px 16px 36px;

  overflow: visible;



  color: var(--brand-text);

}



.erp-dashboard-wrapper,

.erp-dashboard-wrapper * {

  box-sizing: border-box;



  font-family:

    "Tajawal",

    "Inter",

    Arial,

    sans-serif !important;

}





/* RTL */



.erp-dashboard-wrapper.erp-dashboard-rtl {

  direction: rtl;

  text-align: right;

}





/* =========================================================

   2. BACKGROUND LOGO

   الشعار المائي في خلفية لوحة التحكم

========================================================= */



.erp-dashboard-wrapper {

  position: relative;

  isolation: isolate;

}





/* الشعار المائي */

.erp-dashboard-bg {

  position: absolute;



  /* يبدأ أسفل بطاقات الإحصائيات تقريباً */

  top: 60px;

  left: 50%;



  width: 58%;

  max-width: 720px;

  height: auto;



  object-fit: contain;



  transform: translateX(-50%);



  /* قوة ظهور الشعار */

  opacity: 0.055;



  pointer-events: none;

  user-select: none;



  z-index: 0;

}





/* جميع محتويات الصفحة فوق الشعار */

.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

  position: relative;

  z-index: 2;

}





/* ضمان شفافية منطقة المحتوى */

.erp-dashboard-content,

.erp-module-section,

.erp-dashboard-grid {

  background: transparent !important;

}





/* =========================================================

   3. CONTENT LAYER

========================================================= */



.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

  position: relative;

  z-index: 2;

}





/* =========================================================

   4. STATISTICS GRID

========================================================= */



.erp-stats-grid {

  display: grid !important;



  grid-template-columns:

    repeat(4, minmax(0, 1fr)) !important;



  gap: 14px;



  margin: 18px 0 24px;

}





/* =========================================================

   5. STAT CARD

========================================================= */



.erp-stat-card {

  display: flex;



  align-items: center;



  gap: 12px;



  min-width: 0;



  padding: 16px 18px;



  border: 1px solid var(--brand-border);

  border-radius: 14px;



  background: var(--fg-color, #ffffff);



  box-shadow:

    0 4px 14px rgba(36, 59, 99, 0.06);



  transition:

    transform 0.22s ease,

    border-color 0.22s ease,

    box-shadow 0.22s ease;

}





@media (hover: hover) {



  .erp-stat-card:hover {

    transform: translateY(-3px);



    border-color: var(--brand-border-strong);



    box-shadow:

      0 10px 26px rgba(36, 59, 99, 0.11);

  }



}





/* =========================================================

   6. STAT ICON

========================================================= */



.erp-stat-icon {

  display: flex;



  align-items: center;

  justify-content: center;



  width: 44px;

  height: 44px;



  flex: 0 0 44px;



  border-radius: 12px;



  background: var(--brand-soft);



  font-size: 21px;

}





/* =========================================================

   7. STAT INFO

   لون النص موحد لجميع بطاقات الإحصائيات

========================================================= */



.erp-stat-info {

  display: flex;



  flex-direction: column;



  gap: 3px;



  min-width: 0;



  color: var(--brand-text) !important;

}





/* الرقم / القيمة */



.erp-stat-value,

.erp-stat-card .erp-stat-value {

  color: var(--brand-text) !important;



  font-size: 18px !important;

  font-weight: 800 !important;



  line-height: 1.3;



  direction: ltr;

}





/* اسم الإحصائية */



.erp-stat-label,

.erp-stat-card .erp-stat-label {

  color: var(--brand-text) !important;



  font-size: 11.5px !important;

  font-weight: 600 !important;



  line-height: 1.45;

}





/* فرض اللون على أي عناصر داخل بطاقة الإحصائية */



.erp-stat-card .erp-stat-info,

.erp-stat-card .erp-stat-info span {

  color: var(--brand-text) !important;

}





/* =========================================================

   8. STAT CARD SOFT COLORS

   اللون يطبق على خلفية الأيقونة فقط

   وليس على النص

========================================================= */



.erp-stat-card:nth-child(1) .erp-stat-icon {

  background: var(--brand-soft);

}



.erp-stat-card:nth-child(2) .erp-stat-icon {

  background: var(--brand-soft-secondary);

}



.erp-stat-card:nth-child(3) .erp-stat-icon {

  background: var(--brand-soft-accent);

}



.erp-stat-card:nth-child(4) .erp-stat-icon {

  background: var(--brand-soft-purple);

}





/* =========================================================

   9. SECTION

========================================================= */



.erp-quick-actions {

  margin-bottom: 24px;

}



.erp-module-section {

  margin-top: 24px;

}





/* =========================================================

   10. SECTION TITLE

========================================================= */



.erp-section-title {

  position: relative;



  display: flex;



  align-items: center;



  min-height: 36px;



  margin: 0 0 14px;



  padding: 0 0 9px;



  border-bottom:

    1px solid var(--brand-border);



  color: var(--brand-text) !important;



  font-size: 18px;

  font-weight: 600;



  line-height: 1.4;

}





.erp-section-title::after {

  content: "";



  position: absolute;



  bottom: -1px;



  width: 52px;

  height: 2px;



  border-radius: 20px;



  background: var(--brand-primary);

}





.erp-dashboard-rtl

.erp-section-title::after {

  right: 0;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-section-title::after {

  left: 0;

}





/* =========================================================

   11. QUICK ACTIONS GRID

========================================================= */



.erp-quick-grid {

  display: grid !important;



  grid-template-columns:

    repeat(4, minmax(0, 1fr)) !important;



  gap: 12px;

}





/* =========================================================

   12. QUICK BUTTONS

   بدون أيقونات

   لون الخط موحد

========================================================= */



.erp-quick-btn {

  display: flex;



  align-items: center;

  justify-content: center;



  min-height: 48px;



  padding: 11px 14px;



  border:

    1px solid var(--brand-border);



  border-radius: 10px;



  outline: none;



  background: var(--brand-soft);



  color: var(--brand-primary) !important;



  font-family: inherit;



  font-size: 15px;

  font-weight: 700;



  line-height: 1.4;



  text-align: center;



  cursor: pointer;



  transition:

    transform 0.18s ease,

    background-color 0.18s ease,

    border-color 0.18s ease,

    color 0.18s ease,

    box-shadow 0.18s ease;

}





.erp-quick-btn:nth-child(2) {

  background: var(--brand-soft-secondary);

}



.erp-quick-btn:nth-child(3) {

  background: var(--brand-soft-accent);

}



.erp-quick-btn:nth-child(4) {

  background: var(--brand-soft-purple);

}





.erp-quick-btn,

.erp-quick-btn .erp-quick-label {

  color: var(--brand-primary) !important;

}





@media (hover: hover) {



  .erp-quick-btn:hover {

    transform: translateY(-2px);



    color: var(--brand-secondary) !important;



    border-color: var(--brand-secondary);



    background:

      rgba(15, 132, 181, 0.10);



    box-shadow:

      0 6px 16px rgba(56, 103, 174, 0.12);

  }



}





.erp-quick-btn:active {

  transform: scale(0.98);

}





.erp-quick-label {

  width: 100%;



  white-space: normal;



  text-align: center;

}





/* =========================================================

   13. REPORT CARDS GRID

========================================================= */



.erp-dashboard-grid {

  display: grid !important;



  grid-template-columns:

    repeat(3, minmax(0, 1fr)) !important;



  align-items: start;



  gap: 16px;



  width: 100%;



  overflow: visible;

}





/* =========================================================

   14. REPORT CARD CLOSED

========================================================= */



.erp-card {

  --erp-accent: var(--brand-primary);

  --erp-soft: var(--brand-soft);



  position: relative;



  z-index: 1;



  min-width: 0;



  min-height: 74px;

  max-height: 74px;



  padding: 0 16px;



  overflow: hidden;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  background: var(--fg-color, #ffffff);



  color: var(--brand-text) !important;



  box-shadow:

    0 5px 16px rgba(36, 59, 99, 0.06);



  transition:

    max-height 0.4s ease,

    transform 0.28s ease,

    box-shadow 0.28s ease,

    border-color 0.28s ease,

    padding-bottom 0.28s ease;

}





/* soft background */



.erp-card::before {

  content: "";



  position: absolute;



  inset: 0;



  z-index: 0;



  background: var(--erp-soft);



  opacity: 0;



  pointer-events: none;



  transition:

    opacity 0.25s ease;

}





/* bottom accent */



.erp-card::after {

  content: "";



  position: absolute;



  right: 0;

  bottom: 0;



  z-index: 4;



  width: 0;

  height: 3px;



  background: var(--erp-accent);



  transition:

    width 0.3s ease;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-card::after {

  right: auto;

  left: 0;

}





/* =========================================================

   15. CARD BRAND TONES

========================================================= */



.erp-card.tone-0 {

  --erp-accent: var(--brand-primary);

  --erp-soft: var(--brand-soft);

}



.erp-card.tone-1 {

  --erp-accent: var(--brand-secondary);

  --erp-soft: var(--brand-soft-secondary);

}



.erp-card.tone-2 {

  --erp-accent: var(--brand-accent);

  --erp-soft: var(--brand-soft-accent);

}



.erp-card.tone-3 {

  --erp-accent: var(--brand-purple);

  --erp-soft: var(--brand-soft-purple);

}



.erp-card.tone-4 {

  --erp-accent: var(--brand-primary);

  --erp-soft: var(--brand-soft);

}





/* =========================================================

   16. CARD OPEN

========================================================= */



.erp-card.is-open {

  z-index: 30;



  max-height: 590px;



  padding-bottom: 15px;



  border-color:

    var(--erp-accent);



  transform:

    translateY(-5px);



  box-shadow:

    0 18px 40px rgba(36, 59, 99, 0.14);

}





.erp-card.is-open::before {

  opacity: 1;

}





.erp-card.is-open::after {

  width: 100%;

}











/* =========================================================

   17. CARD HEADING

========================================================= */



.erp-card-heading {

  position: relative;



  z-index: 2;



  display: flex;



  align-items: center;



  gap: 8px;



  width: 100%;

  height: 72px;



  margin: 0;

  padding: 0;



  border: 0;

  border-bottom:

    1px solid transparent;



  outline: none;



  background: transparent;



  color: var(--brand-text) !important;



  font-family: inherit;



  text-align: inherit;



  cursor: pointer;



  transition:

    border-color 0.22s ease,

    margin-bottom 0.22s ease;

}





.erp-card.is-open

.erp-card-heading {

  margin-bottom: 10px;



  border-bottom-color:

    var(--brand-border);

}











/* =========================================================

   18. CARD TITLE

   لون موحد لكل البطاقات

========================================================= */



.erp-card-title,

.erp-card .erp-card-title {

  flex: 1;



  min-width: 0;



  color: var(--brand-text) !important;



  font-size: 16px;

  font-weight: 800;



  line-height: 1.5;

}





/* =========================================================

   19. CARD CHEVRON

========================================================= */



.erp-card-chevron {

  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 28px;

  height: 28px;



  flex: 0 0 28px;



  border-radius: 8px;



  background: var(--erp-soft);



  color: var(--erp-accent) !important;



  font-size: 17px;



  transition:

    transform 0.22s ease;

}





.erp-card.is-open

.erp-card-chevron {

  transform: rotate(180deg);

}











/* =========================================================

   20. CARD LINKS

========================================================= */



.erp-card-links {

  position: relative;



  z-index: 2;



  display: grid;



  gap: 5px;



  max-height: 0;



  margin: 0;

  padding: 0;



  overflow: hidden;



  opacity: 0;



  visibility: hidden;



  pointer-events: none;



  transform:

    translateY(-8px);



  transition:

    max-height 0.38s ease,

    opacity 0.2s ease,

    visibility 0.2s ease,

    transform 0.28s ease;

}





.erp-card.is-open

.erp-card-links {

  max-height: 480px;



  overflow-y: auto;



  opacity: 1;



  visibility: visible;



  pointer-events: auto;



  transform:

    translateY(0);

}











/* =========================================================

   21. LINK ROW

========================================================= */



.erp-link-row {

  display: flex;



  align-items: center;



  gap: 6px;



  width: 100%;

}





/* =========================================================

   22. CARD LINK

   لون النص الأساسي موحد

========================================================= */



.erp-link {

  display: flex;



  align-items: center;



  gap: 7px;



  flex: 1;



  min-width: 0;



  min-height: 36px;



  padding: 7px 10px;



  border:

    1px solid transparent;



  border-radius: 8px;



  outline: none;



  background:

    transparent;



  color: var(--brand-text) !important;



  font-family: inherit;



  font-size: 13px;



  font-weight: 500;



  line-height: 1.45;



  text-align: inherit;



  cursor: pointer;



  transition:

    background 0.16s ease,

    color 0.16s ease,

    border-color 0.16s ease,

    transform 0.16s ease;

}





.erp-link-text {

  flex: 1;



  min-width: 0;



  color: inherit !important;

}





.erp-link:hover,

.erp-link:focus {

  border-color:

