    translateX(-3px);

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-link:hover,



.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-link:focus {

  transform:

    translateX(3px);

}





/* =========================================================

   23. LINK ARROW

========================================================= */



.erp-link-arrow {

  flex: 0 0 auto;



  color:

    var(--erp-accent) !important;



  font-size: 13px;



  font-weight: 800;



  opacity: 0;



  transition:

    opacity 0.16s ease;

}





.erp-link:hover .erp-link-arrow,

.erp-link:focus .erp-link-arrow {

  opacity: 1;

}





/* =========================================================

   24. DETAILS BUTTON

========================================================= */



.erp-info-link {

  flex: 0 0 auto;



  padding: 5px 10px;



  border:

