  .erp-quick-grid {



    grid-template-columns:

      repeat(2, minmax(0, 1fr)) !important;



    gap:

      8px;

  }





  .erp-quick-btn {



    min-height:

      43px;



    padding:

      9px 7px;



    font-size:

      11.5px;

  }





  /* التقارير */



  .erp-dashboard-grid {



    grid-template-columns:

      1fr !important;



    gap:

