  }





  /* المودال */



  .erp-modal-overlay {



    align-items:

      flex-end;



    padding:

      10px;

  }





  .erp-modal-box {



    max-height:

      82vh;



    padding:

      22px 17px;



    border-radius:

      16px 16px 0 0;

