            repeat(

              ${hrCycleCards.length},

              minmax(0,1fr)

            );

          "

        >



          ${hrCycleCards

            .map(

              (card, index) => `



                <div class="erp-cycle-item">



                  <button

                    type="button"

                    class="

                      erp-cycle-card

                      cycle-tone-${(index % 4) + 1}

                    "

                    data-hr-cycle="${index}"

                  >



                    <span class="erp-cycle-number">

                      ${card.step}

                    </span>



                    <span class="erp-cycle-card-title">



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>



                    <span class="erp-cycle-description">



                      ${escapeHtml(

                        isArabic

                          ? card.descriptionAr

                          : card.descriptionEn

                      )}



                    </span>



                  </button>





                  ${

                    index <

                    hrCycleCards.length - 1



                      ? `

                        <span

                          class="erp-cycle-arrow"

                          aria-hidden="true"

                        >

                          ${isArabic ? "←" : "→"}

                        </span>

                      `

                      : ""

                  }



                </div>



              `

            )

            .join("")}



        </div>



      </section>



    `;





    hrCycle.addEventListener(

      "click",

      event => {



        const element =

          event.target.closest(

            "[data-hr-cycle]"

          );





        if (!element)

          return;





        const card =

          hrCycleCards[

            Number(

              element.dataset.hrCycle

            )

          ];





        if (!card)

          return;





        if (card.action === "new") {



          newDoc(card.doctype);

          return;

        }





        if (

          card.action ===

          "organization-selector"

        ) {



          showSelector(



            "الهيكل الوظيفي",

            "Organization Structure",



            [

              {

                action: "route",

                doctype: "Department",

                labelAr: "الأقسام",

                labelEn: "Departments"

              },



              {

                action: "route",

                doctype: "Designation",

                labelAr: "المسميات الوظيفية",

                labelEn: "Designations"

              },



              {

                action: "route",

                doctype: "Branch",

                labelAr: "الفروع",

                labelEn: "Branches"

              }

            ]



          );



          return;

        }





        if (

          card.action ===

          "attendance-selector"

        ) {



          showSelector(



            "الحضور والانصراف",

            "Attendance",



            [

              {

                action: "route",

                doctype: "Attendance",

                labelAr: "الحضور",

                labelEn: "Attendance"

              },



              {

                action: "route",

                doctype: "Employee Checkin",

                labelAr: "دخول وانصراف الموظف",

                labelEn: "Employee Checkin"

              },



              {

                action: "route",

                doctype: "Shift Assignment",

                labelAr: "تعيين الورديات",

                labelEn: "Shift Assignment"

              }

            ]



          );



          return;

        }





        if (

          card.action ===

          "payroll-selector"

        ) {



          showSelector(



            "الرواتب",

            "Payroll",



            [

              {

                action: "route",

                doctype: "Payroll Entry",

                labelAr: "مسير الرواتب",

                labelEn: "Payroll Entry"

              },



              {

                action: "route",

                doctype: "Salary Slip",

                labelAr: "قسائم الرواتب",

                labelEn: "Salary Slips"

              },



              {

                action: "route",

                doctype: "Salary Structure",

                labelAr: "هياكل الرواتب",

