  /* =========================================================

     13. RENDER STATS

  ========================================================= */



  function renderStats() {



    if (!statsSection)

      return;





    statsSection.innerHTML = `



      <section class="erp-overview-container">



        <h2 class="erp-section-title">

          ${

            isArabic

              ? "نظرة عامة"

              : "Overview"

          }

        </h2>





        <div class="erp-stats-grid">



          ${statsCards

            .map(

              (card, index) => `



                <div

                  class="

                    erp-stat-card

                    overview-tone-${index + 1}

                  "

                >



                  <div class="erp-stat-icon">

                    ${escapeHtml(card.short)}

                  </div>





                  <div class="erp-stat-info">



                    <span

                      class="erp-stat-value"

                      data-hr-stat="${card.id}"

                    >

                      0

                    </span>





                    <span class="erp-stat-label">



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>



                  </div>



                </div>



              `

            )

            .join("")}



        </div>



      </section>



    `;





    statsCards.forEach(card => {



      Promise

        .resolve()

        .then(() => card.fetch())

        .then(value => {



          const element =

            statsSection.querySelector(

              `[data-hr-stat="${card.id}"]`

            );





          if (element) {



            element.textContent =

              formatNumber(value);



          }



        })

        .catch(error => {



          console.error(

            "HR Stat Error:",

            card.id,

            error

          );



        });



    });



  }





  /* =========================================================

     14. QUICK ACTIONS

  ========================================================= */



  function renderQuickActions() {



    if (!quickActions)

      return;





    quickActions.innerHTML = `



      <h2 class="erp-section-title">

        ${

          isArabic

            ? "اختصارات سريعة"

            : "Quick Actions"

        }

      </h2>





      <div class="erp-quick-grid">



        ${quickActionButtons

          .map(

            (button, index) => `



              <button

                type="button"

                class="erp-quick-btn"

                data-hr-quick="${index}"

              >



                <span class="erp-quick-label">



                  ${escapeHtml(

                    isArabic

                      ? button.labelAr

                      : button.labelEn

                  )}



                </span>



              </button>



            `

          )

          .join("")}



      </div>



    `;





    quickActions.addEventListener(

      "click",

      event => {



        const element =

          event.target.closest(

            "[data-hr-quick]"

          );





        if (!element)

          return;





        const button =

          quickActionButtons[

            Number(

              element.dataset.hrQuick

            )

          ];





        if (!button)

          return;





        newDoc(

          button.doctype

        );



      }

    );



  }





  /* =========================================================

     15. RENDER SECTIONS

  ========================================================= */



  function renderSections() {



    if (!content)

      return;





    content.innerHTML =

      sections

        .map(

          (section, sectionIndex) => {



            const cards =

              section[1]

                .map(

                  (card, cardIndex) => {



                    const links =

                      card[2]

                        .map(

                          item => `



                            <div class="erp-link-row">



                              <button

                                type="button"

                                class="erp-link"

                                data-hr-route="${escapeHtml(item)}"

                              >



                                <span class="erp-link-text">

                                  ${escapeHtml(translate(item))}

                                </span>



                                <span class="erp-link-arrow">

                                  ${isArabic ? "←" : "→"}

                                </span>



                              </button>



                            </div>



                          `

                        )

                        .join("");





                    return `



                      <article

                        class="

                          erp-card

                          tone-${(sectionIndex + cardIndex) % 5}

                        "

                        data-hr-card

                      >



                        <button

                          type="button"

                          class="erp-card-heading"

                          data-hr-toggle

                          aria-expanded="false"

                        >



                          <span class="erp-icon">

                            ${card[1]}

                          </span>



                          <span class="erp-card-title">

                            ${escapeHtml(translate(card[0]))}

                          </span>



                          <span class="erp-card-chevron">

                            ⌄

                          </span>



                        </button>





                        <div class="erp-card-links">

                          ${links}

                        </div>



                      </article>



                    `;



                  }

                )

                .join("");





            return `



              <section class="erp-module-section">



                <h2 class="erp-section-title">

                  ${escapeHtml(translate(section[0]))}

                </h2>



                <div class="erp-dashboard-grid">

                  ${cards}

                </div>



              </section>



            `;



          }

        )

        .join("");





    content.addEventListener(

      "click",

      event => {





        const routeButton =

          event.target.closest(

            "[data-hr-route]"

          );





        if (routeButton) {



          event.preventDefault();



          openRoute(

            routeButton.dataset.hrRoute

          );



          return;

        }





        const toggle =

          event.target.closest(

            "[data-hr-toggle]"

          );





        if (!toggle)

          return;





        const selectedCard =

          toggle.closest(

            "[data-hr-card]"

          );





        if (!selectedCard)

          return;





        const shouldOpen =

          !selectedCard

            .classList

            .contains(

              "is-open"

            );





        content

          .querySelectorAll(

            "[data-hr-card]"

          )

          .forEach(card => {



            if (

              card !== selectedCard

            ) {



              card.classList.remove(

                "is-open"

              );



            }



          });





        selectedCard

          .classList

          .toggle(

            "is-open",

            shouldOpen

          );



      }

    );



  }





  /* =========================================================

     16. FOOTER

  ========================================================= */



  function renderFooter() {



    if (!footerEl)

      return;





    footerEl.innerHTML = `



