            }

          </span>



          <a

            href="mailto:sales@mubtkir.com"

            class="erp-footer-link"

          >

            sales@mubtkir.com

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ◎

          </span>



          <span class="erp-footer-label">

            ${

              isArabic

                ? "الموقع:"

                : "Website:"

            }

          </span>



          <a

            href="https://www.mubtkir.com"

            class="erp-footer-link"

            target="_blank"

            rel="noopener"

          >

            www.mubtkir.com

          </a>



        </div>



      </div>



    `;



  }





  /* =========================================================

     17. INIT

  ========================================================= */



  try {



    renderHRCycle();



  } catch (e) {



    console.error(

      "HR Cycle Error:",

      e

    );



  }





  try {



    renderStats();



  } catch (e) {



    console.error(

      "HR Stats Error:",

      e

    );



  }





  try {



    renderQuickActions();



  } catch (e) {



    console.error(

      "HR Quick Actions Error:",

      e

    );



  }





  try {



    renderSections();



  } catch (e) {



    console.error(

      "HR Sections Error:",

      e

    );



  }





  try {



    renderFooter();



  } catch (e) {



    console.error(

      "HR Footer Error:",

      e

    );



  }



})();

