.erp-footer-icon {



  display: inline-flex;



  align-items: center;

  justify-content: center;



  color:

    var(--brand-primary) !important;



  font-size:

    17px !important;



  line-height:

    1;

}





.erp-footer-label {



  color:

    var(--brand-text) !important;



  font-size:

    var(--footer-font-size) !important;



  font-weight:

    700 !important;

}





.erp-footer-link {



  color:

    var(--brand-primary) !important;



  font-size:

    var(--footer-font-size) !important;



  font-weight:

    600 !important;



  text-decoration: none;



  transition:

    color 0.18s ease;

