  font-size: 20px;

  font-weight: 800;



  line-height: 1;



  opacity: 0.55;



  transform:

    translateY(-50%);



  pointer-events: none;



  z-index: 10;

}





.erp-dashboard-rtl

.erp-cycle-arrow {



  left: -17px;

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-cycle-arrow {



  right: -17px;

}





/* =========================================================

   15. OVERVIEW SECTION

========================================================= */



.erp-stats-section {



  margin: 0 0 24px;

}





.erp-overview-container {



  padding: 18px;



  border:

    1px solid var(--brand-border);



  border-radius: 16px;



  background:

    rgba(255, 255, 255, 0.94);



  box-shadow:

    0 5px 18px rgba(36, 59, 99, 0.06);

