.erp-dashboard-rtl

.erp-link:focus {



  transform:

    translateX(-3px);

}





.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-link:hover,



.erp-dashboard-wrapper:not(.erp-dashboard-rtl)

.erp-link:focus {



  transform:

    translateX(3px);

}





/* =========================================================

   35. LINK ARROW

========================================================= */



.erp-link-arrow {



  flex:

    0 0 auto;



  color:

    var(--erp-accent) !important;



  font-size:

    13px;



  font-weight:

    800;



  opacity: 0;



  transition:

    opacity 0.16s ease;

}





.erp-link:hover

.erp-link-arrow,



.erp-link:focus

.erp-link-arrow {



  opacity: 1;

}





/* =========================================================

   36. DETAILS BUTTON

========================================================= */



.erp-info-link {



  flex:

    0 0 auto;



  padding:

    5px 10px;



  border:

    1px solid var(--brand-border);



  border-radius:

    7px;



  outline: none;



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;



  font-family:

    inherit;



  font-size:

    12px;



  font-weight:

    600;



  cursor: pointer;



  transition:

    border-color 0.16s ease,

    background 0.16s ease,

    color 0.16s ease;

}





.erp-info-link:hover {



  border-color:

    var(--brand-primary);



  background:

    rgba(56, 103, 174, 0.13);



  color:

    var(--brand-primary) !important;

