  /* =========================================================

     3. ROUTING

  ========================================================= */



  const reportNames =

    new Set([

      "Unpaid Expense Claim",

      "Employee Advance Summary"

    ]);





  const treeDocs =

    new Set([

      "Cost Center"

    ]);





  function openRoute(name) {



    try {



      if (

        reportNames.has(name)

      ) {



        frappe.set_route(

          "query-report",

          name

        );



        return;

      }





      if (

        treeDocs.has(name)

      ) {



        frappe.set_route(

          "Tree",

          name

        );



        return;

      }





      frappe.set_route(

        "List",

        name

      );



