script:
(() => {



  /* =========================================================

     MUBTKIR ERP — PERFORMANCE WORKSPACE

     لوحة تحكم الأداء والتقييم

  ========================================================= */



  const root =

    root_element.querySelector("[data-erp-dashboard]");



  const cycleSection =

    root_element.querySelector("[data-purchase-cycle]");



  const statsSection =

    root_element.querySelector("[data-stats-section]");



  const quickActions =

    root_element.querySelector("[data-quick-actions]");



  const content =

    root_element.querySelector("[data-dashboard-content]");



  const footerEl =

    root_element.querySelector("[data-dashboard-footer]");



  if (!root) return;





  /* =========================================================

     1. LANGUAGE

  ========================================================= */



  const langValue =

    window.frappe?.boot?.lang ||

    document.documentElement.lang ||

    "en";



  const isArabic =

    String(langValue)

      .toLowerCase()

      .startsWith("ar");



  root.setAttribute(

    "dir",

    isArabic ? "rtl" : "ltr"

  );





  /* =========================================================

     2. HELPERS

  ========================================================= */



  function escapeHtml(value) {



    return String(value ?? "")

      .replace(/&/g, "&amp;")

      .replace(/</g, "&lt;")

      .replace(/>/g, "&gt;")

      .replace(/"/g, "&quot;")

      .replace(/'/g, "&#039;");

  }





  function formatNumber(value) {



    return (

      parseFloat(value) || 0

    ).toLocaleString("en-US");

  }





  function safeCount(

    doctype,

    filters = {}

  ) {



    return new Promise(resolve => {



      try {



        frappe.call({



          method:

            "frappe.client.get_count",



          args: {

            doctype,

            filters

          },



          callback: r => {



            resolve(

              r?.message || 0

            );



          },



          error: () =>

            resolve(0)



        });



      } catch (e) {



        console.error(

          "Performance Count Error:",

          doctype,

          e

        );



        resolve(0);



      }



    });



  }





  function newDoc(doctype) {



    try {



      frappe.new_doc(

        doctype

      );



    } catch (e) {



      console.error(

        "Performance New Doc Error:",

        doctype,

        e

      );



    }



  }





  /* =========================================================

     3. ROUTING

  ========================================================= */



  const reportNames =

    new Set([

      "Appraisal Overview",

      "Employee Performance Feedback"

    ]);





  const treeDocs =

    new Set([

      "Department"

    ]);





  function openRoute(name) {



    try {



      if (

        reportNames.has(name)

      ) {



        frappe.set_route(

          "query-report",

          name

        );



        return;

      }





      if (

        treeDocs.has(name)

      ) {



        frappe.set_route(

          "Tree",

          name

        );



        return;

      }





      frappe.set_route(

        "List",

        name

      );



    } catch (e) {



      console.error(

        "Performance Route Error:",

        name,

        e

      );



    }



  }





  /* =========================================================

     4. PERFORMANCE CYCLE

  ========================================================= */



  const cycleCards = [



