  /* =========================================================

     9. GOAL SELECTOR

  ========================================================= */



  function showGoalSelector() {



    const overlay =

      document.createElement("div");



    overlay.className =

      "erp-modal-overlay";



    overlay.setAttribute(

      "dir",

      isArabic

        ? "rtl"

