                    <span

                      class="erp-stat-value"

                      data-performance-stat="${card.id}"

                    >

                      0

                    </span>





                    <span

                      class="erp-stat-label"

                    >



                      ${escapeHtml(

                        isArabic

                          ? card.labelAr

                          : card.labelEn

                      )}



                    </span>



                  </div>



                </div>



              `

            )

            .join("")}



        </div>



      </section>



    `;





    statsCards.forEach(

      card => {



        Promise

          .resolve()

          .then(

            () => card.fetch()

          )

          .then(

            value => {



              const element =

                statsSection.querySelector(

                  `[data-performance-stat="${card.id}"]`

                );





              if (element) {



                element.textContent =

                  formatNumber(value);



              }



            }

          )

          .catch(

            error => {



              console.error(

                "Performance Stat Error:",

                card.id,

                error

              );



            }

          );



      }

    );



  }





  /* =========================================================

     12. QUICK ACTIONS

  ========================================================= */



  function renderQuickActions() {



    if (!quickActions)

      return;





    quickActions.innerHTML = `



      <h2 class="erp-section-title">



        ${

          isArabic

            ? "اختصارات سريعة"

            : "Quick Actions"

        }



      </h2>





      <div class="erp-quick-grid">



        ${quickButtons

          .map(

            (button, index) => `



              <button

                type="button"

                class="erp-quick-btn"

                data-performance-quick="${index}"

              >



                <span class="erp-quick-label">



                  ${escapeHtml(

                    isArabic

                      ? button.labelAr

                      : button.labelEn

                  )}



                </span>



              </button>



            `

          )

          .join("")}



      </div>



    `;





    quickActions.addEventListener(

      "click",

      event => {



        const element =

          event.target.closest(

            "[data-performance-quick]"

          );





        if (!element)

          return;





        const button =

          quickButtons[

            Number(

              element.dataset.performanceQuick

            )

          ];





        if (!button)

          return;





        newDoc(

          button.doctype

        );



      }

    );



  }





  /* =========================================================

     13. RENDER CARDS

  ========================================================= */



  function renderCards() {



    if (!content)

      return;





    const cardsHtml =

      cards

        .map(

          (card, index) => {



            const links =

              card.links

                .map(

                  item => `



                    <div class="erp-link-row">



                      <button

                        type="button"

                        class="erp-link"

                        data-performance-route="${escapeHtml(item)}"

                      >



                        <span class="erp-link-text">

                          ${escapeHtml(translate(item))}

                        </span>





                        <span class="erp-link-arrow">

                          ${isArabic ? "←" : "→"}

                        </span>



                      </button>



                    </div>



                  `

                )

                .join("");





            return `



              <article

                class="

                  erp-card

                  tone-${index % 5}

                "

                data-performance-card

              >



                <button

                  type="button"

                  class="erp-card-heading"

                  data-performance-toggle

                  aria-expanded="false"

                >



                  <span class="erp-icon">

                    ${card.icon}

                  </span>





                  <span class="erp-card-title">



                    ${escapeHtml(

                      isArabic

                        ? card.titleAr

                        : card.titleEn

                    )}



                  </span>





                  <span class="erp-card-chevron">

                    ⌄

                  </span>



                </button>





                <div class="erp-card-links">

                  ${links}

                </div>



              </article>



            `;



          }

        )

        .join("");





    content.innerHTML = `



      <section class="erp-module-section">



        <h2 class="erp-section-title">



          ${

            isArabic

              ? "البيانات الرئيسية والتقارير"

              : "Reports & Masters"

          }



        </h2>





        <div class="erp-dashboard-grid">

          ${cardsHtml}

        </div>



      </section>



    `;





    content.addEventListener(

      "click",

      event => {



        const routeButton =

          event.target.closest(

            "[data-performance-route]"

          );





        if (routeButton) {



          event.preventDefault();



          openRoute(

            routeButton.dataset.performanceRoute

          );



          return;

        }





        const toggle =

          event.target.closest(

            "[data-performance-toggle]"

          );





        if (!toggle)

          return;





        const selectedCard =

          toggle.closest(

            "[data-performance-card]"

          );





        if (!selectedCard)

          return;





        const shouldOpen =

          !selectedCard.classList.contains(

            "is-open"

          );





        content

          .querySelectorAll(

            "[data-performance-card]"

          )

          .forEach(card => {



            if (

              card !== selectedCard

            ) {



              card.classList.remove(

                "is-open"

              );



            }



          });





        selectedCard.classList.toggle(

          "is-open",

          shouldOpen

        );



      }

    );



  }





  /* =========================================================

     14. FOOTER

  ========================================================= */



  function renderFooter() {



    if (!footerEl)

      return;





    footerEl.innerHTML = `



      <div class="erp-footer-inner">



        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ☎

          </span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? "الهاتف الموحد:"

                : "Phone:"

            }



          </span>



          <a

            href="tel:0115110455"

            class="erp-footer-link"

            dir="ltr"

          >

            0115110455

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ✉

          </span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? "البريد الإلكتروني:"

                : "Email:"

            }



          </span>



          <a

            href="mailto:sales@mubtkir.com"

            class="erp-footer-link"

          >

            sales@mubtkir.com

          </a>



        </div>





        <span class="erp-footer-sep">

          |

        </span>





        <div class="erp-footer-item">



          <span class="erp-footer-icon">

            ◎

          </span>



          <span class="erp-footer-label">



            ${

              isArabic

                ? "الموقع:"

                : "Website:"

            }



          </span>



          <a

            href="https://www.mubtkir.com"

            class="erp-footer-link"

            target="_blank"

            rel="noopener"

          >

            www.mubtkir.com

          </a>



        </div>



      </div>



    `;



  }





  /* =========================================================

     15. INIT

  ========================================================= */



  try {

    renderCycle();

  } catch (e) {

    console.error(

      "Performance Cycle Error:",

      e

    );

  }





  try {

    renderStats();

  } catch (e) {

    console.error(

      "Performance Stats Error:",

      e

    );

  }





  try {

    renderQuickActions();

  } catch (e) {

    console.error(

      "Performance Quick Actions Error:",

      e

    );

  }





  try {

    renderCards();

  } catch (e) {

    console.error(

      "Performance Cards Error:",

      e

    );

  }





  try {

    renderFooter();

  } catch (e) {

    console.error(

      "Performance Footer Error:",

      e

    );

  }



})();

