    inherit;

  font-size:
    12.5px;

  font-weight:
    700;

  cursor:
    pointer;
}


.erp-modal-toggle-steps:hover {

  background:
    rgba(56, 103, 174, 0.13);
}


/* =========================================================
   44. MODAL STEPS
========================================================= */

.erp-modal-steps {

  max-height: 0;

  overflow: hidden;

  opacity: 0;

  margin-top: 0;

  transition:
    max-height 0.38s ease,
    opacity 0.25s ease,
    margin-top 0.25s ease;
}


.erp-modal-steps.is-shown {

  max-height: 500px;

  opacity: 1;

  margin-top:
    15px;
}


.erp-modal-steps-list {

  margin: 0;

  padding:
    0 20px;

  list-style: none;

  counter-reset:
    step-counter;
}


.erp-modal-steps-list li {

  position: relative;

  counter-increment:
    step-counter;

  padding:
    9px 0;

  border-bottom:
    1px solid rgba(56, 103, 174, 0.10);

  color:
    var(--brand-text) !important;

  font-size:
    12.5px;

  line-height:
    1.65;
}


.erp-modal-steps-list li:last-child {

  border-bottom: 0;
}


.erp-modal-steps-list li::before {

  content:
    counter(step-counter);

  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 22px;
  height: 22px;

  margin-inline-end:
    9px;

  border-radius:
    50%;

  background:
    var(--brand-primary);

  color:
    #ffffff;

  font-size:
    10px;

  font-weight:
    800;
}


/* =========================================================
   45. DARK MODE
========================================================= */

[data-theme="dark"]
.erp-dashboard-wrapper,

html[data-theme="dark"]
.erp-dashboard-wrapper {

  --brand-text:
    #E9EEF7;

  --brand-muted:
    #A7B2C5;

  --brand-border:
    rgba(15, 132, 181, 0.22);

  --brand-border-strong:
    rgba(15, 132, 181, 0.40);
}


/*
   في الوضع الداكن نقلل وضوح Pattern
*/

[data-theme="dark"]
.erp-dashboard-wrapper::before,

html[data-theme="dark"]
.erp-dashboard-wrapper::before {

  opacity: 0.025;
}


[data-theme="dark"]
.erp-cycle-container,

html[data-theme="dark"]
.erp-cycle-container,

[data-theme="dark"]
.erp-overview-container,

html[data-theme="dark"]
.erp-overview-container,

[data-theme="dark"]
.erp-cycle-card,

html[data-theme="dark"]
.erp-cycle-card,

[data-theme="dark"]
