  function fetchAccountBalance(accountType) {

    return new Promise((resolve) => {

      const company =
        frappe.defaults.get_default("company");

      frappe.call({

        method:
          "frappe.client.get_list",

        args: {

          doctype:
            "Account",

          filters: {
            account_type: accountType,
            is_group: 0,
            company: company
          },

          fields: [
            "name"
          ],

          limit_page_length: 0
        },

        async: true,

        callback: (accountsResponse) => {

          const accounts =
            accountsResponse?.message || [];

          if (!accounts.length) {
            resolve(0);
            return;
          }

          frappe.call({

            method:
              "frappe.client.get_list",

            args: {

              doctype:
                "GL Entry",

              filters: {

                account: [
                  "in",
                  accounts.map(
                    (account) =>
                      account.name
                  )
                ],

                is_cancelled: 0
              },

              fields: [
                "sum(debit - credit) as balance"
              ],

              limit_page_length: 0,

              order_by:
                "name asc"
            },

            async: true,

            callback: (response) => {

              resolve(
                response?.message?.[0]?.balance ||
                0
              );

            },

            error: () => {
              resolve(0);
            }

          });

        },

        error: () => {
          resolve(0);
        }

      });

    });

  }

