  function escapeHtml(value) {

    return String(value ?? "")
      .replaceAll(
        "&",
        "&amp;"
      )
      .replaceAll(
        "<",
        "&lt;"
      )
      .replaceAll(
        ">",
        "&gt;"
      )
      .replaceAll(
        '"',
        "&quot;"
      )
      .replaceAll(
        "'",
        "&#039;"
      );

  }


  function formatMoney(value) {

    const number =
      parseFloat(value) || 0;


    return number.toLocaleString(
      "en-US",
      {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      }
    ) +
      (
        isArabic
          ? " ر.س"
          : " SAR"
      );

  }


  function formatNumber(value) {

    return (
      parseFloat(value) || 0
    ).toLocaleString(
      "en-US"
    );

  }


  /* =========================================================
