     لا يوجد Inline Color
  ========================================================= */

  function renderStats() {

    if (!statsSection) {
      return;
    }


    statsSection.innerHTML = `

      <div class="erp-stats-grid">

        ${statsCards
          .map((card) => {

            const label =
              isArabic
                ? card.labelAr
                : card.labelEn;


            return `

              <div class="erp-stat-card">

                <div class="erp-stat-icon">
                  ${card.icon}
                </div>

                <div class="erp-stat-info">

                  <span
                    class="erp-stat-value"
                    data-stat-id="${escapeHtml(card.id)}"
                  >
                    ...
                  </span>

                  <span class="erp-stat-label">
                    ${escapeHtml(label)}
                  </span>

                </div>

              </div>

            `;

          })
          .join("")}

      </div>

    `;


    if (!window.frappe) {
      return;
    }


    statsCards.forEach((card) => {

      card
        .fetch()
        .then((value) => {

          const element =
            statsSection.querySelector(
              `[data-stat-id="${card.id}"]`
            );


          if (!element) {
            return;
          }


          element.textContent =
            formatMoney(value);

        })
        .catch(() => {

          const element =
            statsSection.querySelector(
              `[data-stat-id="${card.id}"]`
            );


          if (element) {
            element.textContent =
              formatMoney(0);
          }

        });

    });

  }


