        : "📖 Steps";


    const hideStepsText =
      isArabic
        ? "📖 إخفاء"
        : "📖 Hide";


    let html = "";


    shortcutSections.forEach((section) => {

      const sectionTitle =
        isArabic
          ? section.titleAr
          : section.titleEn;


      html += `

        <div class="erp-module-section">

          <h2 class="erp-section-title">
            ${section.icon}
            ${escapeHtml(sectionTitle)}
          </h2>

          <div class="erp-dashboard-grid">

      `;


      section.items.forEach((item) => {

        const label =
          isArabic
            ? item.labelAr
            : item.labelEn;


        const description =
          isArabic
            ? item.dAr
            : item.dEn;


        const steps =
          isArabic
            ? item.sAr
            : item.sEn;


        const suffixText =
          item.sfx
            ? (
                isArabic
                  ? item.sfx.ar
                  : item.sfx.en
              )
            : "";


        const stepsHtml = `

          <ol>

            ${steps
              .map(
                (step) =>
                  `<li>${escapeHtml(step)}</li>`
              )
              .join("")}

          </ol>

        `;


        html += `

          <div class="hm-shortcut">

            <div
              class="hm-sh-head"
              data-route="${escapeHtml(item.doctype)}"
              ${
                item.isReport
                  ? 'data-rpt="1"'
                  : ""
              }
              ${
                item.isTree
                  ? 'data-tree="1"'
                  : ""
              }
            >

              <span class="hm-sh-icon">
                ${item.icon}
              </span>

              <span class="hm-sh-name">
                ${escapeHtml(label)}
              </span>

              ${
                !item.isReport
                  ? `
                    <span
                      class="hm-sh-count zero"
                      data-cd="${escapeHtml(item.doctype)}"
                      data-cf='${JSON.stringify(item.cf || {})}'
                      data-cs="${escapeHtml(suffixText)}"
                    >
                      ...
                    </span>
                  `
                  : ""
              }

            </div>


            <p class="hm-sh-desc">
              ${escapeHtml(description)}
            </p>


            <button
              type="button"
              class="hm-sh-stepbtn"
              data-stoggle
            >
              ${showStepsText}
            </button>


            <div
              class="hm-sh-steps"
              style="display:none"
              data-scontent
            >
              ${stepsHtml}
            </div>

          </div>

        `;

      });


      html += `

          </div>

        </div>

      `;

    });


    quickActions.innerHTML =
      html;


    /* =============================
       جلب الأعداد
    ============================= */

    if (window.frappe) {

      quickActions
        .querySelectorAll(
          "[data-cd]"
        )
        .forEach((element) => {

          const doctype =
            element.dataset.cd;


          let filters = {};


          try {

            filters =
              JSON.parse(
                element.dataset.cf ||
                "{}"
              );

          } catch (error) {

            filters = {};

          }


          const suffix =
            element.dataset.cs ||
            "";


          frappe.call({

            method:
              "frappe.client.get_count",

            args: {

              doctype:
                doctype,

              filters:
                filters

            },

            async:
              true,


            callback: (response) => {

              const value =
                response?.message ||
                0;


              element.textContent =
                suffix
                  ? `${formatNumber(value)} ${suffix}`
                  : formatNumber(value);


              if (value > 0) {

                element.classList.remove(
                  "zero"
                );

              } else {

                element.classList.add(
                  "zero"
                );

              }

            },


            error: () => {

              element.textContent =
                "0";

              element.classList.add(
                "zero"
              );

            }

          });

        });

    }


    /* =============================
       الأحداث
    ============================= */

    quickActions.addEventListener(
      "click",
      (event) => {

        /* خطوات */

        const toggle =
          event.target.closest(
            "[data-stoggle]"
          );


        if (toggle) {

          event.preventDefault();
          event.stopPropagation();


          const stepsBox =
            toggle.nextElementSibling;


          if (!stepsBox) {
            return;
          }


          const visible =
            stepsBox.style.display !==
            "none";


          stepsBox.style.display =
            visible
              ? "none"
              : "block";


          toggle.textContent =
            visible
              ? showStepsText
              : hideStepsText;


          return;
        }


        /* فتح مستند */

        const route =
          event.target.closest(
            "[data-route]"
          );


        if (
          !route ||
          !window.frappe
        ) {
          return;
        }


        event.preventDefault();


        const doctype =
          route.dataset.route;


        /* تقرير */

        if (
          route.dataset.rpt ===
          "1"
        ) {

          frappe.set_route(
            "query-report",
            doctype
          );

          return;
        }


        /* شجرة */

        if (
          route.dataset.tree ===
          "1"
        ) {

          frappe.set_route(
            "Tree",
            doctype
          );

          return;
        }


        /* قائمة */

        frappe.set_route(
          "List",
          doctype
        );

      }
    );

  }


  /* =========================================================
     11. الفوتر
  ========================================================= */

  function renderFooter() {

    if (!footerEl) {
      return;
    }


    const phoneLabel =
      isArabic
        ? "الهاتف الموحد"
        : "Phone";


    const emailLabel =
      isArabic
        ? "البريد الإلكتروني"
        : "Email";


    const websiteLabel =
      isArabic
        ? "الموقع"
        : "Website";


    footerEl.innerHTML = `

      <div class="erp-footer-inner">


        <div class="erp-footer-item">

          <span class="erp-footer-icon">
            📞
          </span>

          <span class="erp-footer-label">
            ${escapeHtml(phoneLabel)}:
          </span>

          <a
            href="tel:${footerInfo.phone}"
            class="erp-footer-link"
            dir="ltr"
          >
            ${escapeHtml(footerInfo.phone)}
          </a>

        </div>


        <span class="erp-footer-sep">
          |
        </span>


        <div class="erp-footer-item">

          <span class="erp-footer-icon">
            ✉️
          </span>

          <span class="erp-footer-label">
            ${escapeHtml(emailLabel)}:
          </span>

          <a
            href="mailto:${footerInfo.email}"
            class="erp-footer-link"
          >
            ${escapeHtml(footerInfo.email)}
          </a>

        </div>


        <span class="erp-footer-sep">
          |
        </span>


        <div class="erp-footer-item">

          <span class="erp-footer-icon">
            🌐
          </span>

          <span class="erp-footer-label">
            ${escapeHtml(websiteLabel)}:
          </span>

          <a
            href="https://${footerInfo.website}"
            class="erp-footer-link"
            target="_blank"
            rel="noopener"
          >
            ${escapeHtml(footerInfo.website)}
          </a>

        </div>


      </div>

    `;

  }


  /* =========================================================
     12. نص الترحيب
  ========================================================= */

  const welcomeText =
    root.querySelector(
      "[data-welcome-text]"
    );


  const welcomeSub =
    root.querySelector(
      "[data-welcome-sub]"
    );


  if (welcomeText) {

    welcomeText.textContent =
      isArabic
        ? "مرحباً بك في مبتكر ERP"
        : "Welcome to Mubtkir ERP";

  }


  if (welcomeSub) {

    welcomeSub.textContent =
      isArabic
        ? "كل ما تحتاجه لإدارة أعمالك بذكاء وسهولة"
        : "Everything you need to manage your business smartly and easily";

  }


  /* =========================================================
     13. تشغيل الصفحة
  ========================================================= */

  renderStats();

  renderQuickActions();

  renderFooter();

})();

style:
/* =========================================================

   MUBTKIR ERP — SALES WORKSPACE

   Unified Professional Brand Theme

========================================================= */





/* =========================================================

   1. ROOT + BRAND COLORS

========================================================= */



.erp-dashboard-wrapper {

  --brand-primary: #3867AE;

  --brand-secondary: #0F84B5;

  --brand-accent: #0BA1B8;

  --brand-purple: #644DA6;



  --brand-text: #243B63;

  --brand-muted: #66758A;



  --brand-border: rgba(56, 103, 174, 0.22);

  --brand-border-strong: rgba(56, 103, 174, 0.38);



  --brand-soft: rgba(56, 103, 174, 0.07);

  --brand-soft-secondary: rgba(15, 132, 181, 0.07);

  --brand-soft-accent: rgba(11, 161, 184, 0.07);

  --brand-soft-purple: rgba(100, 77, 166, 0.07);



  position: relative;

  isolation: isolate;



  width: 100%;



  padding: 14px 16px 36px;



  overflow: visible;



  color: var(--brand-text);

}





.erp-dashboard-wrapper,

.erp-dashboard-wrapper * {

  box-sizing: border-box;



  font-family:

    "Tajawal",

    "Inter",

    Arial,

    sans-serif !important;

}





/* RTL */



.erp-dashboard-wrapper.erp-dashboard-rtl {

  direction: rtl;

  text-align: right;

}





/* =========================================================

   2. BACKGROUND LOGO

========================================================= */



.erp-dashboard-bg {

  position: absolute;



  top: 150px;

  left: 50%;



  width: 58%;

  max-width: 720px;

  height: auto;



  object-fit: contain;



  transform: translateX(-50%);



  /*

   * وضوح الشعار المائي

   * ارفعها إلى 0.08 إذا أردته أوضح

   */

  opacity: 0.055;



  pointer-events: none;

  user-select: none;



  z-index: 0;

}





/* =========================================================

   3. CONTENT LAYER

========================================================= */



.erp-stats-section,

.erp-quick-actions,

.erp-dashboard-content,

.erp-footer {

  position: relative;

  z-index: 2;

}





.erp-dashboard-content,

.erp-module-section,

.erp-dashboard-grid {

  background: transparent !important;

}





/* =========================================================

   4. STATISTICS GRID

========================================================= */



.erp-stats-grid {

  display: grid !important;



  grid-template-columns:

    repeat(4, minmax(0, 1fr)) !important;



  gap: 14px;



  margin: 18px 0 24px;

}





/* =========================================================

   5. STAT CARD

========================================================= */



.erp-stat-card {

  display: flex;



  align-items: center;



  gap: 12px;



  min-width: 0;



  padding: 16px 18px;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  background:

    var(--fg-color, #ffffff);



  color:

    var(--brand-text) !important;



  box-shadow:

    0 4px 14px rgba(36, 59, 99, 0.06);



  transition:

    transform 0.22s ease,

    border-color 0.22s ease,

    box-shadow 0.22s ease;

}





@media (hover: hover) {



  .erp-stat-card:hover {

    transform:

      translateY(-3px);



    border-color:

      var(--brand-border-strong);



    box-shadow:

      0 10px 26px rgba(36, 59, 99, 0.11);

  }



}





/* =========================================================

   6. STAT ICON

========================================================= */



.erp-stat-icon {

  display: flex;



  align-items: center;

  justify-content: center;



  width: 44px;

  height: 44px;



  flex: 0 0 44px;



  border-radius: 12px;



  background:

    var(--brand-soft);



  font-size: 21px;

}





/* ألوان خلفيات الأيقونات فقط */



.erp-stat-card:nth-child(1)

.erp-stat-icon {

  background:

    var(--brand-soft);

}





.erp-stat-card:nth-child(2)

.erp-stat-icon {

  background:

    var(--brand-soft-secondary);

}





.erp-stat-card:nth-child(3)

.erp-stat-icon {

  background:

    var(--brand-soft-accent);

}





.erp-stat-card:nth-child(4)

.erp-stat-icon {

  background:

    var(--brand-soft-purple);

}





/* =========================================================

   7. STAT INFO

   جميع النصوص بلون موحد

========================================================= */



.erp-stat-info {

  display: flex;



  flex-direction: column;



  gap: 3px;



  min-width: 0;



  color:

    var(--brand-text) !important;

}





/* القيمة */



.erp-stat-value,

.erp-stat-card .erp-stat-value,

.erp-stat-card .erp-stat-info .erp-stat-value {

  color:

    var(--brand-text) !important;



  font-size:

    18px !important;



  font-weight:

    800 !important;



  line-height: 1.3;



  direction: ltr;

}





/* عنوان الإحصائية */



.erp-stat-label,

.erp-stat-card .erp-stat-label,

.erp-stat-card .erp-stat-info .erp-stat-label {

  color:

    var(--brand-text) !important;



  font-size:

    11.5px !important;



  font-weight:

    600 !important;



  line-height: 1.45;

}





/* =========================================================

   8. SECTION

========================================================= */



.erp-quick-actions {

  margin-bottom: 24px;

}





.erp-module-section {

  margin-top: 24px;

}





/* =========================================================

   9. SECTION TITLE

========================================================= */



.erp-section-title {

  position: relative;



  display: flex;



  align-items: center;



  min-height: 36px;



  margin: 0 0 14px;



  padding: 0 0 9px;



  border-bottom:

    1px solid var(--brand-border);



  color:

    var(--brand-text) !important;



  font-size: 18px;



  font-weight: 600;



  line-height: 1.4;

}





.erp-section-title::after {

  content: "";



  position: absolute;



  bottom: -1px;



  width: 52px;

  height: 2px;



  border-radius: 20px;



  background:

    var(--brand-primary);

}





.erp-dashboard-rtl

.erp-section-title::after {

  right: 0;

}





.erp-dashboard-wrapper:not(

  .erp-dashboard-rtl

)

.erp-section-title::after {

  left: 0;

}





/* =========================================================

   10. QUICK ACTIONS GRID

========================================================= */



.erp-quick-grid {

  display: grid !important;



  grid-template-columns:

    repeat(4, minmax(0, 1fr)) !important;



  gap: 12px;

}





/* =========================================================

   11. QUICK BUTTON

========================================================= */



.erp-quick-btn {

  display: flex;



  align-items: center;

  justify-content: center;



  min-height: 48px;



  padding:

    11px 14px;



  border:

    1px solid var(--brand-border);



  border-radius: 10px;



  outline: none;



  background:

    var(--brand-soft);



  color:

    var(--brand-primary) !important;



  font-family: inherit;



  font-size: 15px;



  font-weight: 700;



  line-height: 1.4;



  text-align: center;



  cursor: pointer;



  transition:

    transform 0.18s ease,

    background-color 0.18s ease,

    border-color 0.18s ease,

    color 0.18s ease,

    box-shadow 0.18s ease;

}





/* اختلاف الخلفيات فقط */



.erp-quick-btn:nth-child(2) {

  background:

    var(--brand-soft-secondary);

}





.erp-quick-btn:nth-child(3) {

  background:

    var(--brand-soft-accent);

}





.erp-quick-btn:nth-child(4) {

  background:

    var(--brand-soft-purple);

}





/* توحيد لون الخط */



.erp-quick-btn,

.erp-quick-btn .erp-quick-label {

  color:

    var(--brand-primary) !important;

}





@media (hover: hover) {



  .erp-quick-btn:hover {

    transform:

      translateY(-2px);



    color:

      var(--brand-secondary) !important;



    border-color:

      var(--brand-secondary);



    background:

      rgba(15, 132, 181, 0.10);



    box-shadow:

      0 6px 16px rgba(56, 103, 174, 0.12);

  }



}





.erp-quick-btn:active {

  transform:

    scale(0.98);

}





.erp-quick-label {

  width: 100%;



  white-space: normal;



  text-align: center;

}





/* =========================================================

   12. REPORT CARDS GRID

========================================================= */



.erp-dashboard-grid {

  display: grid !important;



  grid-template-columns:

    repeat(3, minmax(0, 1fr)) !important;



  align-items: start;



  gap: 16px;



  width: 100%;



  overflow: visible;

}





/* =========================================================

   13. REPORT CARD

========================================================= */



.erp-card {

  --erp-accent:

    var(--brand-primary);



  --erp-soft:

    var(--brand-soft);



  position: relative;



  z-index: 1;



  min-width: 0;



  min-height: 74px;

  max-height: 74px;



  padding:

    0 16px;



  overflow: hidden;



  border:

    1px solid var(--brand-border);



  border-radius: 14px;



  background:

    var(--fg-color, #ffffff);



  color:

    var(--brand-text) !important;



  box-shadow:

    0 5px 16px rgba(36, 59, 99, 0.06);



  transition:

    max-height 0.4s ease,

    transform 0.28s ease,

    box-shadow 0.28s ease,

    border-color 0.28s ease,

    padding-bottom 0.28s ease;

}





/* خلفية خفيفة */



.erp-card::before {

  content: "";



  position: absolute;



  inset: 0;



  z-index: 0;



  background:

    var(--erp-soft);



  opacity: 0;



  pointer-events: none;



  transition:

    opacity 0.25s ease;

}





/* الخط السفلي */



.erp-card::after {

  content: "";



  position: absolute;



  right: 0;

  bottom: 0;



  z-index: 4;



  width: 0;

  height: 3px;



  background:

    var(--erp-accent);



  transition:

    width 0.3s ease;

}





.erp-dashboard-wrapper:not(

  .erp-dashboard-rtl

)

.erp-card::after {

  right: auto;

  left: 0;

}





/* =========================================================

   14. CARD BRAND TONES

========================================================= */



.erp-card.tone-0 {

  --erp-accent:

    var(--brand-primary);



  --erp-soft:

    var(--brand-soft);

}





.erp-card.tone-1 {

  --erp-accent:

    var(--brand-secondary);



  --erp-soft:

    var(--brand-soft-secondary);

}





.erp-card.tone-2 {

  --erp-accent:

    var(--brand-accent);



  --erp-soft:

    var(--brand-soft-accent);

}





.erp-card.tone-3 {

  --erp-accent:

    var(--brand-purple);



  --erp-soft:

    var(--brand-soft-purple);

}





.erp-card.tone-4 {

  --erp-accent:

    var(--brand-primary);



  --erp-soft:

    var(--brand-soft);

}





/* =========================================================

   15. CARD OPEN

========================================================= */



.erp-card.is-open {

  z-index: 30;



  max-height: 590px;



  padding-bottom: 15px;



  border-color:

    var(--erp-accent);



  transform:

    translateY(-5px);



  box-shadow:

    0 18px 40px rgba(36, 59, 99, 0.14);

}





.erp-card.is-open::before {

  opacity: 1;

}





.erp-card.is-open::after {

  width: 100%;

}











/* =========================================================

   16. CARD HEADING

========================================================= */



.erp-card-heading {

  position: relative;



  z-index: 2;



  display: flex;



  align-items: center;



  gap: 8px;



  width: 100%;

  height: 72px;



  margin: 0;

  padding: 0;



  border: 0;



  border-bottom:

    1px solid transparent;



  outline: none;



  background:

    transparent;



  color:

    var(--brand-text) !important;



  font-family: inherit;



  text-align: inherit;



  cursor: pointer;



  transition:

    border-color 0.22s ease,

    margin-bottom 0.22s ease;

}





.erp-card.is-open

.erp-card-heading {

  margin-bottom: 10px;



  border-bottom-color:

    var(--brand-border);

}











/* =========================================================

   17. CARD TITLE

========================================================= */



.erp-card-title,

.erp-card .erp-card-title {

  flex: 1;



  min-width: 0;



  color:

    var(--brand-text) !important;



  font-size: 16px;



  font-weight: 800;



  line-height: 1.5;

}





/* =========================================================

   18. CARD CHEVRON

========================================================= */



.erp-card-chevron {

  display: inline-flex;



  align-items: center;

  justify-content: center;



  width: 28px;

  height: 28px;



  flex: 0 0 28px;



  border-radius: 8px;



  background:

    var(--erp-soft);



  color:

    var(--erp-accent) !important;



  font-size: 17px;



  transition:

    transform 0.22s ease;

}





.erp-card.is-open

.erp-card-chevron {

  transform:

    rotate(180deg);

}











/* =========================================================

   19. CARD LINKS

========================================================= */



.erp-card-links {

  position: relative;



  z-index: 2;



  display: grid;



  gap: 5px;



  max-height: 0;



  margin: 0;

  padding: 0;



  overflow: hidden;



  opacity: 0;



  visibility: hidden;



  pointer-events: none;



  transform:

    translateY(-8px);



  transition:

    max-height 0.38s ease,

    opacity 0.2s ease,

    visibility 0.2s ease,

    transform 0.28s ease;

}





.erp-card.is-open

.erp-card-links {

  max-height: 480px;



  overflow-y: auto;



  opacity: 1;



  visibility: visible;



  pointer-events: auto;



  transform:

    translateY(0);

}











/* =========================================================

   20. LINK ROW

========================================================= */



.erp-link-row {

  display: flex;



  align-items: center;



  gap: 6px;



  width: 100%;

}





/* =========================================================

   21. CARD LINK

========================================================= */



.erp-link {

  display: flex;



  align-items: center;



  gap: 7px;



  flex: 1;



  min-width: 0;



  min-height: 36px;



  padding:

    7px 10px;



  border:

    1px solid transparent;



  border-radius: 8px;



  outline: none;



  background:

    transparent;



  color:

    var(--brand-text) !important;



  font-family: inherit;



  font-size: 13px;



  font-weight: 500;



  line-height: 1.45;



  text-align: inherit;



  cursor: pointer;



  transition:

    background 0.16s ease,

    color 0.16s ease,

    border-color 0.16s ease,

    transform 0.16s ease;

}





.erp-link-text {

  flex: 1;



  min-width: 0;



  color:

    inherit !important;

}





.erp-link:hover,

.erp-link:focus {

  border-color:

    color-mix(

      in srgb,

      var(--erp-accent) 28%,

      transparent

    );



  background:

    var(--erp-soft);



  color:

    var(--erp-accent) !important;

}





.erp-dashboard-rtl

.erp-link:hover,



.erp-dashboard-rtl

.erp-link:focus {

  transform:

    translateX(-3px);

}





.erp-dashboard-wrapper:not(

  .erp-dashboard-rtl

)

.erp-link:hover,



.erp-dashboard-wrapper:not(

  .erp-dashboard-rtl

)

