  ];

  /* =========================================================
     8. SHORTCUTS (اختصاراتك — Exact bank_reconciliation.json)
     الالتزام التام بألوان الهوية: Primary #3867AE | Hover #0F84B5
  ========================================================= */
  const shortcuts = [
    {
      name: "Mada Settlement Entry",
      labelAr: "قيد تسوية مدى",
