      type: "report",
      doctype: "Mada Reconciliation Status"
    }
  ];

  /* =========================================================
     9. CARDS & LINKS (Exact bank_reconciliation.json)
     أيقونات معبرة للمربعات دون عشوائية ودون تكرار
  ========================================================= */
  const sections = [
    [
      "Operations & Settlements",
      [
        [
          "Settlements & Terminals",
          "💳",
          [
            "Mada Settlement Entry",
            "Mada Terminal"
          ]
        ],
        [
          "Bank Reconciliation",
          "🏦",
          [
            "Mada Bank Reconciliation"
          ]
        ]
      ]
    ],
    [
      "Settings & Reports",
      [
        [
          "Settings",
          "⚙️",
          [
            "Mada Reconciliation Settings"
          ]
        ],
        [
          "Reports",
          "📊",
          [
            "Mada Reconciliation Status"
          ]
        ]
      ]
    ]
  ];

  /* =========================================================
     10. ITEM GUIDANCE & DESCRIPTIONS (Modal details)
  ========================================================= */
  const itemDescriptions = {
    "Mada Settlement Entry": {
      icon: "💳",
      summaryAr: "إنشاء وتسجيل قيود التسوية البنكية لعمليات مدى ونقاط البيع، وحساب عمولات العمليات وضريبة القيمة المضافة وإيداع الصافي.",
      summaryEn: "Create and record bank settlement entries for Mada and POS payouts, calculating merchant fees, VAT, and net bank deposits.",
      stepsAr: [
        "اضغط «قيد تسوية مدى جديد»",
        "حدد الشركة والحساب البنكي المودع به وتاريخ التسوية",
        "اختر المعرف أو جهاز نقطة البيع المرتبط بالحركة",
        "أدخل إجمالي عمليات المبيعات ونسبة الرسوم المصرفية والضريبة",
        "تحقق من مطابقة المبلغ الصافي ثم اضغط حفظ وتسجيل القيد المحاسبي"
      ],
      stepsEn: [
        "Click «New Mada Settlement Entry»",
        "Select Company, Bank Account, and Settlement Date",
        "Choose Terminal ID or POS register",
        "Enter gross transactions total, merchant fee, and VAT amounts",
        "Verify net deposit amount, then Save and Submit the entry"
      ]
    },
    "Mada Terminal": {
      icon: "📱",
      summaryAr: "تعريف وإدارة أجهزة نقاط البيع (Terminals) وأرقام المعرفات (TID) ومواقع الفروع وربطها بالحسابات البنكية المعتمدة.",
      summaryEn: "Register and manage POS Terminals, Terminal IDs (TID), branch assignments, and linked bank accounts.",
      stepsAr: [
        "اضغط «جهاز مدى جديد»",
        "أدخل رقم معرف الجهاز (Terminal ID) واسم الجهاز",
        "حدد الفرع أو الموقع الفعلي للجهاز والشركة",
        "اربط الجهاز بالحساب البنكي الافتراضي للتسويات",
        "تأكد من تفعيل حالة الجهاز ثم اضغط حفظ"
      ],
      stepsEn: [
        "Click «New Mada Terminal»",
        "Enter Terminal ID (TID) and terminal name",
        "Assign branch, location, and company",
        "Link default settlement Bank Account",
        "Ensure terminal is Active and Save"
      ]
    },
    "Mada Bank Reconciliation": {
      icon: "🏦",
      summaryAr: "استيراد كشوف الحسابات البنكية الإلكترونية وإجراء المطابقة الآلية بين حركات البنك والعمليات المسجلة في النظام.",
      summaryEn: "Import electronic bank statements and perform automated matching between bank statement rows and system transactions.",
      stepsAr: [
        "اضغط «مطابقة بنك مدى جديدة»",
        "اختر الحساب البنكي وفترة المطابقة (من تاريخ / إلى تاريخ)",
        "ارفع ملف كشف الحساب البنكي بصيغة Excel أو CSV",
        "اضغط معالجة الحركات للمطابقة الآلية مع قيود المبيعات والتسوية",
        "راجع الفروقات أو الحركات غير المطابقة ثم اضغط اعتماد"
      ],
      stepsEn: [
        "Click «New Mada Bank Reconciliation»",
        "Select Bank Account and reconciliation period (From / To Date)",
        "Upload bank statement Excel/CSV file",
        "Process automatic transaction matching against recorded sales and settlements",
        "Audit differences or unmatched rows and submit reconciliation"
      ]
    }
  };

  /* =========================================================
     11. FOOTER INFO
  ========================================================= */
  const footerInfo = {
    phone: (window.frappe?.boot?.theme_settings?.phone) || "0115110455",
    email: (window.frappe?.boot?.theme_settings?.email) || "sales@mubtkir.com",
    website: (window.frappe?.boot?.theme_settings?.website) || "www.mubtkir.com",
    labels: {
      phoneEn: "Phone",
      phoneAr: "الهاتف الموحد",
      emailEn: "Email",
      emailAr: "البريد الإلكتروني",
      websiteEn: "Website",
      websiteAr: "الموقع"
    }
  };

  /* =========================================================
     12. MODAL DIALOG (تفاصيل الشاشات والعمليات)
     الخطوات تظهر مباشرة بدون الحاجة للضغط على زر إظهار الخطوات
     وزر فتح الشاشة موجود وواضح في الأسفل
  ========================================================= */
  function showInfoModal(itemName) {
    const desc = itemDescriptions[itemName];
    const title = isArabic ? (translate(itemName) || itemName) : itemName;
    const summary = desc
      ? (isArabic ? desc.summaryAr : desc.summaryEn)
      : (isArabic ? ("إدارة ومتابعة " + title + " وتنفيذ العمليات المرتبطة بها.") : ("Manage and track " + itemName + "."));
    const rawSteps = desc ? (isArabic ? desc.stepsAr : desc.stepsEn) : null;
    const steps = (Array.isArray(rawSteps) && rawSteps.length > 0)
      ? rawSteps
      : (isArabic
          ? [
              "فتح شاشة " + title,
              "إدخال وتعبئة البيانات الأساسية المطلوبة",
              "مراجعة وتدقيق الحقول والتحقق من صحتها",
              "حفظ السجل واعتماد المستند"
            ]
          : [
              "Open " + itemName,
              "Fill in the required information and fields",
              "Review and verify mandatory values",
              "Save and submit the record"
            ]);

    const overlay = document.createElement("div");
    overlay.className = "erp-modal-overlay";
    overlay.setAttribute("dir", isArabic ? "rtl" : "ltr");

    overlay.innerHTML = `
      <div class="erp-modal-box">
        <button type="button" class="erp-modal-close" data-modal-close>✕</button>
        <div class="erp-modal-header">
          <span class="erp-modal-icon">${desc?.icon || "📄"}</span>
          <h3 class="erp-modal-title">${escapeHtml(title)}</h3>
        </div>
        <p class="erp-modal-summary">${escapeHtml(summary)}</p>

        <div class="erp-modal-steps is-shown" data-modal-steps>
          <ol class="erp-modal-steps-list">
            ${steps.map(s => `<li>${escapeHtml(s)}</li>`).join("")}
          </ol>
        </div>

        <div style="margin-top: 18px;">
          <button
            type="button"
            class="erp-quick-btn"
            data-modal-launch
            style="width: 100%; min-height: 42px;"
          >
            <span class="erp-quick-label">${isArabic ? "فتح الشاشة" : "Open Screen"}</span>
          </button>
        </div>
      </div>
    `;

    root.appendChild(overlay);
    setTimeout(() => overlay.classList.add("is-visible"), 10);

    const closeBtn = overlay.querySelector("[data-modal-close]");
    if (closeBtn) closeBtn.addEventListener("click", () => overlay.remove());

    overlay.addEventListener("click", e => {
      if (e.target === overlay) overlay.remove();
    });

    const launchBtn = overlay.querySelector("[data-modal-launch]");
    if (launchBtn) {
      launchBtn.addEventListener("click", () => {
        overlay.remove();
        openRoute(itemName);
      });
    }
  }

  /* =========================================================
     13. RENDER CYCLE
  ========================================================= */
  function renderCycle() {
    if (!cycleSection) return;

    const cardsHtml = cycleCards.map((card, index) => {
      const title = isArabic ? card.labelAr : card.labelEn;
      const desc = isArabic ? card.descAr : card.descEn;

      return `
        <div class="erp-cycle-item">
          <button
            type="button"
            class="erp-cycle-card cycle-tone-${(index % 4) + 1}"
            data-recon-cycle="${index}"
          >
            <span class="erp-cycle-number">${card.step}</span>
            <span class="erp-cycle-card-title">${escapeHtml(title)}</span>
            <span class="erp-cycle-description">${escapeHtml(desc)}</span>
          </button>
          ${index < cycleCards.length - 1 ? `<span class="erp-cycle-arrow">${isArabic ? "←" : "→"}</span>` : ""}
        </div>
      `;
    }).join("");

    cycleSection.innerHTML = `
      <section class="erp-cycle-container">
        <h2 class="erp-section-title erp-cycle-title">
          ${isArabic ? "دورة مطابقة البنك ومدى" : "Bank Reconciliation Cycle"}
        </h2>
        <div class="erp-cycle-grid">
          ${cardsHtml}
        </div>
      </section>
    `;

    cycleSection.addEventListener("click", event => {
      const el = event.target.closest("[data-recon-cycle]");
      if (!el) return;
      const idx = Number(el.getAttribute("data-recon-cycle"));
      const card = cycleCards[idx];
      if (!card) return;

      if (card.action === "new") {
        newDoc(card.doctype);
      } else if (card.action === "report") {
        openRoute(card.report);
      } else {
        openRoute(card.doctype);
      }
    });
  }

  /* =========================================================
     14. RENDER STATS (أرقام إنجليزية ومحاذاة يمين في العربي)
  ========================================================= */
  function renderStats() {
    if (!statsSection) return;

    const cardsHtml = statsCards.map((card, index) => {
      return `
        <div class="erp-stat-card overview-tone-${index + 1}">
          <div class="erp-stat-icon">${escapeHtml(card.short)}</div>
          <div class="erp-stat-info">
            <span class="erp-stat-value" data-recon-stat="${card.id}">0</span>
            <span class="erp-stat-label">${escapeHtml(isArabic ? card.labelAr : card.labelEn)}</span>
          </div>
        </div>
      `;
    }).join("");

    statsSection.innerHTML = `
      <section class="erp-overview-container">
        <h2 class="erp-section-title">${isArabic ? "نظرة عامة" : "Overview"}</h2>
        <div class="erp-stats-grid">${cardsHtml}</div>
      </section>
    `;

    statsCards.forEach(card => {
      Promise.resolve()
        .then(() => card.fetch())
        .then(val => {
          const el = statsSection.querySelector(`[data-recon-stat="${card.id}"]`);
          if (!el) return;
          if (card.currency) {
            el.textContent = formatCurrency(val) + (isArabic ? " ر.س" : " SAR");
          } else {
            el.textContent = formatNumber(val);
          }
        })
        .catch(() => {});
    });
  }

  /* =========================================================
     15. RENDER SHORTCUTS (Exact bank_reconciliation.json order)
  ========================================================= */
  function renderQuickActions() {
    if (!quickActions) return;

    quickActions.innerHTML = `
      <h2 class="erp-section-title">${escapeHtml(isArabic ? "اختصاراتك" : "Your Shortcuts")}</h2>
      <div class="erp-quick-grid">
        ${shortcuts.map((btn, index) => `
          <button
            type="button"
            class="erp-quick-btn"
            data-shortcut-index="${index}"
          >
            <span class="erp-quick-label">${escapeHtml(isArabic ? btn.labelAr : btn.labelEn)}</span>
          </button>
        `).join("")}
      </div>
    `;

    quickActions.addEventListener("click", event => {
      const btnEl = event.target.closest("[data-shortcut-index]");
      if (!btnEl) return;
      const idx = Number(btnEl.getAttribute("data-shortcut-index"));
      const shortcut = shortcuts[idx];
      if (!shortcut) return;

      openRoute(shortcut.doctype);
    });
  }

  /* =========================================================
     16. RENDER SECTIONS & CARDS (Exact bank_reconciliation.json)
     زر تفاصيل يظهر فقط للشاشات والعمليات ويُمنع في التقارير والإعدادات
  ========================================================= */
  function renderSections() {
    if (!content) return;

    content.innerHTML = sections.map((sec, secIndex) => {
      const secTitle = isArabic ? "العمليات والتقارير" : "Operations & Reports";
      const cardsHtml = sec[1].map((card, cardIndex) => {
        const cardTitle = card[0];
        const cardIcon = card[1];
        const items = card[2];

        const linksHtml = items.map(item => {
          const detailText = isArabic ? "تفاصيل" : "Details";
          const showDetails = hasDetailsButton(cardTitle, item);
          const infoBtn = showDetails
            ? `<button type="button" class="erp-info-link" data-info-item="${escapeHtml(item)}">${detailText}</button>`
            : "";

          return `
            <div class="erp-link-row">
              <button
                type="button"
                class="erp-link"
                data-route-name="${escapeHtml(item)}"
              >
                <span class="erp-link-text">${escapeHtml(translate(item))}</span>
                <span class="erp-link-arrow">${isArabic ? "←" : "→"}</span>
              </button>
              ${infoBtn}
            </div>
          `;
        }).join("");

        return `
          <article
            class="erp-card is-open tone-${(secIndex + cardIndex) % 4}"
            data-erp-card
          >
            <button
              type="button"
              class="erp-card-heading"
              data-card-toggle
              aria-expanded="true"
            >
              <span class="erp-icon">${cardIcon}</span>
              <span class="erp-card-title">${escapeHtml(translate(cardTitle))}</span>
              <span class="erp-card-chevron">⌄</span>
            </button>
            <div class="erp-card-links">
              ${linksHtml}
            </div>
          </article>
        `;
      }).join("");

      return `
        <section class="erp-module-section">
          <h2 class="erp-section-title">${escapeHtml(secTitle)}</h2>
          <div class="erp-dashboard-grid">
            ${cardsHtml}
          </div>
        </section>
      `;
    }).join("");

    content.addEventListener("click", event => {
      // Info modal
      const infoBtn = event.target.closest("[data-info-item]");
      if (infoBtn) {
        event.preventDefault();
        event.stopPropagation();
        showInfoModal(infoBtn.dataset.infoItem);
        return;
      }

      // Route button
      const routeBtn = event.target.closest("[data-route-name]");
      if (routeBtn) {
        event.preventDefault();
        openRoute(routeBtn.dataset.routeName);
        return;
      }

      // Card accordion toggle
      const heading = event.target.closest("[data-card-toggle]");
      if (heading) {
        const cardEl = heading.closest("[data-erp-card]");
        if (!cardEl) return;
        const willOpen = !cardEl.classList.contains("is-open");
        cardEl.classList.toggle("is-open", willOpen);
        heading.setAttribute("aria-expanded", willOpen ? "true" : "false");
      }
    });
  }

  /* =========================================================
     17. RENDER FOOTER
  ========================================================= */
  function renderFooter() {
    if (!footerEl) return;
    const labels = footerInfo.labels;

    footerEl.innerHTML = `
      <div class="erp-footer-inner">
        <div class="erp-footer-item">
          <span class="erp-footer-icon">☎</span>
          <span class="erp-footer-label">${escapeHtml(isArabic ? labels.phoneAr : labels.phoneEn)}:</span>
          <a href="tel:${footerInfo.phone}" class="erp-footer-link" dir="ltr">${escapeHtml(footerInfo.phone)}</a>
        </div>
        <span class="erp-footer-sep">|</span>
        <div class="erp-footer-item">
          <span class="erp-footer-icon">✉</span>
          <span class="erp-footer-label">${escapeHtml(isArabic ? labels.emailAr : labels.emailEn)}:</span>
          <a href="mailto:${footerInfo.email}" class="erp-footer-link">${escapeHtml(footerInfo.email)}</a>
        </div>
        <span class="erp-footer-sep">|</span>
        <div class="erp-footer-item">
          <span class="erp-footer-icon">🌐</span>
          <span class="erp-footer-label">${escapeHtml(isArabic ? labels.websiteAr : labels.websiteEn)}:</span>
          <a href="https://${footerInfo.website}" class="erp-footer-link" target="_blank" rel="noopener">${escapeHtml(footerInfo.website)}</a>
        </div>
      </div>
    `;
  }

  /* =========================================================
     18. INIT
  ========================================================= */
  try { renderCycle(); } catch (e) { console.error("Bank Recon Cycle Error:", e); }
  try { renderStats(); } catch (e) { console.error("Bank Recon Stats Error:", e); }
  try { renderQuickActions(); } catch (e) { console.error("Bank Recon Shortcuts Error:", e); }
  try { renderSections(); } catch (e) { console.error("Bank Recon Sections Error:", e); }
  try { renderFooter(); } catch (e) { console.error("Bank Recon Footer Error:", e); }
})();

style:
/* =========================================================
   MUBTKIR ERP — BUYING WORKSPACE
   Unified Professional Brand Theme
   لوحة تحكم قسم المشتريات
========================================================= */


/* =========================================================
   1. ROOT + BRAND COLORS
   ألوان الهوية الرسمية
========================================================= */

.erp-dashboard-wrapper {

  --brand-primary: #3867AE;
  --brand-secondary: #0F84B5;
  --brand-accent: #0BA1B8;
  --brand-purple: #644DA6;

  --brand-text: #243B63;
  --brand-muted: #66758A;

  --brand-border: rgba(56, 103, 174, 0.22);
  --brand-border-strong: rgba(56, 103, 174, 0.38);

  --brand-soft: rgba(56, 103, 174, 0.07);
  --brand-soft-secondary: rgba(15, 132, 181, 0.07);
  --brand-soft-accent: rgba(11, 161, 184, 0.07);
  --brand-soft-purple: rgba(100, 77, 166, 0.07);

  position: relative;
  isolation: isolate;

  width: 100%;

  padding: 14px 16px 36px;

  overflow: visible;

  color: var(--brand-text);
}


/* =========================================================
   2. FONT
========================================================= */

.erp-dashboard-wrapper,
.erp-dashboard-wrapper * {

  box-sizing: border-box;

  font-family:
    "Tajawal",
    "Inter",
    Arial,
    sans-serif !important;
}


/* =========================================================
   3. RTL
========================================================= */

.erp-dashboard-wrapper.erp-dashboard-rtl {

  direction: rtl;
  text-align: right;
}


/* =========================================================
   BACKGROUND
   صورة واحدة في الخلفية بدون تكرار
========================================================= */

.erp-dashboard-bg {
    position: absolute !important;

    top: 50px;
    left: 50%;

    /* حجم الصورة */
    width: 78%;
    max-width: 1200px;

    height: auto;

    transform: translateX(-50%);

    /* الشفافية */
    opacity: 0.03;

    object-fit: contain;

    pointer-events: none;
    user-select: none;

    z-index: 0;
}


/* الحاوية الرئيسية */
.erp-dashboard-wrapper {
    position: relative !important;
    isolation: isolate;
}


/* المحتوى فوق الخلفية */
.erp-purchase-cycle-section,
.erp-stats-section,
.erp-quick-actions,
.erp-dashboard-content,
.erp-footer {
    position: relative !important;
    z-index: 2;
}

/* =========================================================
   المحتوى فوق الخلفية
========================================================= */

.erp-purchase-cycle-section,
.erp-stats-section,
.erp-quick-actions,
.erp-dashboard-content,
.erp-footer {

    position: relative;

    z-index: 2;
}
/* =========================================================
   إبقاء جميع عناصر الداشبورد فوق الخلفية
========================================================= */

.erp-purchase-cycle-section,
.erp-stats-section,
.erp-quick-actions,
.erp-dashboard-content,
.erp-footer {
    position: relative;
    z-index: 2;
}

/* =========================================================
   5. CONTENT LAYER
   جميع المحتويات تظهر فوق الخلفية
========================================================= */

.erp-purchase-cycle-section,
.erp-stats-section,
.erp-quick-actions,
.erp-dashboard-content,
.erp-footer {

  position: relative;

  z-index: 2;
}


.erp-dashboard-content,
.erp-module-section,
.erp-dashboard-grid {

  background: transparent !important;
}


/* =========================================================
   6. SECTION TITLE
========================================================= */

.erp-section-title {

  position: relative;

  display: flex;
  align-items: center;

  min-height: 36px;

  margin: 0 0 16px;

  padding: 0 0 10px;

  border-bottom:
    1px solid var(--brand-border);

  color:
    var(--brand-text) !important;

  font-size: 18px;
  font-weight: 700;

  line-height: 1.4;
}


.erp-section-title::after {

  content: "";

  position: absolute;

  bottom: -1px;

  width: 52px;
  height: 2px;

  border-radius: 20px;

  background: var(--brand-primary);
}


.erp-dashboard-rtl
.erp-section-title::after {

  right: 0;
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-section-title::after {

  left: 0;
}


/* =========================================================
   7. PURCHASE CYCLE SECTION
========================================================= */

.erp-purchase-cycle-section {

  margin: 18px 0 24px;
}


.erp-cycle-container {

  position: relative;

  padding: 18px 18px 20px;

  border:
    1px solid var(--brand-border);

  border-radius: 16px;

  /*
     شبه معتم حتى يبقى الـ Pattern ظاهراً بخفة
  */

  background:
    rgba(255, 255, 255, 0.94);

  box-shadow:
    0 5px 18px rgba(36, 59, 99, 0.06);
}


.erp-cycle-title {

  margin-bottom: 20px;
}


/* =========================================================
   SALES / PURCHASE CYCLE GRID
   توزيع البطاقات على كامل عرض الصفحة
========================================================= */

.erp-cycle-grid {
  display: grid;

  grid-template-columns:
    repeat(5, minmax(0, 1fr));

  gap: 18px;

  width: 100%;

  align-items: stretch;
}


.erp-cycle-item {
  position: relative;

  display: flex;

  width: 100%;

  min-width: 0;
}


/* البطاقة تتمدد حسب عرض العمود */
.erp-cycle-card {
  width: 100%;

  min-width: 0;

  min-height: 180px;
}

/* =========================================================
   9. PURCHASE CYCLE CARD
========================================================= */

.erp-cycle-card {

  --cycle-color:
    var(--brand-primary);

  --cycle-soft:
    var(--brand-soft);

  position: relative;

  display: flex;

  flex-direction: column;

  align-items: center;
  justify-content: flex-start;

  width: 100%;

  min-width: 0;
  min-height: 180px;

  padding: 17px 11px 15px;

  overflow: visible;

  border:
    1px solid var(--brand-border);

  border-radius: 14px;

  outline: none;

  background:
    rgba(255, 255, 255, 0.96);

  color:
    var(--brand-text) !important;

  font-family: inherit;

  text-align: center;

  cursor: pointer;

  transition:
    transform 0.20s ease,
    border-color 0.20s ease,
    box-shadow 0.20s ease;
}


.erp-cycle-card::before {

  content: "";

  position: absolute;

  inset: 0;

  border-radius: inherit;

  background:
    var(--cycle-soft);

  opacity: 0.42;

  pointer-events: none;
}


.erp-cycle-card::after {

  content: "";

  position: absolute;

  right: 0;
  bottom: 0;

  width: 0;
  height: 3px;

  background:
    var(--cycle-color);

  transition:
    width 0.25s ease;
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-cycle-card::after {

  right: auto;
  left: 0;
}


.erp-cycle-card > * {

  position: relative;

  z-index: 2;
}


@media (hover: hover) {

  .erp-cycle-card:hover {

    transform:
      translateY(-4px);

    border-color:
      var(--cycle-color);

    box-shadow:
      0 12px 28px rgba(36, 59, 99, 0.12);
  }


  .erp-cycle-card:hover::after {

    width: 100%;
  }
}


/* =========================================================
   10. CYCLE NUMBER
========================================================= */

.erp-cycle-number {

  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 42px;
  height: 42px;

  flex: 0 0 42px;

  margin-bottom: 14px;

  border-radius: 50%;

  background:
    var(--cycle-color);

  color:
    #ffffff !important;

  font-size: 18px;
  font-weight: 800;

  line-height: 1;

  box-shadow:
    0 5px 14px rgba(36, 59, 99, 0.12);
}


/* =========================================================
   11. CYCLE TITLE
========================================================= */

.erp-cycle-card-title {

  display: block;

  width: 100%;

  margin-bottom: 7px;

  color:
    var(--brand-text) !important;

  font-size: 13.5px;
  font-weight: 800;

  line-height: 1.45;
}


/* =========================================================
   12. CYCLE DESCRIPTION
========================================================= */

.erp-cycle-description {

  display: block;

  width: 100%;

  color:
    var(--brand-muted) !important;

  font-size: 10.5px;
  font-weight: 500;

  line-height: 1.65;
}


/* =========================================================
   13. CYCLE BRAND COLORS
========================================================= */

.erp-cycle-card.cycle-tone-1 {

  --cycle-color:
    var(--brand-primary);

  --cycle-soft:
    var(--brand-soft);
}


.erp-cycle-card.cycle-tone-2 {

  --cycle-color:
    var(--brand-secondary);

  --cycle-soft:
    var(--brand-soft-secondary);
}


.erp-cycle-card.cycle-tone-3 {

  --cycle-color:
    var(--brand-accent);

  --cycle-soft:
    var(--brand-soft-accent);
}


.erp-cycle-card.cycle-tone-4 {

  --cycle-color:
    var(--brand-purple);

  --cycle-soft:
    var(--brand-soft-purple);
}


/* =========================================================
   14. CYCLE ARROW
========================================================= */

.erp-cycle-arrow {

  position: absolute;

  top: 50%;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 20px;
  height: 20px;

  color:
    var(--brand-primary) !important;

  font-size: 20px;
  font-weight: 800;

  line-height: 1;

  opacity: 0.55;

  transform:
    translateY(-50%);

  pointer-events: none;

  z-index: 10;
}


.erp-dashboard-rtl
.erp-cycle-arrow {

  left: -17px;
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-cycle-arrow {

  right: -17px;
}


/* =========================================================
   15. OVERVIEW SECTION
========================================================= */

.erp-stats-section {

  margin: 0 0 24px;
}


.erp-overview-container {

  padding: 18px;

  border:
    1px solid var(--brand-border);

  border-radius: 16px;

  background:
    rgba(255, 255, 255, 0.94);

  box-shadow:
    0 5px 18px rgba(36, 59, 99, 0.06);
}


/* =========================================================
   16. STATS GRID
========================================================= */

.erp-stats-grid {

  display: grid !important;

  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 14px;

  margin: 0;
}


/* =========================================================
   17. STAT CARD
========================================================= */

.erp-stat-card {

  display: flex;

  align-items: center;

  gap: 13px;

  min-width: 0;

  min-height: 88px;

  padding: 16px 18px;

  border:
    1px solid var(--brand-border);

  border-radius: 14px;

  background:
    rgba(255, 255, 255, 0.96);

  box-shadow:
    0 4px 14px rgba(36, 59, 99, 0.05);

  transition:
    transform 0.22s ease,
    border-color 0.22s ease,
    box-shadow 0.22s ease;
}


@media (hover: hover) {

  .erp-stat-card:hover {

    transform:
      translateY(-3px);

    border-color:
      var(--brand-border-strong);

    box-shadow:
      0 10px 26px rgba(36, 59, 99, 0.10);
  }
}


/* =========================================================
   18. STAT ICON
========================================================= */

.erp-stat-icon {

  display: flex;

  align-items: center;
  justify-content: center;

  width: 46px;
  height: 46px;

  flex: 0 0 46px;

  border-radius: 12px;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-size: 11px !important;
  font-weight: 800;

  letter-spacing: 0.4px;
}


.erp-stat-card.overview-tone-1
.erp-stat-icon {

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;
}


.erp-stat-card.overview-tone-2
.erp-stat-icon {

  background:
    var(--brand-soft-secondary);

  color:
    var(--brand-secondary) !important;
}


.erp-stat-card.overview-tone-3
.erp-stat-icon {

  background:
    var(--brand-soft-accent);

  color:
    var(--brand-accent) !important;
}


.erp-stat-card.overview-tone-4
.erp-stat-icon {

  background:
    var(--brand-soft-purple);

  color:
    var(--brand-purple) !important;
}


/* =========================================================
   19. STAT INFO
========================================================= */

.erp-stat-info {

  display: flex;

  flex-direction: column;

  gap: 3px;

  min-width: 0;

  color:
    var(--brand-text) !important;
}


.erp-stat-value,
.erp-stat-card .erp-stat-value {

  color:
    var(--brand-text) !important;

  font-size:
    20px !important;

  font-weight:
    800 !important;

  line-height: 1.3;

  font-variant-numeric: lining-nums tabular-nums !important;
  font-feature-settings: "lnum" 1, "tnum" 1 !important;
}


.erp-stat-label,
.erp-stat-card .erp-stat-label {

  color:
    var(--brand-text) !important;

  font-size:
    12px !important;

  font-weight:
    600 !important;

  line-height: 1.45;
}


.erp-dashboard-rtl .erp-stat-card {
  text-align: right !important;
}

.erp-dashboard-rtl .erp-stat-info {
  direction: rtl !important;
  text-align: right !important;
  align-items: flex-start !important;
}

.erp-dashboard-rtl .erp-stat-value,
.erp-dashboard-rtl .erp-stat-label {
  direction: rtl !important;
  text-align: right !important;
}


/* =========================================================
   20. QUICK ACTIONS
   تم إبقاء تصميم الاختصارات كما كان
========================================================= */

.erp-quick-actions {

  margin-bottom: 24px;
}


/* =========================================================
   21. QUICK ACTIONS GRID
========================================================= */

.erp-quick-grid {

  display: grid !important;

  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 12px;
}


/* =========================================================
   22. QUICK BUTTON
========================================================= */

.erp-quick-btn {

  display: flex;

  align-items: center;
  justify-content: center;

  min-height: 48px;

  padding:
    11px 14px;

  border:
    1px solid var(--brand-border);

  border-radius: 10px;

  outline: none;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-family: inherit;

  font-size: 15px;
  font-weight: 700;

  line-height: 1.4;

  text-align: center;

  cursor: pointer;

  transition:
    transform 0.18s ease,
    background-color 0.18s ease,
    border-color 0.18s ease,
    color 0.18s ease,
    box-shadow 0.18s ease;
}


.erp-quick-btn:nth-child(1) {

  background:
    var(--brand-soft);
}


.erp-quick-btn:nth-child(2) {

  background:
    var(--brand-soft-secondary);
}


.erp-quick-btn:nth-child(3) {

  background:
    var(--brand-soft-accent);
}


.erp-quick-btn:nth-child(4) {

  background:
    var(--brand-soft-purple);
}


.erp-quick-btn,
.erp-quick-btn .erp-quick-label {

  color:
    var(--brand-primary) !important;
}


@media (hover: hover) {

  .erp-quick-btn:hover {

    transform:
      translateY(-2px);

    color:
      var(--brand-secondary) !important;

    border-color:
      var(--brand-secondary);

    background:
      rgba(15, 132, 181, 0.10);

    box-shadow:
      0 6px 16px rgba(56, 103, 174, 0.12);
  }
}


.erp-quick-btn:active {

  transform:
    scale(0.98);
}


.erp-quick-label {

  width: 100%;

  white-space: normal;

  text-align: center;
}


/* =========================================================
   23. MODULE SECTION
========================================================= */

.erp-module-section {

  margin-top: 24px;
}


/* =========================================================
   24. REPORT CARDS GRID
========================================================= */

.erp-dashboard-grid {

  display: grid !important;

  grid-template-columns:
    repeat(3, minmax(0, 1fr)) !important;

  align-items: start;

  gap: 16px;

  width: 100%;

  overflow: visible;
}


/* =========================================================
   25. REPORT CARD
========================================================= */

.erp-card {

  --erp-accent:
    var(--brand-primary);

  --erp-soft:
    var(--brand-soft);

  position: relative;

  z-index: 1;

  min-width: 0;

  min-height: auto;
  max-height: none;

  padding:
    0 16px;

  overflow: visible;

  border:
    1px solid var(--brand-border);

  border-radius: 14px;

  background:
    rgba(255, 255, 255, 0.95);

  color:
    var(--brand-text) !important;

  box-shadow:
    0 5px 16px rgba(36, 59, 99, 0.06);

  transition:
    max-height 0.4s ease,
    transform 0.28s ease,
    box-shadow 0.28s ease,
    border-color 0.28s ease,
    padding-bottom 0.28s ease;
}


.erp-card::before {

  content: "";

  position: absolute;

  inset: 0;

  z-index: 0;

  background:
    var(--erp-soft);

  opacity: 0;

  pointer-events: none;

  transition:
    opacity 0.25s ease;
}


.erp-card::after {

  content: "";

  position: absolute;

  right: 0;
  bottom: 0;

  z-index: 4;

  width: 0;
  height: 3px;

  background:
    var(--erp-accent);

  transition:
    width 0.3s ease;
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-card::after {

  right: auto;
  left: 0;
}


/* =========================================================
   26. CARD BRAND TONES
========================================================= */

.erp-card.tone-0 {

  --erp-accent:
    var(--brand-primary);

  --erp-soft:
    var(--brand-soft);
}


.erp-card.tone-1 {

  --erp-accent:
    var(--brand-secondary);

  --erp-soft:
    var(--brand-soft-secondary);
}


.erp-card.tone-2 {

  --erp-accent:
    var(--brand-accent);

  --erp-soft:
    var(--brand-soft-accent);
}


.erp-card.tone-3 {

  --erp-accent:
    var(--brand-purple);

  --erp-soft:
    var(--brand-soft-purple);
}


.erp-card.tone-4 {

  --erp-accent:
    var(--brand-primary);

  --erp-soft:
    var(--brand-soft);
}


/* =========================================================
   27. CARD OPEN
========================================================= */

.erp-card.is-open {

  z-index: 30;

  max-height: 590px;

  padding-bottom: 15px;

  border-color:
    var(--erp-accent);

  transform:
    translateY(-5px);

  box-shadow:
    0 18px 40px rgba(36, 59, 99, 0.14);
}


.erp-card.is-open::before {

  opacity: 1;
}


.erp-card.is-open::after {

  width: 100%;
}





/* =========================================================
   28. CARD HEADING
========================================================= */

.erp-card-heading {

  position: relative;

  z-index: 2;

  display: flex;
  align-items: center;

  gap: 8px;

  width: 100%;
  height: 72px;

  margin: 0;
  padding: 0;

  border: 0;
  border-bottom:
    1px solid transparent;

  outline: none;

  background:
    transparent;

  color:
    var(--brand-text) !important;

  font-family: inherit;

  text-align: inherit;

  cursor: pointer;

  transition:
    border-color 0.22s ease,
    margin-bottom 0.22s ease;
}


.erp-card.is-open
.erp-card-heading {

  margin-bottom: 10px;

  border-bottom-color:
    var(--brand-border);
}





/* =========================================================
   29. CARD ICON
========================================================= */

.erp-icon {

  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 34px;
  height: 34px;

  flex:
    0 0 34px;

  border-radius:
    9px;

  background:
    var(--erp-soft);

  font-size:
    17px;
}


/* =========================================================
   30. CARD TITLE
========================================================= */

.erp-card-title,
.erp-card .erp-card-title {

  flex: 1;

  min-width: 0;

  color:
    var(--brand-text) !important;

  font-size:
    16px;

  font-weight:
    800;

  line-height:
    1.5;
}


/* =========================================================
   31. CARD CHEVRON
========================================================= */

.erp-card-chevron {

  display: inline-flex;

  align-items: center;
  justify-content: center;

  width: 28px;
  height: 28px;

  flex:
    0 0 28px;

  border-radius:
    8px;

  background:
    var(--erp-soft);

  color:
    var(--erp-accent) !important;

  font-size:
    17px;

  transition:
    transform 0.22s ease;
}


.erp-card.is-open
.erp-card-chevron {

  transform:
    rotate(180deg);
}





/* =========================================================
   32. CARD LINKS
========================================================= */

.erp-card-links {

  position: relative;

  z-index: 2;

  display: grid;

  gap: 5px;

  max-height: none;

  margin: 0;
  padding: 0;

  overflow: visible;

  opacity: 1;
  visibility: visible;

  pointer-events: auto;

  transform: none;

  transition:
    max-height 0.38s ease,
    opacity 0.2s ease,
    visibility 0.2s ease,
    transform 0.28s ease;
}


.erp-card.is-open
.erp-card-links {

  max-height: 480px;

  overflow-y: auto;

  opacity: 1;
  visibility: visible;

  pointer-events: auto;

  transform:
    translateY(0);
}


/* Hover expansion disabled - cards open by default */


/* =========================================================
   33. LINK ROW
========================================================= */

.erp-link-row {

  display: flex;

  align-items: center;

  gap: 6px;

  width: 100%;
}


/* =========================================================
   34. CARD LINK
========================================================= */

.erp-link {

  display: flex;

  align-items: center;

  gap: 7px;

  flex: 1;

  min-width: 0;
  min-height: 36px;

  padding:
    7px 10px;

  border:
    1px solid transparent;

  border-radius:
    8px;

  outline: none;

  background:
    transparent;

  color:
    var(--brand-text) !important;

  font-family: inherit;

  font-size:
    13px;

  font-weight:
    500;

  line-height:
    1.45;

  text-align:
    inherit;

  cursor: pointer;

  transition:
    background 0.16s ease,
    color 0.16s ease,
    border-color 0.16s ease,
    transform 0.16s ease;
}


.erp-link-text {

  flex: 1;

  min-width: 0;

  color:
    inherit !important;
}


.erp-link:hover,
.erp-link:focus {

  border-color:
    var(--brand-border);

  background:
    var(--erp-soft);

  color:
    var(--erp-accent) !important;
}


.erp-dashboard-rtl
.erp-link:hover,

.erp-dashboard-rtl
.erp-link:focus {

  transform:
    translateX(-3px);
}


.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-link:hover,

.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-link:focus {

  transform:
    translateX(3px);
}


/* =========================================================
   35. LINK ARROW
========================================================= */

.erp-link-arrow {

  flex:
    0 0 auto;

  color:
    var(--erp-accent) !important;

  font-size:
    13px;

  font-weight:
    800;

  opacity: 0;

  transition:
    opacity 0.16s ease;
}


.erp-link:hover
.erp-link-arrow,

.erp-link:focus
.erp-link-arrow {

  opacity: 1;
}


/* =========================================================
   36. DETAILS BUTTON
========================================================= */

.erp-info-link {

  flex:
    0 0 auto;

  padding:
    5px 10px;

  border:
    1px solid var(--brand-border);

  border-radius:
    7px;

  outline: none;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-family:
    inherit;

  font-size:
    12px;

  font-weight:
    600;

  cursor: pointer;

  transition:
    border-color 0.16s ease,
    background 0.16s ease,
    color 0.16s ease;
}


.erp-info-link:hover {

  border-color:
    var(--brand-primary);

  background:
    rgba(56, 103, 174, 0.13);

  color:
    var(--brand-primary) !important;
}


/* =========================================================
   37. SCROLLBAR
========================================================= */

.erp-card-links::-webkit-scrollbar {

  width: 5px;
}


.erp-card-links::-webkit-scrollbar-track {

  background:
    transparent;
}


.erp-card-links::-webkit-scrollbar-thumb {

  border-radius:
    10px;

  background:
    var(--brand-primary);
}


/* =========================================================
   38. FOOTER
========================================================= */

.erp-footer {

  --footer-font-size:
    15px;

  margin-top:
    34px;

  padding:
    20px 12px 4px;

  border-top:
    1px solid var(--brand-border);

  color:
    var(--brand-text);
}


.erp-footer-inner {

  display: flex;

  align-items: center;
  justify-content: center;

  flex-wrap: wrap;

  gap:
    10px 22px;

  width: 100%;
}


.erp-footer-item {

  display: flex;

  align-items: center;

  gap: 7px;

  color:
    var(--brand-text) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight:
    600;

  line-height:
    1.6;
}


.erp-footer-icon {

  display: inline-flex;

  align-items: center;
  justify-content: center;

  color:
    var(--brand-primary) !important;

  font-size:
    17px !important;

  line-height:
    1;
}


.erp-footer-label {

  color:
    var(--brand-text) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight:
    700 !important;
}


.erp-footer-link {

  color:
    var(--brand-primary) !important;

  font-size:
    var(--footer-font-size) !important;

  font-weight:
    600 !important;

  text-decoration: none;

  transition:
    color 0.18s ease;
}


.erp-footer-link:hover {

  color:
    var(--brand-secondary) !important;

  text-decoration:
    underline;
}


.erp-footer-sep {

  color:
    var(--brand-border-strong) !important;

  font-size:
    20px;

  font-weight:
    300;

  line-height:
    1;
}


/* =========================================================
   39. MODAL OVERLAY
========================================================= */

.erp-modal-overlay {

  position: fixed;

  inset: 0;

  z-index:
    99999 !important;

  display: flex;

  align-items: center;
  justify-content: center;

  padding: 20px;

  background:
    rgba(12, 27, 54, 0) !important;

  transition:
    background 0.28s ease;
}


.erp-modal-overlay.is-visible {

  background:
    rgba(12, 27, 54, 0.52) !important;
}


/* =========================================================
   40. MODAL BOX
========================================================= */

.erp-modal-box {

  position: relative;

  width: 100%;

  max-width: 480px;
  max-height: 85vh;

  padding:
    28px 24px;

  overflow-y: auto;

  border:
    1px solid var(--brand-border);

  border-radius:
    16px;

  background:
    #ffffff !important;

  box-shadow:
    0 24px 64px rgba(12, 27, 54, 0.28) !important;

  opacity: 0;

  transform:
    translateY(24px)
    scale(0.97);

  transition:
    opacity 0.28s ease,
    transform 0.28s ease;
}


.erp-modal-overlay.is-visible
.erp-modal-box {

  opacity: 1;

  transform:
    translateY(0)
    scale(1);
}


/* =========================================================
   41. MODAL CLOSE
========================================================= */

.erp-modal-close {

  position: absolute;

  top: 12px;

  display: flex;

  align-items: center;
  justify-content: center;

  width: 32px;
  height: 32px;

  border: 0;

  border-radius:
    8px;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-size:
    15px;

  cursor:
    pointer;
}


[dir="rtl"]
.erp-modal-close {

  left: 12px;
}


[dir="ltr"]
.erp-modal-close {

  right: 12px;
}


/* =========================================================
   42. MODAL CONTENT
========================================================= */

.erp-modal-header {

  display: flex;

  align-items: center;

  gap: 11px;

  margin-bottom:
    15px;
}


.erp-modal-icon {

  font-size:
    28px;

  line-height:
    1;
}


.erp-modal-title {

  margin: 0;

  color:
    var(--brand-text) !important;

  font-size:
    18px;

  font-weight:
    800;
}


.erp-modal-summary {

  margin:
    0 0 16px;

  color:
    var(--brand-text) !important;

  font-size:
    13.5px;

  line-height:
    1.75;
}


/* =========================================================
   43. MODAL STEPS BUTTON
========================================================= */

.erp-modal-toggle-steps {

  display: inline-flex;

  align-items: center;

  gap: 6px;

  padding:
    8px 16px;

  border:
    1px solid var(--brand-primary);

  border-radius:
    9px;

  background:
    var(--brand-soft);

  color:
    var(--brand-primary) !important;

  font-family:
    inherit;

  font-size:
    12.5px;

  font-weight:
    700;

  cursor:
    pointer;
}


.erp-modal-toggle-steps:hover {

  background:
    rgba(56, 103, 174, 0.13);
}


/* =========================================================
   44. MODAL STEPS
========================================================= */

.erp-modal-steps {

  max-height: 0;

  overflow: visible;

  opacity: 0;

  margin-top: 0;

  transition:
    max-height 0.38s ease,
    opacity 0.25s ease,
    margin-top 0.25s ease;
}


.erp-modal-steps.is-shown {

  max-height: 500px;

  opacity: 1;

  margin-top:
    15px;
}


.erp-modal-steps-list {

  margin: 0;

  padding:
    0 20px;

  list-style: none;

  counter-reset:
    step-counter;
}


.erp-modal-steps-list li {

  position: relative;

  counter-increment:
    step-counter;

  padding:
    9px 0;

  border-bottom:
    1px solid rgba(56, 103, 174, 0.10);

  color:
    var(--brand-text) !important;

  font-size:
    12.5px;

  line-height:
    1.65;
}


.erp-modal-steps-list li:last-child {

